quests[49902] = { id = 49902, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zum Trübsumpf", description = "Es gibt in Nazmir nur ein sicheres Gebiet, in dem sich dieser Rokhan und Eure anderen Hordenfreunde aufhalten können: im Trübsumpf.\n\nIhr habt Glück, dass Krag'was Höhle dort ganz in der Nähe ist. Wir haben den Trübsumpf als letzten Halt auf unserer Pilgerreise genutzt.\n\nNehmt den Pfad zum Trübsumpf, den ich auf Eurer Karte markiert habe, und sagt unterwegs allen Tortollanern, dass sie uns dort treffen sollen.\n\nSie wollen bestimmt wissen, wie diese Geschichte ausgeht. Wir werden uns auch auf den Weg machen und unterwegs jeden einsammeln, auf den wir treffen.", sourceObjective = "Gewinnt Tortollaner für Eure Sache, während Ihr zum Trübsumpf reist.", completion = "Schön, Euch zu seh'n, {name}. Prinzessin Talanji hat mir alles über Torga un' die Tortollaner erzählt. Schätze, wir hatt'n Glück, wie das alles ausgegang'n is'.\n\nWir wart'n hier auf Verstärkung von der Horde.", sourceObjectiveStatus = "unverified-source-field" }
quests[49905] = { id = 49905, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Überraschende Wendung", description = "Das Ende von Vol'jamba is' gekomm'.\n\nAber seid Euch bewusst, dass er Euch immer noch töt'n kann. Mein und noch mehr Euer Schicksal hängt davon ab, ob Ihr es mit meinem ehemaligen Schüler im Kampf aufnehm'n könnt.\n\nEr wird Masken und Voodoo und alle möglichen fiesen Tricks nutz'n, um Euch ein Ende zu setz'n. Wir haben ihm nur seine Möglichkeit genomm', uns zu täusch'n.\n\nViel Glück. Ich hoffe für Euch, dass Ihr Erfolg ham werdet.", sourceObjective = "Tötet Vol'jamba.", completion = "Der Tod is' ein Werkzeug, {name}. Vergesst das nicht.", sourceObjectiveStatus = "unverified-source-field" }
quests[49908] = { id = 49908, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zurück in Brennadam", description = "Die Naga wurden dank Eurer Hilfe fast komplett ausgelöscht. Sie werden es sich zweimal überlegen, hier noch einmal anzugreifen.\n\nKönnt Ihr nach Brennadam zurückkehren und dem Knappen Augustus III. ausrichten, dass er wieder seinen normalen Posten besetzen kann?", sourceObjective = "Meldet Euch bei Knappe Augustus III. in Brennadam.", completion = "Alles klar! Ich kehre sofort zurück!", sourceObjectiveStatus = "unverified-source-field" }
quests[49917] = { id = 49917, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mit Kaja'mit", description = "Ich wart hier schon 'ne Ewigkeit auf 'ne Audienz beim König, aber er will nich' mit mir red'n! Sein aufgeblas'ner Lakai hier ignoriert mich auch.\n\nIm Lianendorf braut sich 'n Problem zusamm'. Die Horde is' am Hafen gelandet un' 'n paar Goblins ham Wind davon bekomm', wo sich unser alter Kaja'mitsteinbruch befindet. Die sin' so blitzschnell abgehau'n, als ob Todesschwinge persönlich hinter denen her wär.\n\nDiese Mine is' allerdings nich' ohne. Brutal gefährlich. Könnt Ihr vielleicht ins Dorf geh'n un' die Goblins zur Vernunft bring'n?", sourceObjective = "Reist zum Lianendorf.", completion = "Gerade rechtzeitig, Kumpel! Es gibt viel zu tun, falls wir hier in Zuldazar wirklich Kaja'mit finden.", sourceObjectiveStatus = "unverified-source-field" }
quests[49918] = { id = 49918, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Gorillagraben" }
quests[49919] = { id = 49919, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kaja'mittendrin", description = "Kaja'mit! Allein beim Aussprechen des Wortes klingelt es in meinen hübschen Öhrchen.\n\nDie Zandalari saßen die ganze Zeit auf einem riesigen Schatz und haben ihn wegen ein paar sprechenden Gorillas einfach aufgegeben. Nach Goblinrecht gehört er jetzt uns!\n\nMal sehen, wie hoch die Konzentration dieses Vorkommens wirklich ist. Schaut Euch diese Dämpfe mal genauer an, die vom Kaja'mit aufsteigen.\n\nGeht in die Schlucht und platziert meine Scanner an diesen Dampfventilen. Der Rest passiert automatisch.", sourceObjective = "Scannt Kaja'mitdampfventile im Gorillagraben.", completion = "Ich danke Euch! Ihr seid vielleicht ein Idiot... äh ich meine, Idol!\n\nDas Vorkommen ist auf jeden Fall groß genug, dass wir anfangen können. Leider stehen uns diese sprechenden Gorillas im Weg.", sourceObjectiveStatus = "unverified-source-field" }
quests[49920] = { id = 49920, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gorillakriegsführung", description = "Ihr kommt genau zur rechten Zeit. Ich danke Euch für Eure Hilfe.\n\nIm Gorillagraben herrscht kein Frieden mehr. Durch das Kaja'mit sind wir zwar höchst intelligent und beredt geworden, doch damit kam auch der Krieg zu uns.\n\nMeine Brüder gedenken nicht, zu kämpfen. Weder gegen die Zandalaritrolle noch untereinander. Unsere Passivität hat uns jedoch zu Opfern gemacht.\n\nIch bitte Euch, befreit meine Kameraden. Sie sind in der ganzen Schlucht verteilt, eingesperrt in Käfigen und unter Bewachung. Eilt Euch!", sourceObjective = "Rettet 6 friedliebende Gorillas.", completion = "Ich danke Euch, mein Freund. Mit wahrem Heldenmut habt Ihr meinen Brüdern die Freiheit zurückgegeben. Wir sehen uns in Bälde wieder.", sourceObjectiveStatus = "unverified-source-field" }
quests[49922] = { id = 49922, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "König Da'ka", description = "Die Zandalari trauen sich nicht in die Nähe des Gorillagrabens, diese Feiglinge!\n\nDas sind doch nur ein paar sprechende Gorillas. Und ein \"Großa Macka\", wie ihn die Zandalari nennen.\n\nWir müssen einfach nur König Da'ka ausschalten und die Bürger werden uns dafür wahrscheinlich sogar noch in den Himmel loben! Zumindest werden wir das Kaja'mit abbauen dürfen.\n\nIhr könnt es doch locker mit diesem Riesengorilla aufnehmen, oder?", sourceObjective = "Tötet König Da'ka.", completion = "Gut. Ein Pelzträger weniger. Das Kaja'mit ist so gut wie unser!", sourceObjectiveStatus = "unverified-source-field" }
quests[49926] = { id = 49926, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Straße nach Korlach", description = "Lord und Lady Kronsteig sind auf dem Kronsteiganwesen gefangen. Bevor wir zu ihnen können, müssen wir jedoch erst durch die Stadt Korlach hindurch... Und die hat der Herzbannzirkel fest im Griff.\n\nZuallererst sollten wir einen vorgeschobenen Außenposten errichten. Unsere Späher haben entdeckt, dass der Turm bei der Wachmannshöhe nur leicht bewacht ist. Ich empfehle, den Turm zu erobern.\n\nIhr habt jetzt das Kommando, <Inquisitor/Inquisitorin>. Gebt den Befehl und wir reiten los.", sourceObjective = "Trefft Euch mit Marschall Lesner bei der Wachmannshöhe in Drustvar.", completion = "Sehr gut, Ihr seid endlich da.\n\nDieser Turm wacht über Korlach und seine Umgebung. Dem Zirkel scheint er nicht besonders wichtig zu sein, aber uns kann der Turm als wertvoller Stützpunkt dienen.", sourceObjectiveStatus = "unverified-source-field" }
quests[49928] = { id = 49928, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tradition der Leere", sourceObjective = "Trefft Euch mit Alleria Windläufer beim Telogrusriss.", completion = "Obwohl einige noch immer zweifeln, haben Eure Taten bewiesen, dass die Ren'dorei der Allianz ehrenhaft dienen.\n\nEuer Wille ist stark, {name}. Nehmt dieses Geschenk an als Symbol der Mächte, die Ihr beherrscht.", sourceObjectiveStatus = "unverified-source-field" }
quests[49929] = { id = 49929, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aufruf an die Verbündeten", description = "Die Allianz sah sich mit wachsenden Bedrohungen in ganz Azeroth konfrontiert.\n\nWir konnten unsere Freunde nur schützen, wenn wir uns neue Verbündete suchten.\n\nIch wurde zum Botschafter ernannt, um diese Verbündeten zu suchen. Kommt zu unserer Botschaft in Sturmwind. Ich könnte Eure Hilfe gebrauchen.", sourceObjective = "Trefft Aysa Wolkensänger in der Botschaft von Sturmwind.", completion = "Willkommen, {name}. Ich bin froh, zu sehen, dass Ihr dem Ruf gefolgt seid.", sourceObjectiveStatus = "unverified-source-field" }
quests[49930] = { id = 49930, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aufruf an die Verbündeten", description = "Grüße, Champion! Ich wurde zum Botschafter der Horde im diplomatischen Austausch mit all unseren Verbündeten ernannt.\n\nMeine Aufgabe ist es, die aufzusuchen, die das Ideal der Horde verkörpern und mit ihnen über einen Beitritt zu sprechen.\n\nAls <gefeierter Held/gefeierte Heldin> der Horde wäre Eure Unterstützung sehr willkommen! Trefft mich bei der Botschaft in Orgrimmar, wenn Ihr es einrichten könnt.", sourceObjective = "Trefft Ji Feuerpfote bei der Botschaft von Orgrimmar.", completion = "Ah, {name}. Jetzt können wir beginnen.", sourceObjectiveStatus = "unverified-source-field" }
quests[49931] = { id = 49931, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Titanenzorn" }
quests[49932] = { id = 49932, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schluss mit Schlummern", description = "Es gibt da etwas, das Ihr Euch ansehen solltet. Zeit dazu habt Ihr ohnehin, da die Goblins noch nicht bereit sind.\n\nEs gibt hier in der Nähe eine Statue, die in Wirklichkeit aber gar keine Statue ist. Geübte Tortollaneraugen entlarven sie nämlich als deaktivierten Titanenhüter!\n\nDie Sache ist nun, dass dieses Ding Geräusche von sich gibt, seit Ihr Krag'wa geholfen habt.\n\nIch würde wetten, dass Ihr es mit Eurem titanisch aussehenden Amulett wieder zum Laufen bringen könntet. Und mit der Hilfe eines Titanenhüters wären wir im Kampf gegen die Bluttrolle unaufhaltsam.\n\nVersucht also bitte, diesen Titanen neu zu starten!", sourceObjective = "Untersucht den deaktivierten Titanenhüter außerhalb des Trübsumpfs.", progress = "Kern entdeckt. Danke für Bergung.", completion = "Eure Hilfe ist erforderlich. Wir müssen beginnen.", sourceObjectiveStatus = "unverified-source-field" }
quests[49933] = { id = 49933, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Für die Horde", description = "Nach Jahrtausenden der Isolation stehen wir kurz davor, wieder Teil von etwas Größerem zu werden. Unser Bündnis mit der Horde ermöglicht uns einen Neuanfang. Solch eine Chance werden wir nur einmal erhalten-- wir dürfen sie nicht verschwenden.\n\nGeht nach Orgrimmar. Dort beginnt Eure Reise durch Azeroth. Kämpft für dieses Land und sorgt dafür, dass die Shal'dorei einen Platz darin haben.\n\nZeigt der Welt, wer wir sind, {class}. Ehrt die Horde, denn so bringt Ihr auch Suramar Ehre.", sourceObjective = "Trefft Euch mit Botschafter Schwarzwacht in der Botschaft von Orgrimmar.", completion = "Seid Ihr der Neue? Dann soll ich Euch willkommen heißen. Hier, nehmt diesen Brief.\n\n<Schwarzwacht seufzt entnervt.>", sourceObjectiveStatus = "unverified-source-field" }
quests[49935] = { id = 49935, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Titanenhüterreparatur leicht gemacht", description = "Umfassende Systemreparatur in naher Anlage möglich. Vorläufiges Ziel: Reparatur der Hilfssysteme.\n\nScans zeigen drei gefallene Titanenhüter. Kerne bergen. Titanenhüter Hezrel kann Daten aus Kernen abrufen.\n\nTitanenhüter Hezrels Ziel: Neustarten der Hilfssysteme, Erreichen der nahegelegenen Anlage, Wiederherstellen aller Primärsysteme, Eindämmen der Verderbnis.\n\nErgebnis: Verderbnis eingedämmt. Titanenhüter Hezrel kann gegen Bluttrolle helfen.\n\nDefinition für Bluttroll nicht in Datenbanken gefunden.", sourceObjective = "Bergt Titanendatenkerne von gefallenen Titanenhütern.", progress = "Datenkerne einlegen.", completion = "Kerne geborgen. Datenprüfung und -zusammenführung beginnt in Kürze.", sourceObjectiveStatus = "unverified-source-field" }
quests[49937] = { id = 49937, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Überreste bergen", description = "Umgebungsscan zeigt herumwandernde, gerüstete Geister. Absicht: Verteidigung der Anlage, getrieben von Verderbnis.\n\nErkenne Überreste von Titanenpanzerung in Rüstungen der Geister. Erbitte Bergung der Überreste.\n\nTitanenhüter Hezrel kann Titanenpanzerung zerlegen und in Waffe gegen verderbte Truppen umschmieden.", sourceObjective = "Bergt 25 Titanenpanzerungen von Schreckgespenstern von Nazwatha.", progress = "Titanenpanzerung benötigt.", completion = "Titanenpanzerung ausreichend. Leite Schmiedevorgang ein, sobald Funktionalität wiederhergestellt ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[49938] = { id = 49938, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verderbte Erde", description = "Inakzeptables Niveau von Verderbnis in der Nähe entdeckt. Scan zeigt verderbte Vegetation.\n\nVöllige Vernichtung von Verderbnis erforderlich. Erbitte Vernichtung sämtlicher verderbter Vegetation.", sourceObjective = "Vernichtet 12 blutdurchströmte Peitscher.", completion = "Vegetationsverderbnis auf akzeptables Niveau gesenkt.", sourceObjectiveStatus = "unverified-source-field" }
quests[49939] = { id = 49939, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf bald, Schwester", description = "Wir haben den Verteidigern ein wenig Luft verschafft, aber diese Kreaturen belagern weiterhin die Barrikade!\n\nDie Hexe, die hinter dem Angriff steckt, ist vom Schlachtfeld geflohen, als wir ihre Streitkräfte besiegt haben. Ich habe beobachtet, wie sie in das Haus auf dem Hügel ging. Ich werde die Verteidigung hier weiter unterstützen.\n\nIhr müsst in das Haus gehen und die Hexe töten!", sourceObjective = "Tötet Schwester Noella Dornholz.", completion = "Wir hätten nicht mehr lange ausgehalten. Ihr habt uns alle gerettet.", sourceObjectiveStatus = "unverified-source-field" }
quests[49940] = { id = 49940, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Sandnarbenbresche", description = "Hab Gerede über Sand und Schlangen mitgekriegt.\n\nDie Bitte kommt von 'nem kleinen Dorf im Randbereich von Zuldazar. Es hat nur 'n paar Höfe. Ich glaub', es hieß Dol-irgendwas. Weiß nich', wie sie's jetz' nenn'. Schaut doch mal, was da los is'.\n\nKlingenwache Sonji wurd vor 'ner Weile vorausgeschickt. Sie sollt Euch was über die... Situation da erzähl'n könn'.", sourceObjective = "Trefft Klingenwache Sonji an der Sandnarbenbresche.", completion = "Endlich hat Rastakhan jemand'n gesandt!\n\nIch hoffe, Ihr habt keine Angst vor Schlangen, Mann.", sourceObjectiveStatus = "unverified-source-field" }
quests[49941] = { id = 49941, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Knochenanalyse", description = "Von Verderbnis beeinflusste untote Wesen um nahegelegene Anlage entdeckt. Annäherung unmöglich. Planung erforderlich.\n\nBerechnung läuft...\n\nPlanung abgeschlossen. Als reanimierte Monstrositäten bezeichnete, große Kreaturen sind Sammelpunkt der Verderbnis.\n\nAus geborgener Panzerung geschmiedete Titanenwaffe nehmen. Damit Monstrositäten schwächen und Knochen sammeln.\n\nWerde Vorgang zur Zerstörung der Knochen einleiten, um Erschaffung weiterer Monstrositäten zu verhindern.", sourceObjective = "Schwächt reanimierte Monstrositäten mit dem Titanenmanipulator und sammelt 15 ihrer Knochen.", progress = "Knochen von reanimierten Monstrositäten einlegen, um fortzufahren.", completion = "Knochenzerstörung wird eingeleitet.", sourceObjectiveStatus = "unverified-source-field" }
quests[49943] = { id = 49943, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blutspende", description = "Hey, {name}! Ich muss Euch was Aufregendes erzähl'n, aber das muss unter uns Schreibern bleib'n.\n\n<Grazzul nickt Euch zu und holt einen großen Folianten hervor.>\n\nDas is' das blutgebundene Register. Wenn Ihr da Euren Namen reinschreibt, lernt Ihr, wie man \"Blutverträge\" herstellt. Is' mit ein wenig Gefahr verbunden, aber das Risiko lohnt sich!\n\nIch selbst kenn nur einen und es ist immer berauschend, ihn anzuwend'n, weil... also... Ihr werdet schon seh'n.\n\nWas meint Ihr? Interessiert?", sourceObjective = "Unterschreibt das blutgebundene Register.", completion = "Lasst mal seh'n, ob Ihr auch alles richtig gemacht habt.\n\n<Grazzul sucht Eure Unterschrift und nickt.>\n\nJa, sieht ordentlich aus. Der Zauber hat wohl auch schon auf Euch gewirkt.\n\nJetzt seid Ihr würdig, die Herstellung von \"Blutverträgen\" zu erlern'n.\n\nAber passt dabei auf, {name}. Ich hab's schonmal gesagt und ich sag's nochmal. Das sin' gefährliche Spielereien.", sourceObjectiveStatus = "unverified-source-field" }
quests[49944] = { id = 49944, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wissensdrust", description = "Es gibt überall Blutinschriftenmeister, die Euch das Nötige beibring'n können. Als ersten der Meister solltet Ihr Kronah aufsuch'n.\n\nSie is' 'n bisschen... exzentrisch, um es mal milde auszudrück'n. Sie is' eine der wenigen Tortollaner, die ein wenig herumgekommen sin'.\n\nSie hat mir den Blutvertrag beigebracht, den ich heraufbeschwör'n kann!\n\nSie is' gern in der Schmugglerhöhle an der Westküste von Drustvar.", sourceObjective = "Sucht Kronah in der Schmugglerhöhle in Drustvar auf.", completion = "<Kronah betrachtet Euch argwöhnisch von Kopf bis Fuß.>\n\nSagt mal \"Ahhh\", Junge.\n\n<Kronah schaut sich Eure Mundhöhle an.>\n\nIhr habt da ein paar schöne Zähne. Dafür könnte man einen hübschen Preis verlangen. Aber deswegen seid Ihr nicht hier, oder?\n\nNein, Ihr gehört wohl eher zu den Leuten, die sich den Prüfungen der Blutverträge gewachsen fühlen, oder? Also gut.", sourceObjectiveStatus = "unverified-source-field" }
quests[49945] = { id = 49945, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Erste Eindrücke", description = "Mehr kann ich Euch nicht bieten, <junger Schreiber/junge Schreiberin>. Aber Eure Reise ist noch nicht an ihrem Ende angelangt.\n\nGeht zu Eurer Ausbilderin und berichtet ihr von Eurem Erfolg.\n\n<Kronah greift nach einem seltsamen Glas.>\n\nIhr wollt vermutlich keine eingelegten Krokiliskeneier für die Reise mitnehmen, was?\n\n<Als sie das Glas öffnet, verbreitet sich der übelste Gestank, den Ihr je gerochen habt, und Ihr torkelt vor Abscheu zurück.>\n\nNa gut, dann eben nicht. Das ist eh ein etwas gewöhnungsbedürftiger Geschmack. Man muss seine Geschmacksnerven dafür schon ein paar tausend Jahre trainieren.", sourceObjective = "Kehrt zu Zooey Tintenritzel im Tiragardesund zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[49946] = { id = 49946, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Linien im Sand", description = "Mehr kann ich Euch nicht bieten, <junger Schreiber/junge Schreiberin>. Aber Eure Reise ist noch nicht an ihrem Ende angelangt.\n\nWenn Ihr nichts an Reisen auszusetzen habt und an tödlicheren Blutverträgen interessiert seid, müsst Ihr Euch nach Zandalar begeben.\n\nDort müsst Ihr in einer Gegend, die man Vol'dun nennt, einen Sethrak namens Veriss ausfindig machen.\n\n<Kronah greift nach einem seltsamen Gefäß und öffnet es. Der übelste Gestank, den Ihr je gerochen habt, steigt daraus auf und Ihr torkelt angewidert zurück.>\n\nEingelegte Krokiliskeneier mag ich am liebsten. Möchtet Ihr welche?", sourceObjective = "Begebt Euch zu Veriss bei der Terrasse der Ergebenen in Vol'dun und beginnt dort mit Euren Blutprüfungen.", completion = "Ah! Ein neuer Initiand! Woher ich das weiß? Weil Blut an Euren Händen klebt natürlich.\n\n<Auf dem Gesicht des Sethrak erscheint ein verschlagenes Grinsen.>\n\nIch bin Veriss, der örtliche Hüter der Blutverträge von Zandalar.\n\nWenn Ihr Euren Namen darin einschreiben möchtet, muss ich Euch erst um etwas bitten.", sourceObjectiveStatus = "unverified-source-field" }
quests[49947] = { id = 49947, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Durch Blut gebunden", description = "Wie mir scheint, seid Ihr hier fertig, {name}. Danke noch mal, dass Ihr mein Buch zurückgebracht habt. Ihr könnt Euch sicher vorstellen, wie es wirkt, wenn ein Meister so etwas verliert.\n\nAber nur zwischen uns beiden, das war noch der einfache Teil. Wartet nur, bis Ihr den Großmeister trefft.\n\nEure Ausbilderin wird Euch dazu weiter informieren. Viel Glück, {name}!", sourceObjective = "Kehrt zu Zooey Tintenritzel im Tiragardesund zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[49948] = { id = 49948, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der letzte Vers", description = "Jetzt, wo Ihr all die Verträge erlernt habt, müsst Ihr noch eine Sache lern'n.\n\nIhr müsst Euch einen speziellen Federkiel fertig'n, um Verträge zu schreib'n. Und bevor Ihr das Muster dafür erhaltet, müsst Ihr beweis'n, dass Ihr auch würdig seid.\n\nMeister Miju is' dafür verantwortlich. Absolviert seine Prüfung, dann wird er Euch alles Notwendige beibring'n.", sourceObjective = "Begebt Euch zu Miju in (Zone), um mit Eurer letzten Prüfung zu beginnen.", sourceObjectiveStatus = "unverified-source-field" }
quests[49949] = { id = 49949, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unerwünschte Untote", description = "Verderbnis reanimiert tote Kreaturen. Verwandelt sie in Monstrositäten. Muss aufgehalten werden.\n\nTötung aller nicht möglich, aber Reduktion ihrer Anzahl. Reduzierte Anzahl entspricht weniger Verderbnis außerhalb der Eindämmung.\n\nUntote in der Umgebung vernichten. Unterdessen fährt Hüter Hezrel mit Systemneustart fort.\n\nNeustartziel: Daten zur Natur der Verderbnis wiederherstellen.", sourceObjective = "Tötet 15 Untote von Nazwatha.", completion = "Anzahl der Untoten auf akzeptables Niveau reduziert. Benötige weiterhin Methode zur Umgehung der Ziele, um Zugang zur Eindämmung zu erhalten.", sourceObjectiveStatus = "unverified-source-field" }
quests[49950] = { id = 49950, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blutläuterung", description = "<Ihr seht eine merkwürdige Blutkugel, die ein Flüstern von Leid und Zerstörung von sich gibt.\n\nDas muss die Energiequelle für die Verderbnis sein, nach der Hezrel sucht. Scheinbar kann man sie leicht zerstören.\n\nIhr seht überall im Tempelhof weitere Blutkugeln. Vielleicht schwächt ihre Zerstörung die Verderbnis in diesem Gebiet.>", sourceObjective = "Zerstört 4 verderbte Energien.", completion = "Scanner konnten keine Hinweise auf verderbte Energie orten. Muss Reparaturen fortsetzen, darf denselben Fehler nicht zweimal begehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[49952] = { id = 49952, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Essenz von G'huun", description = "Analyse der blutgetränkten Knochen abgeschlossen. Herstellung einer synthetischen Essenz möglich, die der von G'huun ähnelt.\n\nAnwendung der Essenz dauert einen Moment. Ermöglicht Euch, kampflos an den Untoten vorbeizukommen.\n\nEile vonnöten. Beim Tempel noch mehr Diener von G'huun. Müsst hineingelangen, um Eindämmungsprotokolle zu reaktivieren.", sourceObjective = "Lasst Titanenhüter Hezrel die synthetische Essenz anwenden, um einen sicheren Weg vorbei an den Untoten zu ermöglichen.", sourceObjectiveStatus = "unverified-source-field" }
quests[49955] = { id = 49955, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nicht von dieser Welt", description = "Systemwiederherstellung läuft. Daten wiederhergestellt. Quelle der Verderbnis stammt von einem Alten Gott.\n\nMehrere Wesen in der Nähe entdeckt, die die Analyse und Eindämmung der Verderbnis in Nazmir verhindern.\n\nWahrscheinlich Wesen aus der Leere. Wurden durch Verderbnis von Altem Gott angelockt.\n\nErbitte Vernichtung der Leerenwesen. Präsenz der Leere verhindert Systemreparatur.", sourceObjective = "Eliminiert 6 Gesichtslose.", completion = "Anzahl der Diener des Alten Gottes vorübergehend reduziert. Wird ohne geeignete Eindämmung nicht lange anhalten.", sourceObjectiveStatus = "unverified-source-field" }
quests[49956] = { id = 49956, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Leere verboten", description = "Scans zeigen Realitätsfehler nahe der Anlage. Portale direkt in die Leere.\n\nAktuelle Theorie: Quelle für Verderbnis bei Altem Gott. Leere wird von Verderbnis des Alten Gotts angezogen.\n\nPortale müssen versiegelt werden, um durch Verderbnis des Alten Gotts angelockte Wesen einzudämmen.\n\nBereite Ausgabe von Gerät vor. Titanenhüter Hezrel konnte es dank Hilfe bei Systemstart herstellen.\n\nVersiegelung von Leerenportalen damit notwendig, um zu verhindern, dass mehr Leerenwesen in das Gebiet eindringen.", sourceObjective = "Versiegelt 4 Leerenportale.", completion = "Keine Leerenportale mehr entdeckt. Muss fortfahren.", sourceObjectiveStatus = "unverified-source-field" }
quests[49957] = { id = 49957, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Protokollwiederherstellung", description = "Systemreparatur läuft. Benötigte Kernkomponente: Eindämmungsprotokoll. \n\nEindämmungsprotokoll wird Verteidigungssysteme vollständig neu starten. Titanenhüter Hezrel kann somit die Eindämmung ordnungsgemäß wiederherstellen.\n\nScans zeigen große Kreatur innerhalb des Tempels, die Platte mit dem Eindämmungsprotokoll absorbiert hat. Kreatur existiert zwischen Leere und dieser Ebene.\n\nErbitte Vernichtung der Kreatur und Sicherstellung des Protokolls.", sourceObjective = "Besorgt das Eindämmungsprotokoll von Oberanführer Kraxis.", progress = "Bitte Eindämmungsprotokoll vorlegen.", completion = "Eindämmungsprotokoll erhalten. Systemneustart initiiert.", sourceObjectiveStatus = "unverified-source-field" }
quests[49960] = { id = 49960, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Macht sie alle!", description = "Hubert ist ein guter Spürhund, daran besteht kein Zweifel. Aber wenn er erst mal einen Stacheleber entdeckt hat, dann wird er zum störrischsten, wütendsten und hartnäckigsten Hund, den es gibt, und das wird uns noch nützlich werden.\n\nDirekt unter unseren Nasen organisiert und leitet der Vorarbeiter die Tunnelgräber, damit sie maximales Chaos und die größtmögliche Zerstörung anrichten. Wenn Ihr den Vorarbeiter aus dem Verkehr zieht, sollten wir uns wieder freier und sicherer auf den Höfen bewegen können.\n\nHubert sieht ziemlich hungrig aus, meint Ihr nicht auch? Warum nehmt Ihr ihn nicht mit? Vielleicht nimmt er Euch ja sogar Eure Arbeit ab.", sourceObjective = "Besiegt Vorarbeiter Klingenknurr.", completion = "Prima. Ohne den Vorarbeiter sollten die Stacheleber hier deutlich unorganisierter zu Werke gehen und weitaus länger brauchen, um sich zu sammeln.", sourceObjectiveStatus = "unverified-source-field" }
quests[49965] = { id = 49965, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Kriegsrudel", description = "Zul begann einen Coup, aber er eroberte die Pyramide nich' für sich selbst. Er hat sich auch nicht bemüht, jene auf seine Seite zu bring'n, die sich nicht eh schon mit ihm verschwor'n hatten.\n\nDas macht mir mehr Sorgen, als wenn er sein Gesicht in Dazar'alor selbst meißeln würde.\n\nWir müssen herausfind'n, was er plant. Schließt Euch Gonks Anhängern an und reitet zum Tempel des Propheten. Sucht dort Kriegsdruidin Loti auf, um weitere Befehle zu erhalt'n.", sourceObjective = "Reitet mit Gonk zum Tempel des Propheten.", progress = "Erfolgreiche Jagd.", completion = "Blut verlangt nach Blut.", sourceObjectiveStatus = "unverified-source-field" }
quests[49969] = { id = 49969, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Einen Gott erwecken", description = "Seht Ihr die versinkenden Ruinen im Osten? Sie waren vor nicht allzu langer Zeit ein Tempel des Hailoas, Gral.\n\nDie Naga haben seinen Tempel zerstört und stehlen seine Geheimnisse. Wenn sie damit etwas Gutes im Schilde führen, bin ich ein Meeresriese.\n\nEs wäre klug, Gral wissen zu lassen, was sich hier zuträgt. Ich glaube nicht, dass er das gut finden würde.\n\nGral war sehr mächtig, aber gerade sein Wissen über das Meer war unvergleichlich. So jemanden kann man immer auf seiner Seite gebrauchen.\n\nEin wenig frisches, blutiges Nagafleisch lockt ihn vielleicht hervor.", sourceObjective = "Sammelt Brocken Nagafleisch als Opfergabe für Gral.", progress = "<Die Schale strahlt ein Gefühl der Erwartung aus.>", completion = "Das ist mal eine Opfergabe, die meiner Aufmerksamkeit würdig ist!", sourceObjectiveStatus = "unverified-source-field" }
quests[49973] = { id = 49973, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Thalyssras Anwesen", description = "Interessiert Ihr Euch dafür, wie die Nachtgeborenen der Horde beigetreten sind?\n\nWir gewannen ihr Vertrauen, als wir dabei halfen, Suramar von Elisandes tyrannischer Herrschaft und der Brennenden Legion zu befreien.\n\nLordregent Theron lud sie später ein, ihn in Quel'Thalas zu treffen. Lady Liadrin machte sich auf, um der Ersten Arkanistin Thalyssra die Einladung zu überbringen.", sourceObjective = "Trefft Euch mit Lady Liadrin im Anwesen der Ersten Arkanistin in Suramar.", completion = "Die Stadt Suramar bietet einen prächtigen Anblick. Ich hoffe Silbermond stößt bei ihnen nicht auf Enttäuschung.", sourceObjectiveStatus = "unverified-source-field" }
quests[49975] = { id = 49975, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ruhet in den Tiefen", description = "Dieser Abschnitt fließt durch den Schrein des Sturms, bevor er ins offene Meer mündet. Hier werden wir den Seelen der Gefallenen die Freiheit schenken.\n\nWenn unsere Geister den Schrein passieren, sollen sie den Legenden zufolge die großen Segnungsrituale unterstützen, die für alle Schiffe von Kul Tiras zelebriert werden.\n\nSo hören wir vom Haus Sturmsang niemals auf, unserem Volk zu dienen.", sourceObjective = "Schließt das Ritual der Befreiung ab.", progress = "Das Meer verlangt Respekt. Trotzen wir ihm, werden wir seinen Zorn auf uns ziehen.", completion = "Danke, dass Ihr mir bei meiner traurigen Aufgabe helft.", sourceObjectiveStatus = "unverified-source-field" }
quests[49976] = { id = 49976, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gaben des Gefallenen", sourceObjective = "Sprecht mit Mathias Shaw.", completion = "Wenn diese seltsame Substanz so mächtig ist, wie es den Anschein hat, können wir sie nicht in die falschen Hände fallen lassen. Sie werden Euch in Silithus brauchen.", sourceObjectiveStatus = "unverified-source-field" }
quests[49977] = { id = 49977, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rückruf nach Orgrimmar", description = "Der Kriegshäuptling hat um Eure schnellstmögliche Rückkehr nach Orgrimmar gebeten. Eine dringende Angelegenheit erfordert Eure Aufmerksamkeit.\n\nEinzelheiten erläutere ich bei Eurer Ankunft.\n\nTrefft mich in der Nähe des Eingangs zur Feste Grommash. Die Dunkle Fürstin hat Pläne mit Euch, {name}. Ich würde sie nicht warten lassen...", sourceObjective = "Sprecht mit Nathanos Pestrufer.", completion = "Ich habe mich schon gefragt, wo Ihr bleibt, {name}. Die Zukunft der Horde könnte von dem abhängen, was ich Euch zu sagen habe...", sourceObjectiveStatus = "unverified-source-field" }
quests[49980] = { id = 49980, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eindämmungsverfahren", description = "Scans zeigen: Konstrukt ist nicht mehr funktionsfähig. Reparatur unmöglich.\n\nTitanenhüter Hezrels Datenbank vollständig wiederhergestellt. Vermute, Lösung in Daten enthalten.\n\nBrauche Zeit zum Untersuchen der Daten und Finden der Lösung zur Eindämmung von Verderbnis des Alten Gotts.\n\nBitte warten, während Titanenhüter Hezrel in Datenbanken nach Lösung sucht.", sourceObjective = "Beobachtet Titanenhüter Hezrel bei der Suche nach einer Lösung für die Verderbnis des Alten Gottes von Nazmir.", completion = "Neues Protokoll initiiert. Oberste Priorität: Sieg über die Bluttrolle.", sourceObjectiveStatus = "unverified-source-field" }
quests[49981] = { id = 49981, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aufbruch zur Wunde", description = "Ich habe bereits Agenten nach Silithus geschickt, um einen Stützpunkt einzurichten.\n\nSie haben Befehl, die Bewegungen der Horde zu überwachen und so viele Informationen wie möglich zu dieser mysteriösen Substanz zu sammeln.\n\nEiner meiner Kommandanten erwartet Euch dort bereits. Verliert keine Zeit.", sourceObjective = "Trefft Euch mit dem Kommandanten des SI:7 in Silithus.", completion = "Grüße, {name}. Es ist gut, jemandem von Eurem Ansehen hier bei uns in Silithus zu wissen.", sourceObjectiveStatus = "unverified-source-field" }
quests[49982] = { id = 49982, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aufbruch zur Wunde", description = "Das Bilgewasserkartell hat bereits damit begonnen, in Silithus diese mysteriöse Substanz abzubauen.\n\nDer Kriegshäuptling hat darauf bestanden, dass Ihr persönlich die Abbauarbeiten in Silithus beaufsichtigt und jegliche Einmischung von Seiten der Allianz unterbindet.\n\nGallywix schien wenig begeistert darüber, dass die Wahl auf Euch fiel, aber Sylvanas widerspricht man nicht.\n\nIhr müsst sofort nach Silithus aufbrechen. Der Befehlshaber unseres Stützpunkts dort erwartet Euch bereits.", sourceObjective = "Sprecht mit Grol Kriegsklinge in Silithus.", completion = "Grüße, {name}. Ich wurde über Euer Kommen unterrichtet. Der Abbau ist bereits im Gange.", sourceObjectiveStatus = "unverified-source-field" }
quests[49985] = { id = 49985, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rückkehr zum Trübsumpf", description = "Alter Gott G'huun für Zerstörung dieses Siegels verantwortlich. Befiehlt Bluttrollen, die letzte Anlage in Zuldazar zu zerstören.\n\nTitanenhüter Hezrel muss bei der Vernichtung der Bluttrolle helfen. Zuldazarsiegel darf nicht vernichtet und G'huun nicht befreit werden.\n\nMuss Hallen von Atul'Nazman verlassen. Bitte Titanenhüter Hezrel außerhalb des Tempels treffen. Werde Euch bei Rückkehr zum Trübsumpf helfen.\n\nNach Abschluss von Aufgabe muss Titanenhüter Hezrel Verbindung zu anderem Hüter in Eindämmungskammer von G'huun aufbauen.", sourceObjective = "Trefft Titanenhüter Hezrel außerhalb von Atul'Nazman und kehrt zum Trübsumpf zurück.", completion = "Wir haben alles, was wir brauch'n, um die Bluttrolle zu verfolg'n! Wir sollt'n aufbrech'n.", sourceObjectiveStatus = "unverified-source-field" }
quests[49991] = { id = 49991, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fergütung für Federfuß' fabulöses Fallen!", description = "Willkommen in Zuldazar, <mein lieber Freund/meine liebe Freundin>!\n\nIch bin jeden Quadratzentimeter dieser herrlichen Stadt auf eigenen Füßen abgelaufen. Diese Füße sind jetzt ganz schön geschafft!\n\nDeshalb habe ich mich entschlossen, meinen mächtigen Freunden bei der Horde einen Dienst anzubieten: Federfuß' fabulöses Fallen!\n\nIch weiß schon, was Ihr jetzt denkt. Fallen bedeutet normalerweise Schreie, Schmerz und den vorzeitigen Tod.\n\nABER NICHT MIT FEDERFUSS!\n\nGegen eine kleine einmalige Gebühr sorge ich dafür, dass Ihr von dieser Ziggurat immer wohlbehalten und guter Dinge herabschwebt.", sourceObjective = "Zahlt Quinsy Federfuß 100 Gold, dann gewährt er Euch immer, wenn Ihr in der Nähe seid, 'Langsamer Fall'.", sourceObjectiveStatus = "unverified-source-field" }
quests[49994] = { id = 49994, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schlittern mit Stil" }
quests[49995] = { id = 49995, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fabrizierte Fabrikationen", description = "Mit dem Schiff, das wir in der Werft bauten, stimmte was nicht. Ich habe die Pläne nie gesehen, aber ich habe zu meiner Zeit genug Schiffe gebaut, um zu wissen, dass es sich damit anders als sonst üblich verhielt.\n\nSämtliche Dokumente werden in letzter Zeit in den Salzwerken die Straße entlang unter strengster Bewachung verwahrt. Es wimmelt dort nur so von Miliz.\n\nWenn Ihr genug von diesen Dokumenten beschafft, finden wir vielleicht heraus, was Lord Sturmsang und seine Jungs vorhaben.", sourceObjective = "Bergt 8 Kriegsschiffsbaupläne.", progress = "Konntet Ihr dieser Baupläne habhaft werden?", completion = "Ich wusste doch, dass sie sie noch haben! Wenn Ihr jemals etwas verschwinden lassen wollt, Junge, dann solltet Ihr es lieber eigenhändig zerstören.", sourceObjectiveStatus = "unverified-source-field" }
quests[49996] = { id = 49996, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Neubewaffnung", description = "Die Menschen in diesem Tal haben ein aufrichtiges Herz, {name}. Sie brennen darauf, die Kontrolle über ihr Zuhause wiederzuerlangen.\n\nWir müssen ihnen helfen.\n\nDie Salzwerke dort die Straße hoch liefern die meisten der Waffen für Haus Sturmsang. Unsere Bewegung hier könnte die wirklich gut brauchen.\n\nWenn Ihr genug Waffen für alle beschaffen könnt, kann ich unsere Freunde hier in die Grundlagen einweisen.", sourceObjective = "Sammelt 12 sturmverschmolzene Waffen.", progress = "Es gibt noch immer viele, die Lord Sturmsang nicht folgen. Ihnen müssen wir zur Seite stehen.", completion = "Dieses Tal gehört seinen Leuten. Wir müssen kämpfen, um es zu retten!", sourceObjectiveStatus = "unverified-source-field" }
quests[49997] = { id = 49997, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Urteil des Sturms", description = "Als ich während des Rituals meinen Geist den Strömen öffnete, spürte ich die Anwesenheit eines Mitglieds aus dem innersten Kreis Lord Sturmsangs.\n\nWellensprecher Raik. Wenn jemand die verschollene Flotte finden kann, dann er.\n\nIch werde nicht tatenlos zusehen, wie sich meine Brüder gegen unsere eigenen Leute wenden. Verflucht seien die Eide.\n\nWir müssen Raik zwingen, Vernunft anzunehmen.", sourceObjective = "Stellt Wellensprecher Raik.", progress = "Es muss getan werden.", completion = "Ich hätte nie gedacht, dass Raik der Dunkelheit erliegen würde. Die Dinge stehen schlechter, als ich befürchtet hatte.", sourceObjectiveStatus = "unverified-source-field" }
quests[49998] = { id = 49998, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stimmen in der Tiefe", description = "Die anderen sind zum Nebelfluthafen vorausgegangen. Ich bezweifle, dass sie dort herzlich begrüßt werden.\n\nWir sollen uns dort mit ihnen treffen. Es gibt allerdings etwas, das ich vorher erledigen muss.\n\nTrotz Raiks Rückzug spüre ich immer noch eine furchtbare Dunkelheit in der Nähe. Ich wünsche, den Gezeiten zu lauschen, um Antworten zu erhalten. Es wäre mir sehr recht, wenn Ihr Euch mir anschließt, falls uns noch mehr Gefahren über den Weg laufen.", sourceObjective = "Helft Bruder Pike, sein dunkles Omen zu untersuchen.", completion = "Wir müssen den anderen helfen, bevor sie überrannt werden!", sourceObjectiveStatus = "unverified-source-field" }
quests[50000] = { id = 50000, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bestialische Machenschaften" }
quests[50001] = { id = 50001, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hexen behexen", description = "Die Stadt wird überrannt!\n\nDie Wachen sind zurückgefallen und es kommt noch schlimmer. Einige Dorfbewohner sind der Magie der Hexen zum Opfer gefallen. Sie sind kaum mehr als seelenlose Tiere, die blind Befehle befolgen.\n\nWir müssen diese armen Seelen erlösen und die Monster töten, die ihnen das angetan haben.\n\nTut, was Ihr könnt, um die Reihen der Monster in der Stadt auszudünnen!", sourceObjective = "Tötet 15 Dornholzkreaturen und Hexen.", completion = "Gut gemacht. Ihr habt ihre Reihen gelichtet.", sourceObjectiveStatus = "unverified-source-field" }
quests[50002] = { id = 50002, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine äußerst wertvolle Fracht", description = "Wir waren nicht das einzige Schiff in unserem Konvoi, das in solche Not geraten ist. Unser Flaggschiff ist im Osten auf Grund gelaufen. Es hatte äußerst wertvolle Fracht an Bord, und jetzt brauche ich Eure Hilfe, um sie wiederzubeschaffen.", sourceObjective = "Findet die \"wertvolle\" Fracht an der Nebelklippenküste.", completion = "Wer seid Ihr? Wo ist mein Vater? Ich habe Hunger. Kann ich ein Schwert haben? Wo ist mein Papa?!", sourceObjectiveStatus = "unverified-source-field" }
quests[50003] = { id = 50003, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die erste Wache", description = "Wie Ihr seht, hat der Zirkel meine eigenen Wachen in seine Dienste gezwungen. Es schmerzt mich zwar, gegen meine eigenen Leute zu kämpfen, aber die Magie des Zirkels hat sie so weit verderbt, dass sie nicht mehr gerettet werden können.\n\nDer Tod ist die einzige Gnade, die wir ihnen gewähren können.\n\nDie Inquisitoren und ich werden mit dem Regiment, das draußen stationiert ist, schon fertig. Ihr müsst in der Zwischenzeit ihre Anführerin ausfindig machen und töten.\n\nDie Inquisitoren stehen zu Euren Diensten, {class}. Seid Ihr bereit, den Turm zu erobern?", sourceObjective = "Tötet Schwester Adela auf der Wachmannshöhe.", progress = "Auf Euren Befehl greifen wir den Turm an.", completion = "Gut gekämpft, {class}. Der Turm ist unser.\n\nJetzt können wir uns voll auf Korlach konzentrieren.", sourceObjectiveStatus = "unverified-source-field" }
quests[50005] = { id = 50005, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Händchenhalten", description = "Bringt mich sofort zu meinem Vater!\n\nWaaaartet doch! Ihr müsst meine Hand halten...", sourceObjective = "Begleitet Petra zu ihrem Vater.", completion = "Ihr habt mein kostbares kleines Seesternchen gefunden!", sourceObjectiveStatus = "unverified-source-field" }
quests[50009] = { id = 50009, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schiffswrackbergung", description = "An der Nebelklippenküste wimmelt es vor Sirenen und Saurolisken! Räumt sie aus dem Weg und schnappt Euch alles, was es auf den Schiffen noch zu holen gibt." }
quests[50026] = { id = 50026, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rettet unsere Besatzung", description = "Oh, den Sternen sei Dank! Unser Schiff ist auf Grund gelaufen, und unsere Männer brauchen dringend Hilfe.\n\nFindet Henri Hartke beim Schiffswrack am Fuße des Hügels. Er ist zurückgeblieben, um den anderen zu helfen.", sourceObjective = "Findet Henri Hartke an der Nebelklippenküste.", completion = "Wir brauchen Eure Hilfe!", sourceObjectiveStatus = "unverified-source-field" }
quests[50035] = { id = 50035, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bret Test - SQL" }
quests[50036] = { id = 50036, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Waffe aus vergangenen Zeiten", description = "Ich habe das Pergament studiert, das Fräulein Luzilla Euch mitgegeben hat. Ich habe Teile der alten Sprache übersetzt.\n\nSie nannten es \"Flüssiges Feuer\" und man nutzte es, um \"die Drust wegzubrennen\". Mit diesem Grundrezept können wir etwas herstellen, das uns weiterhilft. Das ist ein kompliziertes Rezept, aber rein zufällig habe ich alles, was wir brauchen, um daraus eine wirkungsvolle alchemistische Waffe zu machen!\n\nBei der Herstellung werde ich Eure Unterstützung brauchen. Wärt Ihr so freundlich, mir zu helfen?", sourceObjective = "Helft Meister Eschtal bei der Herstellung eines Tranks des flüssigen Feuers.", progress = "Brauen wir etwas zusammen!", completion = "Wunderbar! Das riecht etwas streng, aber es wird die hölzernen Konstrukte niederbrennen, da bin ich mir sicher! Lasst es uns ausprobieren.", sourceObjectiveStatus = "unverified-source-field" }
quests[50041] = { id = 50041, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Handvoll Geschosse", description = "Seht Ihr das Problem? Nein, offenbar nicht.\n\nDas Problem sind nicht diese verdammten Stacheleber. Stacheleber kann ich den ganzen Tag jagen. Und das tue ich schon mein ganzes Leben lang, seit mein Papi mir meine erste Waffe gegeben hat.\n\nDas Problem ist nur, dass diese Schweine so zäh sind... zäher als zuvor. Sie lassen sich nicht einfach töten wie früher, versteht Ihr? Meine neuen verbesserten Geschosse bleiben einfach in ihnen stecken und sie weigern sich, zu sterben!\n\nHier, nehmt mein Messer. Zieht los, tötet ein paar dieser Stacheleber und holt mir meine Munition zurück. Dann kann ich den Rest erlegen! Und ich werde erst dann aufhören, wenn keiner mehr übrig ist!", sourceObjective = "Sammelt 20 geborgene Azeritmunition.", progress = "Ich habe den Eindruck, dass ich bald mein Geschirr verschießen muss, und ich habe nur drei Sätze. Beeilt Euch lieber!", completion = "Wunderbar! Ich kann weiterschießen, und sie können mir nichts anhaben! Besser geht es nicht!", sourceObjectiveStatus = "unverified-source-field" }
quests[50043] = { id = 50043, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Archäologische Effizienz", description = "Fräulein Tae'shara und ich sind leidenschaftliche Entdecker von verborgenen Geheimnissen. Natürlich teilen wir auch einen tiefen Respekt vor diesem uralten Land.\n\nWenn wir allerdings in ihrem Tempo weitermachen, haben wir keine einzige Entdeckung gemacht, bevor die Allianz uns hier überrennt.\n\nWir müssen unsere Untersuchung beschleunigen.\n\nIn diesen Ruinen ist alles voller Fossilien. Nehmt einen Signalgeber und ruft einen meiner Feger herbei. Er wird die obere Erde abtragen, und Ihr könnt die Proben einfach aufsammeln.\n\nNehmt alles mit, was Ihr findet. Wir setzen es dann später zusammen.", sourceObjective = "Sammelt 50 Fossilienfragmente von Xibala.", progress = "Ich sehe einfach keinen Grund, uns die Hände schmutzig zu machen, {name}.", completion = "Hm. Die sind ein wenig... kaputt, meint Ihr nicht?\n\nNun gut, mit ein wenig Magie ist das kein Problem.", sourceObjectiveStatus = "unverified-source-field" }
quests[50044] = { id = 50044, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Archäologische Effizienz", description = "Ich schätze, ich schulde dem Mädel ihre Knochen, wenn ich noch länger Eure Zeit stehle, und das werde ich definitiv.\n\nGeht in die Ruinen und nutzt diesen Stein hier, um einen meiner polternden Elementarfreunde herbeizurufen. Sie werden jeglichen Dreck zwischen Euch und den Fossilien aus dem Weg sprengen.\n\nWir könnten das auch auf die altmodische Weise machen, aber wollt Ihr wirklich den ganzen Tag im Dreck graben? Natürlich wollt Ihr das nicht.\n\nAcadia wird schon einsehen, dass ein wenig Effizienz nur Vorteile für alle Beteiligten bringt.", sourceObjective = "Nutzt den Elementarbeschwörungsstein, um die Fossile von Xibala freizulegen. Bringt 50 Fossilfragmente von Xibala zurück zu Acadia Tistelstein.", progress = "<Acadia sieht Morgrum verbittert an.>\n\nIch glaube nicht, dass er sich auch nur einen Kieselstein für unsere Expedition interessiert, {name}.", completion = "<Acadia starrt fassungslos auf die Fragmente.>\n\nIch... werde sie einfach... saubermachen. Vielleicht können wir noch etwas davon... retten.\n\nDanke?", sourceObjectiveStatus = "unverified-source-field" }
quests[50046] = { id = 50046, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf Sabotagemission", description = "Die Horde hat mit dem Abbau des mysteriösen Erzes an der großen Wunde keine Zeit verloren.\n\nZu unserem Glück ist die Technologie der Goblins nicht annähernd so fortgeschritten wie die von Gnomeregan! Man braucht nur ein bisschen gutes altes Dynamit, um einen Goblinschredder komplett lahmzulegen.\n\nWas für eine stümperhafte Maschinerie!\n\nNehmt diese Dynamitbündel und befestigt sie an den inaktiven Schreddern rund um das Minenlager.\n\nDas wird diese gierigen Goblins um Wochen zurückwerfen.", sourceObjective = "Platziert 10 Dynamitbündel.", completion = "Solide Arbeit, {name}! Die sabotierten Schredder werden die Abbauarbeiten des Bilgewasserkartells zum Erliegen bringen!", sourceObjectiveStatus = "unverified-source-field" }
quests[50047] = { id = 50047, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gratisproben", description = "Die Krone hat den SI:7 beauftragt, die Abbauarbeiten der Goblins zu infiltrieren und jegliche Informationen zu sammeln, die wir über diese mysteriöse neue Substanz finden können.\n\nMeine Agenten haben das Lager unterwandert, aber die Uhr tickt und wir müssen schnell an ein paar dieser abgebauten Erzproben kommen.\n\nMit anderen Worten: Ich brauche jemanden, der die Dinge etwas direkter handhaben kann. Jemanden, der es schafft, einen Kampf gegen eine Übermacht anzuzetteln und es dort lebend rausschafft.\n\nBringt die Erzproben zur Analyse zu Khargus Zasterstein, wenn Ihr zurückkommt.", sourceObjective = "Sammelt 8 Proben des mysteriösen Erzes.", progress = "Was habt Ihr für mich?", completion = "So etwas habe ich noch nie gesehen... Ich fange gleich mit der Untersuchung an!", sourceObjectiveStatus = "unverified-source-field" }
quests[50048] = { id = 50048, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Brodelnde Küste", description = "Wir haben Berichte über eine Insel vor der Küste von Silithus erhalten, auf der es Azerit im Übermaß geben soll.\n\nEs ist entscheidend, dass wir die Insel sichern, bevor die Horde von ihrer Existenz erfährt.\n\nMeister Mathias Shaw leitet das Expeditionsteam persönlich und möchte, dass Ihr Euch zum Dienst meldet. Viel Glück!", sourceObjective = "Schließt das Schlachtfeld \"Brodelnde Küste\" ab.", sourceObjectiveStatus = "unverified-source-field" }
quests[50049] = { id = 50049, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Perspektive des Sprechers", description = "Sargeras hat eine Narbe auf unserer Welt hinterlassen, {name}. Eine Narbe, die nicht schnell verheilen wird...\n\nEs scheint, die Narben zwischen der Allianz und der Horde verheilen ähnlich schwer.\n\nZu viele Leben wurden bereits geopfert im Kampf gegen die Zerstörung von Azeroth. Ich werde nicht zulassen, dass wir noch mehr verlieren.\n\nBevor Ihr geht, habe ich noch ein Anliegen: Bitte bringt diesen Brief zu Magni Bronzebart. Er ist in Silithus auf der Suche nach einer Möglichkeit, die Wunde zu heilen.\n\nDer Brief enthält potenziell wertvolle Informationen für ihn.", sourceObjective = "Bringt Khadgars Brief zu Magni Bronzebart in Silithus.", completion = "Danke, dass Ihr mir Khadgars Brief gebracht habt. Ich werde Zeit brauchen, über seine Idee nachzudenken. Wenn das alles zutrifft, gibt es vielleicht einen Weg für uns, Azeroth zu retten... aber zu einem hohen Preis.", sourceObjectiveStatus = "unverified-source-field" }
quests[50052] = { id = 50052, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Es hat sich ausspioniert", description = "Hey {name}, bin ich froh, dass Ihr hier seid.\n\nMir ist das hier alles über den Kopf gewachsen. Killerkäfer, eine seltsame Substanz... dieses RIESENSCHWERT, das da im Boden steckt... Ich habe gar kein gutes Gefühl, was diese Gegend angeht.\n\nUnd als ob das noch nicht ausreicht, erhalte ich jetzt auch noch Berichte, dass Spione der Allianz in unserem Lager ihr Unwesen treiben.\n\nJetzt mal ehrlich, die Dunkle Fürstin hat Pläne mit diesem mysteriösen Erz und ich werde nicht derjenige sein, der ihr dabei in die Suppe spuckt; wenn Ihr versteht, was ich meine.\n\nBegebt Euch zum Minenlager und kümmert Euch um diese SI:7-Spione, bevor sie uns noch die ganze Operation sabotieren!", sourceObjective = "Tötet 10 Agenten des SI:7 in Silithus.", completion = "Das habt Ihr gut gemacht, {name}... Die Krise hätten wir überstanden. Wir sollten aber besser die Augen nach ihrer Verstärkung offen halten.\n\nWenn dieses Zeug so wertvoll ist, wie Gallywix behauptet, dürfte es hier in Kürze von Allianz nur so wimmeln.", sourceObjectiveStatus = "unverified-source-field" }
quests[50053] = { id = 50053, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf der faulen Haut", description = "Ich bin schon lange genug dabei, um zu wissen, dass man einem Goblin nicht die Arbeit eines Orcs überlassen kann. \n\nGallywix und sein Kartell mögen dem Kriegshäuptling dienen, aber wir sollten sie lieber im Auge behalten, wenn wir hier vorankommen wollen!\n\nIch habe bereits mit angesehen, wie einige der Arbeiter herumbummeln und faulenzen. Die Horde duldet keine Faulheit!\n\nGeht und erinnert diese faulen Schürfer daran, wo ihr Platz ist!", sourceObjective = "Motiviert 10 faule Schürfer.", completion = "Hmpf! Ich hoffe, Ihr habt Euch nicht zurückgehalten. Wenn es nach mir ginge, hätten sie mehr als eine leichte Abreibung bekommen!", sourceObjectiveStatus = "unverified-source-field" }
quests[50054] = { id = 50054, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Brodelnde Küste", description = "Wir haben Berichte über eine Insel vor der Küste von Silithus erhalten, auf der es Azerit im Übermaß geben soll.\n\nEs ist entscheidend, dass wir die Insel sichern, bevor die Allianz von ihrer Existenz erfährt.\n\nNathanos Pestrufer leitet das Expeditionsteam persönlich und möchte, dass Ihr Euch zum Dienst meldet. Geht mit Ehre!", sourceObjective = "Schließt das Schlachtfeld \"Brodelnde Küste\" ab.", sourceObjectiveStatus = "unverified-source-field" }
quests[50055] = { id = 50055, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Perspektive des Sprechers", description = "Sargeras hat eine Narbe auf unserer Welt hinterlassen, {name}. Eine Narbe, die nicht schnell verheilen wird...\n\nEs scheint, die Narben zwischen der Allianz und der Horde verheilen ähnlich schwer.\n\nZu viele Leben wurden bereits geopfert im Kampf gegen die Zerstörung von Azeroth. Ich werde nicht zulassen, dass wir noch mehr verlieren.\n\nBevor Ihr geht, habe ich noch ein Anliegen: Bitte bringt diesen Brief zu Magni Bronzebart. Er ist in Silithus auf der Suche nach einer Möglichkeit, die Wunde zu heilen.\n\nDer Brief enthält potenziell wertvolle Informationen für ihn.", sourceObjective = "Bringt Khadgars Brief zu Magni Bronzebart in Silithus.", progress = "Was habt Ihr für mich, {class}?", completion = "Danke, dass Ihr mir Khadgars Brief gebracht habt. Ich werde Zeit brauchen, über seine Idee nachzudenken. Wenn das alles zutrifft, gibt es vielleicht einen Weg für uns, Azeroth zu retten... aber zu einem hohen Preis.", sourceObjectiveStatus = "unverified-source-field" }
quests[50056] = { id = 50056, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Ruf des Sprechers", sourceObjective = "Trefft Euch mit Magni Bronzebeard an der Wunde in Silithus.", sourceObjectiveStatus = "unverified-source-field" }
quests[50057] = { id = 50057, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Macht in unseren Händen", sourceObjective = "Geht zum Schwert in Silithus und kanalisiert seine Macht in Euer Artefakt.", sourceObjectiveStatus = "unverified-source-field" }
quests[50058] = { id = 50058, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Hexenhaustier", description = "Ich habe sie gesehen! Die Hexe!\n\nSie kommt von Zeit zu Zeit in die Höhle, um nach ihrem Haustier zu sehen. Ich habe noch nie so eine große Spinne gesehen!\n\nSie verbreitet ihren Zauber, verflucht alle Tiere hier im Wald und befiehlt ihnen, uns anzugreifen.\n\nDie Brutmutter hat jede Menge Eier gelegt. Wenn die ausschlüpfen, wird es hier noch viel mehr von diesen besessenen Bestien geben!\n\nWenn Ihr sie tötet, könnt Ihr vielleicht diesen Befall aufhalten.", sourceObjective = "Tötet die Mooszahnmatriarchin.", sourceObjectiveStatus = "unverified-source-field" }
quests[50059] = { id = 50059, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nichts gehört", description = "Sobald diese Schlangenweiber auftauchen, verlieren alle den Verstand! Alle meine Männer sind diesen Dingern Hals über Kopf verfallen. Ich persönlich weiß gar nicht, was sie an ihnen finden. Ich meine, ich verstehe ja ihren Reiz, aber Flügel als Arme und Schlangenschwänze? Damit kann ich nichts anfangen.\n\nEin kapitales Exemplar von ihnen haust in einer Höhle östlich von hier. Die Freier stehen Schlange bei ihr. Sie müssen zurück an die Arbeit. Also verpasst ihr eine und bringt sie alle hierher zurück.", sourceObjective = "Tötet Anthemusa.", completion = "Ich dachte mir, wenn ich sie schon nicht schlagen kann, schließe ich mich ihnen an! Die da drüben scheint noch zu haben zu sein. Glaubt Ihr, sie würde mit mir gehen?\n\nOh, und danke, dass Ihr alle zurück auf ihre Posten geholt habt. Wir haben jede Menge aufzuräumen.", sourceObjectiveStatus = "unverified-source-field" }
quests[50063] = { id = 50063, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mit Feuer bekämpfen", description = "Ausgezeichnet! Mit diesen hübschen Fläschchen flüssigen Feuers im Arsenal gibt es eigentlich nur noch eines zu tun:\n\nProbieren wir sie aus!\n\nEinige dieser großen Monstrositäten treiben sich in den Wäldern oberhalb meiner Hütte herum. Das wären doch die perfekten Probanden für unser kleines alchemistisches Experiment, meint Ihr nicht auch?", sourceObjective = "Testet die Fläschchen flüssiges Feuer an 3 Dornholzbollwerken.", completion = "Ich wollte sie aufhalten, jedoch vergebens. Sie haben Meister Eschtal in die Wälder entführt!", sourceObjectiveStatus = "unverified-source-field" }
quests[50064] = { id = 50064, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geht nicht in den Keller", description = "Wir haben alles abgesucht. Also <schluck> alles außer dem Keller.\n\nA-a-aber Papa hat gesagt, da darf ich nicht runter.\n\nDa ist es dunkel, sagt er, und gruselig, und gefährlich alleine... Ich könnte da unten sogar von einem Waber aufgefressen werden!\n\nIch weiß zwar nicht, was das ist, aber ich will nicht aufgefressen werden!\n\nKönnt Ihr bitte vorausgehen, {name}?", sourceObjective = "Betretet den Keller.", completion = "Der Waber! Ich habe ihn gesehen! Papa hat ihn sich nicht ausgedacht!!", sourceObjectiveStatus = "unverified-source-field" }
quests[50065] = { id = 50065, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Grund zu bleiben", description = "<Ihr lest eine Taschenuhr vom Boden auf. Sie ist zwar schmutzig, aber funktionstüchtig und scheint sorgsam behandelt worden zu sein.\n\nVielleicht gibt es noch mehr Gegenstände, die Goldfeld nicht mehr einsammeln konnte, bevor er sich in seinem Haus verschanzen musste. Er wäre gewiss dankbar, wenn Ihr sie ihm brächtet.>", sourceObjective = "Durchsucht Goldfelds Bauernhof nach weiteren Andenken.", progress = "Zum letzten Mal: Ich gehe nicht! Ich war zuerst hier. Sollen SIE doch gehen!", completion = "Ihr... Ihr habt sie gefunden. Ich...", sourceObjectiveStatus = "unverified-source-field" }
quests[50069] = { id = 50069, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Goldfelds Krieg", description = "Ich gehe nicht. Ich werde niemals gehen.\n\nDiese Stacheleber... Sie haben sie getötet. Ich gab ihr die Uhr und sagte ihr, sie solle sich beeilen... sich den Jungen schnappen und zum Haus gehen, während ich die Waffe hole...\n\n<Goldfeld kann die Tränen kaum unterdrücken.>\n\nIch werde nicht gehen. Unsere Familie hat hier ihre Wurzeln. Sie würden wollen, dass ich bleibe. Versteht Ihr nicht? Das ist unsere Farm. Mein Junge... Er wollte in die Miliz eintreten. Ich hatte ein Schwert für ihn gefertigt...\n\n<Goldfeld holt tief Luft.>\n\nJetzt wisst Ihr Bescheid. Helft mir, meine Farm zurückzuerobern. Schnappt Euch eine Waffe und lasst uns jeden einzelnen töten.", sourceObjective = "Besiegt die Eindringlinge der Stacheleber.", progress = "Das ist MEIN Zuhause!", completion = "Es ist vollbracht. Meine Familie ist gerächt.", sourceObjectiveStatus = "unverified-source-field" }
quests[50070] = { id = 50070, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Detektiv Mildenhall", description = "Hmm... Okay, okay, lasst uns nachdenken.\n\nWenn Ihr mein Papa wärt und versehentlich einen Haufen Honigmonster losgelassen hättet, was würdet Ihr dann machen?\n\nHmm, na gut, Ihr würdet sie wahrscheinlich alle aufmischen, aber mein Vater würde sicher wegrennen.\n\nWenn er es so eilig hatte, hat er hier bestimmt etwas vergessen.", sourceObjective = "Durchsucht die Metbrauerei Mildenhall nach Hinweisen.", progress = "Habt Ihr noch etwas gefunden?", completion = "Hm... Wir haben überall gesucht.", sourceObjectiveStatus = "unverified-source-field" }
quests[50071] = { id = 50071, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Für das Licht!", description = "Die Lichtgeschmiedeten werden sich der Allianz mit Freuden anschließen.\n\nUnsere Sache ist nun die Eure, {name}.\n\nKehren wir nach Sturmwind zurück. Hauptmann Fareeya wird zu unserem Volk sprechen.", sourceObjective = "Kehrt nach Sturmwind zurück und sprecht mit Aysa Wolkensänger, um das Ende dieser Geschichte zu hören.", completion = "Die Geschichten der Lichtgeschmiedeten hallen durch die Straßen Sturmwinds. Eine Armee von Elitesoldaten, gegründet für den Kampf gegen die Legion... sie werden zu unseren stärksten Verbündeten gehören.", sourceObjectiveStatus = "unverified-source-field" }
quests[50074] = { id = 50074, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Brutalitätsschub", description = "Die Aggressionsformel ist fertig und Ihr müsst sie Ben'jin injizieren.\n\nLasst uns der Welt und dem Hexendoktor beweisen, dass akribisch erforschte, übertrieben mächtige, doppelt verblindete, penibel begutachtete Supergoblinwissenschaft der genialste Weg für, äh, so ziemlich alles ist!", sourceObjective = "Verabreicht die Aggressionsformel Ben'jin dem Sanftmütigen.", progress = "Ganz schön spannend, findet Ihr nicht?", completion = "Ich habe immerhin Momente lang an der Formel gearbeitet! Sie hätte funktionieren müssen! Diese Brutosaurier sterben doch nur aus, weil sie sich unvernünftigerweise der Wissenschaft widersetzen!", sourceObjectiveStatus = "unverified-source-field" }
quests[50076] = { id = 50076, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sammeln der Krieger", description = "Dank Euch und der Horde ham wir so viel erfahren und sind so weit gekommen, aber das wird alles wertlos sein, wenn die Bluttrolle uns hier besieg'n.\n\nJeder von uns hat alles gegeb'n, seit wir in diesen verfluchten Sumpf vorgedrung'n sind. Es blieb nich' mal Zeit zum Schlafen oder zum Essen. Wir haben hier die stärksten und besten Soldaten, die man sich nur vorstell'n kann, aber auch die haben ihre Grenzen.\n\nWir müssen sie dran erinnern, wofür wir kämpf'n!", sourceObjective = "Läutet den uralten Gong.", completion = "Wir sind jetzt bereit. Unser Angriff auf die Bluttrolle kann losgeh'n!", sourceObjectiveStatus = "unverified-source-field" }
quests[50078] = { id = 50078, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unvergängliche Totems", description = "Die Bluttrolle liefern uns 'nen erbitterten Kampf. Die erweck'n ihre Toten und schick'n sie gegen uns!\n\nIhre Totenbeschwörer erweck'n die Toten mithilfe von Totems, die von Blutmagie gespeist werd'n. Wenn wir die zerstör'n, wird das unsren Truppen etwas Luft verschaff'n.", sourceObjective = "Zerstört 3 Totems der Wiederbelebung.", progress = "Warum nervt Ihr mich, wenn diese Totems noch überall herumsteh'n?", completion = "Gute Arbeit. Das sollte es uns etwas leichter mach'n.", sourceObjectiveStatus = "unverified-source-field" }
quests[50079] = { id = 50079, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Bombe macht bumm", description = "Seht Euch das an... Diese Bluttrolle haben sich in ihrer Festung ziemlich gut verschanzt. Mehrere Verteidigungslinien, ein Haufen Ausrüstung. Die sind bestens ausgestattet.\n\nSie erwart'n aber keinen Angriff von uns. Sie tun mir fast schon leid!\n\nFang'n wir mal ganz gemütlich damit an, ihnen zu zeigen, was wir von ihren Barrikaden halt'n. Hier, nehmt diese Rauchgranaten und markiert sie damit. Ich bin gespannt, was sie zu unsrem schicken Sprengstoff sag'n werden!", sourceObjective = "Fordert Artillerieschläge auf die Barrikaden der Bluttrolle in Zul'Nazman an.", completion = "Gute Arbeit! Jetzt könn' wir weiter in die Höhle des Bösen vorstoß'n.", sourceObjectiveStatus = "unverified-source-field" }
quests[50080] = { id = 50080, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Plünderer ausplündern" }
quests[50081] = { id = 50081, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Weg des Schmerzes", description = "Meine Leute werd'n immer noch verschleppt und ins Dorf der Bluttrolle gebracht, um sie dort in dunklen Ritualen zu opfern.\n\nWenn Ihr weitergeht, könnt Ihr einige Gefangene seh'n, die den Weg nich' überlebt ham. Ich kann ihre Todesschreie während der abscheulichen Rituale der Bluttrolle immer noch hör'n.\n\nWir können meine Soldaten nich' einfach im Sumpf sterb'n lass'n, {name}!\n\nNehmt diese Verbände an Euch und rettet so viele Zandalari, wie Ihr da unten find'n könnt.", sourceObjective = "Rettet 6 verletzte Soldaten der Zandalari.", progress = "Konntet Ihr den andren helf'n?", completion = "Unsre Soldaten werd'n jetzt stärker, weiser und vor allem lebendig nach Hause zurückkehr'n.\n\nIch dank Euch im Namen der Zandalari.", sourceObjectiveStatus = "unverified-source-field" }
quests[50082] = { id = 50082, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gelegenheit macht Ziele", description = "Unser Wirk'n hier is' offensichtlich nicht unbemerkt geblieb'n, {name}. Ich spür 'ne dunkle Macht vor uns.\n\nAteena kommt!\n\nDas is' unsre Chance! Wenn wir jetzt zuschlag'n, könn' wir den Bluttroll'n 'nen heftigen Schlag versetz'n!\n\nWir müss'n los!", sourceObjective = "Tretet der Großen Mutta Ateena gegenüber.", completion = "Sie ist um einiges stärker, als ich erwartet hätte. Aber wir hab'n auch noch ein paar Asse im Ärmel!\n\nLasst uns Eure Kanone aufstell'n und sehen, was sie anricht'n kann.", sourceObjectiveStatus = "unverified-source-field" }
quests[50083] = { id = 50083, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Kroggmutter", description = "Egal, was wir mach'n, solang die Bluttrolle hier im Dorf sin', stell'n sie 'ne Gefahr dar.\n\nUn' diese Gefahr müss'n wir ausschalt'n!\n\nAmaka is' mit Abstand der stärkste Bluttroll, den ich je geseh'n hab. Sie verfüttert die Leichen der Zandalari an ihre jung'n Kroggs, damit sie groß, fett un' tödlich werd'n. Jetz' is' die Zeit der Rache gekomm'. Un' wir werd'n ihre Klein' geg'n sie einsetz'n.\n\nAuf jetz'! Tötet 'nen Krogg un' schneidet ihm die Giftdrüsen ausm Bauch. Damit könn' wir Amaka schwäch'n un' sie endlich abmurks'n.", sourceObjective = "Beschafft eine Krogggiftdrüse und tötet Amaka die Kroggmutter.", completion = "Gut gemacht, {name}! \n\nDer Tod von einem von ihr'n Generälen wird den Bluttrollen 'nen heftigen Schlag verpass'n. Jetz' dürf'n wir nich' nachlass'n un' müss'n dranbleib'n!", sourceObjectiveStatus = "unverified-source-field" }
quests[50084] = { id = 50084, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf die Beine, Soldat", description = "Ich dacht mir, dass einige von den Kämpfern, die wir aufm Weg treff'n, sicher auf Rache sinnen. Deshalb hab ich 'n paar Waffen mehr mitgenomm'. Man weiß ja nie.\n\nSeht Ihr da vorn? Diese ganz'n Käfige sin' voll von gefang'nen Trollen, die nur drauf warten, zu sterben. Wir erscheinen da jetz' wie die Antwort auf all ihre Gebete!\n\nLos! Verteilt so viele Waffen, wie Ihr könnt. Rache is' süß!", sourceObjective = "Stattet 10 gefangene Zandalari mit Waffen aus.", sourceObjectiveStatus = "unverified-source-field" }
quests[50085] = { id = 50085, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Nachricht von Blut und Feuer", description = "Guckt mal, was ich hier gefund'n hab. Die hier hatte 'nen Zauberstab in der Hand.\n\n<Rokhan schließt kurz seine Augen.>\n\nMmmh... Er is' warm. Un' es is' Feuermojo drin. Perfekt!\n\nNehmt das Ding un' lasst sie ihre eigene Feuerkraft spür'n.\n\nBrennt das ganze Dorf nieder!", sourceObjective = "Nutzt den Zauberstab der Glutfunken und setzt 8 Bluttrollhütten in Agwamar in Brand.", completion = "Gut gemacht, Mann. Das is' Gerechtigkeit!", sourceObjectiveStatus = "unverified-source-field" }
quests[50087] = { id = 50087, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ateenas Tod", description = "Ihr wart wahrlich <'n besserer Verbündeter/'ne bessere Verbündete>, als ich es je zu hoff'n gewagt hätte. Dank Euch un' Eurer Horde ham wir es bis hierher geschafft. Jetzt fehlt nur noch ein Schritt.\n\nWir müss'n der Anführerin der Bluttrolle geg'nübertret'n un' ihre dunklen Machenschaften ein für alle Mal beend'n.\n\nOhne den Schutz von Ateenas Mojo könn' wir diese Monstrosität endlich vernicht'n, bevor sie über Zuldazar herfällt.\n\nIhr wisst, was zu tun ist.\n\nErst muss ich mich vorbereit'n. Geht! Ich komm zu Euch, wenn der Kampf angefang'n hat.", sourceObjective = "Tötet die Große Mutta Ateena.", completion = "Endlich is' unser Kampf hier vorbei!\n\nIhr habt darüber hinaus in den Tortollanern gute Freunde gefund'n un' die Macht der Loa auf Eurer Seite. Ich hab das Gefühl, dass wir ihre Hilfe in Zukunft öfter brauch'n werd'n.\n\nEs wird Zeit für mich, nach Zuldazar zurückzukehr'n und meinem Vater von unsrem Sieg zu bericht'n.\n\nHört Ihr das? Rokhan scheint 'ne Nachricht für uns zu hab'n.", sourceObjectiveStatus = "unverified-source-field" }
quests[50088] = { id = 50088, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Goldene Felder der Ewigkeit", description = "Um den Rest kann ich mich kümmern. Wäre ich allein gewesen, hätte dieser Ettin mir ganz schön Ärger gemacht, also habt Dank.\n\nDoch ich möchte Euch um einen weiteren Gefallen bitten.\n\nMeine Frau hat die Nelken, die am Flussufer wachsen, sehr geliebt. Wenn Ihr ein paar davon pflücken könntet... Es gibt am Fluss ein malerisches Plätzchen unter einem Baum. Nach einem langen Tag auf den Feldern haben wir uns dort gerne den Sonnenuntergang angeschaut.\n\nUnser Junge rannte herum, fing Käfer, bastelte Pfeifen aus Schilf...", sourceObjective = "Bettet Bauer Goldfelds Familie zur ewigen Ruhe.", progress = "Das wär's dann.", completion = "Habt Dank, {class}. Jetzt werden sie ihre Ruhe finden.", sourceObjectiveStatus = "unverified-source-field" }
quests[50090] = { id = 50090, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aufbau der Verteidigung", description = "Wir können die Monster jetzt zurücktreiben. Allerdings werden meine Verteidiger keine Chance haben, wenn wir als Schutz nicht eine vorgeschobene Barrikade errichten.\n\nEs sollte genug Holz da sein, um in der Nähe des Zugangs zur Stadt eine Barrikade zu errichten.", sourceObjective = "Sammelt Holz zum Bau vorgeschobener Barrikaden.", completion = "Vielen Dank. Jetzt können wir die Stadt besser schützen.", sourceObjectiveStatus = "unverified-source-field" }
quests[50091] = { id = 50091, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dorfreparatur" }
quests[50092] = { id = 50092, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sind sie zu stark...", description = "Ich nehme an, das Feuer hat sich ausgebreitet, während ich da unten war, oder? Dann müssen wir zuallererst verhindern, dass die Stadt niederbrennt! Helft, dieses Problem zu lösen, dann werde ich Zeit haben, Euch zu helfen bei... worum auch immer es geht.\n\nMal sehen... Genau! Nehmt das hier. Das hat sich für die meisten Einwohner hier als etwas zu... heftig erwiesen. Aber Ihr seht stark genug aus.\n\nStellt Euch einfach vor das Feuer und schaut Richtung Flammen, wenn Ihr das verwendet. Dann haben wir die Feuer sicher schnell gelöscht!", sourceObjective = "Benutzt den Frostatemtrank, um die Feuer zu löschen.", completion = "Wunderbar! Die Feuer sind gelöscht und Euer Atem ist minzig frisch!", sourceObjectiveStatus = "unverified-source-field" }
quests[50110] = { id = 50110, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Überbringer schlechter Nachrichten", description = "Wir müssen Lordadmiralin Katherine Prachtmeer von diesem Angriff berichten und beweisen, dass Lady Aschenwind dahinter steckt.\n\nDas wird nicht leicht... Lady Aschenwind und Katherine Prachtmeer sind schon seit Jahren eng befreundet.\n\nSchnell! Wir müssen nach Boralus!", sourceObjective = "Kehrt mit Taelia nach Boralus zurück.", completion = "Die Neuigkeiten über den Angriff scheinen Boralus schon erreicht zu haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[50111] = { id = 50111, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Totems, Totems, Totems!", description = "<Dieses Totem pulsiert mit Energie, die es auf die Götzen und Dornen in der Nähe überträgt.\n\nEs sieht recht zerbrechlich aus... Es wäre eine Schande, wenn ihm etwas passieren würde.>", sourceObjective = "Zerstört die Dornenwachentotems im Kral der Borstenrücken.", completion = "Gute Idee! Wenn wir sie zerstören, lenken wir ihre Mystiker ab und gebieten ihrer Ausbreitung Einhalt.", sourceObjectiveStatus = "unverified-source-field" }
quests[50112] = { id = 50112, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Den ersten Stein werfen", description = "Heda, {name}, helft mir doch mal, ja?\n\n<Kumali winkt Euch zu sich herüber.>\n\nIch hab dieses Rezept und hab versucht, mich an den Rest zu erinnern, aber die richtigen Zutaten woll'n mir nich' einfall'n.\n\nMein Partner is' nämlich mit der andren Hälfte vom Rezept durchgebrannt, weil wir uns gestritt'n ham. Aber dieser Stein is' ein ganz besonderer Schatz.\n\nSchnappt Euch 'n paar Phiolen und fangt an, diese Zutaten zusammenzumix'n, ja? Schau'n wir mal, ob's die richtigen sind.", sourceObjective = "Stellt einen Trank der Haltbarkeit und einen wechselhaften Trank mit den erhaltenen Rezepten her. Die benötigten Zutaten findet Ihr in Kumalis Laden.", progress = "Ich verlang auf keinen Fall die andre Hälfte vom Rezept von dem... dem... Schwachkopf zurück. Ich werd's schon rauskrieg'n, Ihr werdet seh'n.", completion = "Na gut, {name}, lasst uns seh'n, ob das funktioniert.", sourceObjectiveStatus = "unverified-source-field" }
quests[50113] = { id = 50113, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Okulare Extrakte", description = "Nun, es gibt hier 'ne Kreatur mit Augen, die perfekt für bestimmte Alchemierezepte sind.\n\nDie könnt'n wir vielleicht brauch'n, um dieses Projekt fertigzustell'n. Wobei ich nich' glaube, dass die auf dem kompletten Rezept draufstand'n, als ich's zum letzten Mal geseh'n hab, wisst Ihr? Aber mein Gedächtnis is' auch nich' mehr, was es mal war.\n\nAch! Ich schwafle Euch voll. Geht mir die Augen hol'n, ja, {name}?", sourceObjective = "Sammelt 10 Klingenschwingenaugen und bringt sie Kumali. Seht dann zu, wie sie versucht, einen Stein daraus herzustellen.", progress = "Achtet drauf, die Augen erst einzusammeln, wenn die Kreatur tot is'. Sonst macht sie die furchtbarsten Geräusche, wenn Ihr die Augen rausnehm'n wollt.", completion = "Sehr gut. Das sollt'n mehr als genug sein!", sourceObjectiveStatus = "unverified-source-field" }
quests[50114] = { id = 50114, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Informationen raushämmern", description = "Ich schätze, Ihr habt bemerkt, dass man für die Herstellung einen ganz bestimmten Amboss braucht. Und ich schätze, Ihr wollt wissen, wo Ihr einen khaz'gorischen Amboss finden könnt.\n\nNun, ich weiß nicht, wo Ihr einen finden könnt, ganz zu schweigen davon, dass ich niemals behauptet habe, Ihr würdet das verflixte Teil tatsächlich herstellen können.\n\nWenn Ihr mich jetzt entschuldigen würdet, ich muss noch mehr von diesen Anleitungen verkaufen.", sourceObjective = "Entlockt Grix Brennecke mehr Informationen, wo ein khaz'gorischer Amboss zu finden ist.", completion = "Gut, gut... in Ordnung! Ich sage Euch, was ich weiß.", sourceObjectiveStatus = "unverified-source-field" }
quests[50115] = { id = 50115, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Standortwechsel", description = "Vielleicht liegt das Problem darin, dass wir keine normalen Reagenzien brauch'n. Vielleicht brauch'n wir was, das man nur durch Transmutation kriegt.\n\nJetzt is' alles 'nen Versuch wert, das sag ich Euch. Hier is' 'n Rezept, das mein früherer Partner hinterlass'n hat.\n\nEr is' immer zu diesem Tümpel gegangen und hat Gestrüpp in so Blasen verwandelt.\n\nWarum, fragt Ihr Euch? Ganz einfach, er war schon immer ganz besess'n davon, alles Mögliche zu transmutier'n. Einer der Gründe, warum wir nie so richtig miteinander konnt'n.\n\nWie auch immer, bringt mir einige dieser Blas'n, dann schau'n wir, ob wir daraus diesen Stein mach'n können.", sourceObjective = "Geht zum Tümpel, transmutiert Berberitzensträucher in Strauchblasen und sammelt 6 davon ein.\n\nBringt sie Kumali und seht zu, wie sie versucht, den Stein daraus herzustellen.", progress = "Ich hab oft geseh'n, wie er sie in seinen Projekten einsetzt. Sie müss'n also nützliche Eigenschaften für die Alchemie ham.", completion = "Diese Blasen seh'n... komisch aus. Andrerseits is' Zukashi auch 'n komischer Kauz.", sourceObjectiveStatus = "unverified-source-field" }
quests[50116] = { id = 50116, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine mögliche Lösung", description = "Nichts von alldem funktioniert. Ich kann's selbst nich' glaub'n, aber Ihr müsst wohl Zukashi finden.\n\nVielleicht könnt Ihr ihn überzeug'n, die andre Hälfte vom Rezept rauszurück'n. Der is' ziemlich eingebildet, aber nich' ganz unvernünftig.\n\nSoweit ich weiß, is' er in Nazmir in der Nähe vom Trübsumpf. Sagt ihm besser nich', dass es mit mir zu tun hat.", sourceObjective = "Reist nach Nazmir und findet Zukashi.", completion = "Wer seid Ihr? Wieder 'n Lehrling von Kumali, der die wahre Kunst der Alchemie lern' will?\n\nOder habt Ihr es auf was andres abgeseh'n?\n\n<Ihr erklärt Zukashi, dass Ihr an einem besonderen Transmutationsstein forscht und er Euch vielleicht helfen kann.>\n\nAch, dieses Ding, wie? Hehe, ja, das wär schon was Schickes.\n\nAber wenn Ihr mein Wissen ham wollt, müsst Ihr mir erst mit was helf'n, kleiner Mixah.", sourceObjectiveStatus = "unverified-source-field" }
quests[50117] = { id = 50117, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein tödlicher Trunk", description = "Das Erste, was Ihr für mich tun könnt, is', mir 'n paar Todespilze zu sammeln.\n\nKeine Sorge, selbst wenn Ihr Euch nich' mit Kräuterkunde auskennt, sind sie einfach zu find'n. Sie wachs'n normalerweise dort, wo der Tod in der Luft liegt.\n\nAm best'n geht Ihr dafür in die Froschmarsch'n im Südost'n. Die Trolle dort opfern gern ma' die Kreaturen, die in dem Sumpf wohn'n.", sourceObjective = "Sammelt 15 Todespilze.", progress = "Habt Ihr endlich meine Pilze?\n\nSollte eigentlich 'ne einfache Aufgabe sein, sogar für jemand'n wie Euch.", completion = "Gute Arbeit, kleiner Mixah! Das is' mehr als genug.", sourceObjectiveStatus = "unverified-source-field" }
quests[50118] = { id = 50118, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nur einen Steinwurf", description = "Beim Beschaff'n dieser Zutat habt Ihr vielleicht etwas Spaß, <kleiner Mixah/kleine Mixerin>. Ich geb Euch diese Steine. Mit denen könnt Ihr Dinge in andre Dinge verwandeln.\n\nDie Bluttrolle zieh'n unsren Ruf in den Keller und trink'n alles mögliche komische Zeug, das ihrem Körper nich' guttut.\n\nIch brauch deren Blut, um meine Arbeit hier abzuschließ'n, aber kein besudeltes. Mit dies'n Stein'n werd'n die deutlich schwächer. Manchmal verwandeln die Steine sie aber auch in andre Sachen...\n\nSeid vorsichtig damit.", sourceObjective = "Wendet den Beutel mit Transmutationssteinen auf Bluttrolle an und tötet sie. Sammelt 8 Phiolen mit verändertem Blut von ihnen ein.", progress = "Wenn man Zeug transmutiert, weiß man nie, was hint'n dabei rauskommt, bis man's halt ausprobiert. Oder was meint Ihr?", completion = "Wie gefall'n Euch die Steine? Spaßig, oder?\n\nDas is' mehr als genug Blut. Gut gemacht, kleiner Mixah.", sourceObjectiveStatus = "unverified-source-field" }
quests[50119] = { id = 50119, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Chemische Kreation", description = "Jetzt hab ich alles, was ich brauch, und kann dieses Projekt abschließ'n. Meine neuste Transmutation wird meine bisher beste!\n\nAber hier is' nich' der richtige Ort, um sie auszuprobier'n. Das könnte zu viel Aufmerksamkeit erreg'n.\n\nWenn Ihr das selbst seh'n wollt, <kleiner Mixah/kleine Mixerin>, trefft mich weiter nördlich. Da gibt's 'ne Höhle, wo wir das gefahrlos ausprobier'n könn'.", sourceObjective = "Trefft Zukashi an der erwähnten Höhle und seid auf alles gefasst.", completion = "Dieser Beutel muss Zukashi gehört haben. Ihr durchwühlt seine Habseligkeiten und entdeckt ein Stück Papier, das offenbar von einem anderen Stück abgerissen wurde.\n\nIhr nehmt es an Euch und fangt an zu lesen.", sourceObjectiveStatus = "unverified-source-field" }
quests[50120] = { id = 50120, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Erfolgsrezept", description = "Nach eingehender Begutachtung seid Ihr davon überzeugt, dass es sich um die zweite Hälfte des Rezepts handelt, wegen der Ihr hergekommen seid.\n\nUnten auf dem Rezept befindet sich eine seltsame Unterschrift: \"Silas Dunkelmond\".\n\nNun, Kumali dürfte jedenfalls sehr zufrieden sein, das hier wiederzusehen.", sourceObjective = "Bringt das Stück Papier zu Kumali.", completion = "Ihr habt's geschafft, {name}! Das is' die andre Hälfte vom Rezept!\n\n\n\nHier. Nehmt Ihr dieses Exemplar, aber nur nich' verleg'n. Ich mach noch 'ne Kopie und bewahr sie sicher auf.\n\nSo können wir's wiederherstell'n, wenn's einer von uns vergisst, wisst Ihr? Außerdem seid Ihr 'n besserer Partner, als Zukashi es je war, das sag ich Euch. War schön, mit Euch zu arbeit'n, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[50121] = { id = 50121, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Den ersten Stein werfen", description = "Würdet Ihr mir bei etwas helfen, {name}?\n\n<Elrick winkt Euch zu sich herüber.>\n\nIch habe nämlich dieses Rezept, von dem ich... aktuell nur die Hälfte habe. Ich versuche, mich an die andere Hälfte zu erinnern, aber es fällt mir einfach nicht mehr ein.\n\nMein FRÜHERER Partner hat das Rezept entzweigerissen und ist mit der anderen Hälfte davongelaufen, weil wir uns gestritten hatten. Doch der Stein, den man damit herstellt, ist unschätzbar wertvoll.\n\nSchnappt Euch doch einige Phiolen und mischt die Zutaten auf dieser Liste. Vielleicht kommen wir zusammen darauf.", sourceObjective = "Stellt einen Trank der Haltbarkeit und einen wechselhaften Trank mit den erhaltenen Rezepten her. Die benötigten Zutaten findet Ihr in Elricks Laden.", progress = "Ich würde nie um die andere Hälfte bitten. Nicht nach dem, was Quintin zu mir gesagt hat. Ich werde das Rätsel schon lösen, Ihr werdet sehen.", completion = "Dann wollen wir es mal versuchen, oder?", sourceObjectiveStatus = "unverified-source-field" }
quests[50122] = { id = 50122, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Okulare Extrakte", description = "Meine nächste Idee beruht auf Kreaturen, die für bestimmte Alchemierezepte nützlich sind. Zumindest für Tränke.\n\nHoffentlich sind sie hierfür genau das Richtige und es gibt keine... Fehlberechnungen mehr. Ich kann mich zwar nicht daran erinnern, sie auf der Zutatenliste des Rezepts gesehen zu haben... aber mein Gedächtnis ist auch nicht mehr, was es einmal war.\n\nAch, was erzähle ich Euch da lang und breit. Besorgt Ihr doch die Augen, ich treffe inzwischen die Vorbereitungen.", sourceObjective = "Sammelt 10 Hochlandzerfleischeraugen und bringt sie Elrick.", progress = "Ich hoffe allerdings, dass Ihr Euch die Augen nach dem Tod der Kreaturen genommen habt. Sie geben absolut schreckliche Geräusche von sich, wenn man die Extraktion bei lebendigem Leibe versucht.", completion = "Sehr gut. Das sollten mehr als genug sein!", sourceObjectiveStatus = "unverified-source-field" }
quests[50123] = { id = 50123, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Anleitung für die Ewigkeit", description = "He, {name}, hier herüber! Ihr seht so aus, als ob Ihr schon eine Weile mit dem Hammer umgehen könnt. Für sowas habe ich ein Auge.\n\n<Grix grinst über beide Ohren.>\n\nHört mir zu. Ich habe eine Anleitung für den allerbesten Schmiedehammer, den Ihr je gesehen habt. Ausnahmsweise biete ich sie heute gegen Erz zum Verkauf an.\n\nRebliserz, um genau zu sein. Es ist ziemlich selten, aber in Gol Koval in Drustvar gibt es reichlich davon. Die Elementare dort bestehen förmlich daraus.\n\nBringt mir eine Ladung davon und die Anleitung ist Euer!", sourceObjective = "Bringt Grix Brennecke 30 Brocken Rebliserz aus Gol Koval in Drustvar.", progress = "Diese Anleitung ist locker tausend, wenn nicht ZEHNtausend Goldstücke wert! Schmiede auf der ganzen Welt werden Euch darum beneiden. Glaubt mir.", completion = "Ja, ja! Genau das habe ich gemeint!\n\nHier, Eure Anleitung. Viel Spaß damit.", sourceObjectiveStatus = "unverified-source-field" }
quests[50124] = { id = 50124, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Standortwechsel", description = "Der Stein, den man mit diesem Rezept herstellt, ist ein Transmutationsstein. Kann es sein, dass die fehlenden Reagenzien aus einem Transmutationsvorgang stammen müssen?\n\nMittlerweile würde ich alles probieren. Hier ist ein altes Rezept meines früheren Partners.\n\nEr ist immer ins Sturmsangtal gegangen, direkt südlich der Hochlandplatte, und hat die Büsche in Blasen verwandelt.\n\nBringt mir einige solcher Blasen, dann wollen wir sehen, ob sie uns gefehlt haben.", sourceObjective = "Geht ins Sturmsangtal, transmutiert Berberitzensträucher zu Strauchblasen und sammelt 6 davon.\n\nBringt sie Elrick und seht zu, wie er versucht, den Stein daraus herzustellen.", progress = "Ich habe früher gesehen, wie er die Globen für Projekte verwendet hat. Sie müssen also über bestimmte alchemistische Eigenschaften verfügen.", completion = "Diese Blasen sind... merkwürdig. Aber das passt zu Quintin.", sourceObjectiveStatus = "unverified-source-field" }
quests[50125] = { id = 50125, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine mögliche Lösung", description = "Nichts scheint zu funktionieren. Ich fasse es nicht, dass ich das vorschlage, aber ich glaube, wir müssen uns an Quintin wenden.\n\nAlso, Ihr solltet das tun, denn mit mir wird er wohl nicht reden. Vielleicht könnt Ihr ihn überzeugen, sich von der anderen Hälfte des Rezepts zu trennen?\n\nSoweit ich weiß, befindet er sich in Drustvar in der Nähe von Aroms Wehr. Dort gibt es zwar viele Alchemisten, aber er sollte nicht zu schwer zu finden sein.\n\nSagt ihm lieber nicht, dass ich Euch geschickt habe. Sonst rückt er das Rezept wahrscheinlich nicht so leicht raus.", sourceObjective = "Reist nach Drustvar und findet Quintin Pfitzer.", completion = "Wen haben wir denn hier? Ihr seid nicht zufällig ein früherer Lehrling meines kleinen Bruders Elrick, der hier richtige Alchemie erlernen möchte, oder?\n\n<Ihr erklärt Quintin, dass Ihr an einem besonderen Transmutationsstein forscht und er Euch eventuell helfen könnte.>\n\nAha, so einen würdet Ihr also gerne herstellen, wie? Nun, genau wie bei der Transmutation müsst ihr dafür etwas Gleichwertiges aufwenden.\n\nIhr müsst zunächst ein paar Dinge für mich erledigen. Euch wird das Vergnügen zuteil, MEIN Lehrling zu sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[50126] = { id = 50126, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein tödlicher Trunk", description = "Als Erstes hätte ich gerne, dass Ihr mir einige Todespilze sammelt.\n\nKeine Sorge, wenn Ihr Euch mit Kräuterkunde nicht auskennt. Sie sind sehr leicht zu pflücken und wachsen üblicherweise dort, wo der Tod in der Luft liegt.\n\nIch würde es südlich von hier im Blutroten Wald versuchen. Die Kreaturen, die den Wald geradezu überrannt haben, scheinen mit Todesmagie behaftet zu sein.", sourceObjective = "Sammelt 15 Todespilze.", progress = "Habt Ihr endlich meine Pilze bekommen?\n\nEs sollte eigentlich eine einfache Aufgabe sein, sogar für jemanden wie Euch.", completion = "Ach ja, das ist für mich mehr als ausreichend. Gute Arbeit, Lehrling.", sourceObjectiveStatus = "unverified-source-field" }
quests[50127] = { id = 50127, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nur einen Steinwurf", description = "Die Beschaffung der nächsten Zutat wird Euch vielleicht Vergnügen bereiten. Ich habe ein paar besondere Steine mit transmutativen Eigenschaften, vor allem bei Lebewesen. Dem gar nicht so unähnlich, den Ihr herstellen möchtet.\n\nDie Hexen, die dieses Land plagen, sind mit Magie erfüllt, und ihr Blut ist es genauso.\n\nIch benötige ihr Blut, um mein jüngstes Projekt abzuschließen, aber in unveränderter Form. Diese Steine werden sie in schwächere Kreaturen verwandeln. Hin und wieder passiert allerdings das Gegenteil...\n\nIch würde Euch empfehlen, vorsichtig damit umzugehen.", sourceObjective = "Wendet den Beutel mit Transmutationssteinen auf Hexen an und tötet sie. Sammelt dann 8 Phiolen mit verändertem Blut von ihnen ein.", progress = "Ganz weiß man nie, was bei einer Transmutation herauskommt, bis man es probiert. Findet Ihr nicht auch, mein Lehrling?", completion = "Wie haben Euch die Steine gefallen? Amüsant, nicht wahr?\n\nDas ist auch mehr als genug Blut. Gute Arbeit.", sourceObjectiveStatus = "unverified-source-field" }
quests[50128] = { id = 50128, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Chemische Kreation", description = "Das ist wohl alles. Diese neueste Transmutation ist meine bisher edelste. Und sobald sie abgeschlossen ist, erhaltet Ihr Euren Preis, Lehrling.\n\nHier ist allerdings kein geeigneter Platz für einen Test. Das könnte zu viel Aufmerksamkeit erregen.\n\nNicht besonders weit weg von hier ist eine Höhle, die ein passenderer Ort für die Durchführung eines solchen Tests wäre.\n\nTrefft mich dort, wenn Ihr bereit seid, zu erleben, weshalb Transmutation der einzige Zweig der Alchemie ist, den es zu erlernen lohnt.", sourceObjective = "Trefft Quintin an der erwähnten Höhle und seid auf alles gefasst.", progress = "Da sind anscheinend ein paar von Quintins Sachen drin.", completion = "Dieser Beutel muss Quintin gehört haben. Ihr durchwühlt seine Habseligkeiten und entdeckt ein Stück Papier, das offenbar von einem anderen Stück abgerissen wurde.\n\nIhr nehmt es an Euch und fangt an zu lesen.", sourceObjectiveStatus = "unverified-source-field" }
quests[50129] = { id = 50129, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Erfolgsrezept", description = "Nach eingehender Begutachtung seid Ihr davon überzeugt, dass es sich um die zweite Hälfte des Rezepts handelt, wegen der Ihr hergekommen seid.\n\nUnten auf dem Rezept befindet sich eine seltsame Unterschrift: \"Silas Dunkelmond\".\n\nNun, Elrick dürfte jedenfalls sehr zufrieden sein, das hier wiederzusehen.", sourceObjective = "Bringt das Stück Papier zu Elrick.", completion = "Ihr habt es?! Ich bin beeindruckt, dass Ihr es Quintin abnehmen konntet.\n\n<Elrick nimmt Eure Hälfte des Rezepts und holt ein frisches Pergament. Er schreibt die Informationen ab und bringt das fertige Dokument zu Euch.>\n\nHier, dieses Exemplar ist für Euch. Ich fertige eine weitere Kopie für mich an und passe dieses Mal gut darauf auf.\n\nIhr habt einen wesentlich besseren Partner abgegeben, als Quintin es je war, wenn ich das mal so sagen darf. Es war ein Vergnügen, mit Euch zu arbeiten, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[50130] = { id = 50130, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine freundliche Geste", description = "Das Leben in den Marschen ist nicht einfach, {name}. Wir streben nach Harmonie mit allen hier heimischen Wesen, aber unsere Feinde da draußen bedrohen unsere Existenz.\n\nUnterstützt uns. Verhelft den Bewohnern von Sporeggar zu einer besseren Zukunft.", sourceObjective = "Erreicht bei Sporeggar den Status freundlich.", completion = "Danke, dass Ihr den Einwohnern von Sporeggar geholfen habt, {race}. Ihr seid hier immer willkommen.", sourceObjectiveStatus = "unverified-source-field" }
quests[50131] = { id = 50131, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine neue Perspektive", description = "Danke für alles, was Ihr für mein Volk getan habt, aber sie fürchten sicher immer noch vor Fremdlingen.\n\nBekämpft die Sumpflords und rettet unsere Sporenbeutel im Pilzgeflecht. Die Zukunft meines Volkes steht auf dem Spiel!", sourceObjective = "Erreicht bei Sporeggar den Status neutral.", completion = "Vielen Dank, {name}! Vielen Dank.", sourceObjectiveStatus = "unverified-source-field" }
quests[50133] = { id = 50133, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unkraut vergeht nicht" }
quests[50134] = { id = 50134, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geräte und Dingsbumse in Hülle und Fülle", description = "Die Miliz mag uns aufgegeben haben, aber ich mich noch lange nicht!\n\nIch tüftele gern, und ich finde, dass meine Erntegolems besser sind als jeder Tagelöhner, den ich je hatte. Sie müssen nur regelmäßig gewartet werden, damit sie funktionstüchtig bleiben.\n\nAber jetzt machen sich die Borstenrücken auf meinen Feldern breit, und meine Landarbeiter rosten vor sich hin.\n\nKönntet Ihr allen, die Ihr findet, ihre inneren Mechanismen entnehmen, wenn Ihr auf die Felder rausgeht? Das verhindert, dass sie explodieren und wird sich außerdem für meine Rache als nützlich erweisen.", sourceObjective = "Sammelt 10 Ernterdingsbumse.", progress = "Habt Ihr die Teile schon?", completion = "Perfekt! Mit diesen Teilen kann ich meine ganze Mannschaft neu konstruieren... oder einen von ihnen so RICHTIG stark machen.", sourceObjectiveStatus = "unverified-source-field" }
quests[50135] = { id = 50135, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Weist die Ranken in die Schranken!", description = "Vielleicht habt Ihr bemerkt, dass die Felder gerade ein wenig... instabil sind.\n\nDie Borstenrücken waren fleißig. Sie haben diese langen Dornenranken gezüchtet und Tunnel unter der Farm gegraben. Die Ranken waren schon immer ein wichtiger Teil ihrer Grenzen und sie breiten sich immer weiter aus!\n\nBegebt Euch da runter und versucht herauszufinden, wer oder was diese Ranken so wuchern lässt. Es ist unmöglich, dass sie von Natur aus so schnell wachsen. Wenn wir den Ranken Einhalt gebieten können, können wir auch dieses Gebiet zurückerobern!", sourceObjective = "Tötet die drei Rankenmeister.", completion = "Mystiker, die sich Magie zunutze machen, um die Ranken zu formen? Ich weiß nicht viel über Magie, aber ich bin heilfroh, dass Ihr ihnen einen Riegel vorgeschoben habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[50136] = { id = 50136, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Landwirtschaftsstimulator", description = "Seitdem Ihr ihre Meister besiegt habt, laufen die Pflanzen Amok! Aber keine Sorge, ich habe einen Plan.\n\nIch habe mich darangemacht, einen der Landarbeiter, die noch nicht vollends hinüber waren, zu reparieren. Er sollte noch genug Saft für einen weiteren Ausflug durch die Felder haben.\n\nDie Technologie in diesen Erntemaschinen hat es in sich. Ihre Werkzeuge sollten mehr als ausreichen, um ein paar kleineren Pflanzen und sogar ein paar Stachelebern den Garaus zu machen.\n\nWas meint Ihr? Seid Ihr für etwas Landwirtschaft nach Sturmsangart zu haben? Dann springt rein und macht Euch an die Arbeit!", sourceObjective = "Benutzt den gesteuerten Landarbeiter, um 30 Gegner zu töten.", completion = "Jawohl, das wird es ihnen zeigen! Diese Stacheleber werden es sich zweimal überlegen, bevor sie sich wieder auf meine Farm wagen!", sourceObjectiveStatus = "unverified-source-field" }
quests[50138] = { id = 50138, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Schlacht um die Blutfeuerschlucht", description = "Wir müss'n zuschlagen und die Bedrohung durch die Bluttrolle ein für alle Mal beend'n!\n\nWir reisen zurück zur Blutfeuerschlucht und dieses Mal werd'n es die Bluttrolle sein, die davonlauf'n.\n\nLasst uns aufsitz'n und ihnen zeig'n, dass wir 'ne Macht sind, mit der zu rechnen is'!", sourceObjective = "Erobert die Blutfeuerschlucht von den Bluttrollen.", completion = "Gut gekämpft!\n\nDie Bluttrolle flieh'n! Jetzt dürf'n wir nicht nachlassen!", sourceObjectiveStatus = "unverified-source-field" }
quests[50139] = { id = 50139, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das fehlende Glied", description = "<Obgleich sie verbrannt ist, bleiben einige Passagen der Nachricht des Architekten lesbar.>\n\nSie sind... überall... getarnt...\n\nVerschlüsselte... Baupläne...\n\nGlyphe...\n\nPontus... beobachtet mich...\n\n<Die Glyphe muss zur Entschlüsselung der Schiffsbaupläne dienen. Wahrscheinlich hat Pontus sie.>", sourceObjective = "Besorgt die Glyphe des Architekten von Gezeitenwächter Pontus.", progress = "Wir müssen all dem auf den Grund gehen, bevor Lord Sturmsang in die Offensive geht!", completion = "Eine Glyphe? Aber natürlich! Aber mit was zum Großen Meer ist die denn bedeckt?!", sourceObjectiveStatus = "unverified-source-field" }
quests[50149] = { id = 50149, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein scharfes Auge", description = "Es wäre eine kluge Idee, sich zuerst einen Überblick über die Umgebung zu verschaffen, bevor wir anfangen.\n\nInquisitor Nottlich ist ein erfahrener Falkner und ein verlässlicher Späher. Er nutzt ein uraltes Artefakt, um durch die Augen seines Falken sehen zu können. So kann er unglaubliche Distanzen überblicken.\n\nLeider wurde Nottlich im Kampf verwundet. Es ist zwar nichts Bedrohliches, aber schlimm genug, dass er sich nicht mehr auf die Führung seines Falken konzentrieren kann.\n\nKönnt Ihr vielleicht helfen?", sourceObjective = "Sprecht mit Inquisitor Nottlich auf der Wachmannshöhe und erkundet die Umgebung von Korlach.", progress = "Was bringt Ihr für Neuigkeiten?", completion = "Jetzt wissen wir zumindest, dass es immer noch ein paar Leute in Korlach gibt, die wir retten können.\n\nWir sollten uns auf sie konzentrieren, bis wir einen Plan haben, wie wir um diese Barriere herumkommen.\n\nIch werde diese Pfeife zurück zu Nottlich bringen. Ich danke Euch, {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[50150] = { id = 50150, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Für die richtige Stimmung sorgen", description = "Das Voodooliebesräucherwerk und das romantische Essen sin' bereit, {name}. Nehmt es und stellt es direkt vor Maka'fon ab.\n\nSchnell, wenn's geht. Dieser Gestank is' einfach... unglaublich widerlich und ekelhaft.\n\nKönntet Ihr 'n bisschen schneller geh'n.\n\nWeg.\n\nVon uns.\n\nZum Wohle der Brutosaurier natürlich.", sourceObjective = "Platziert das Licht und das Voodooliebesräucherwerk in der Nähe von Maka'fon der Reizbaren und kredenzt ihr das romantische Brutosaurusessen.", completion = "Auf dem Gebiet der Liebe bin ich 'ne Expertin, das kann Euch jeder meiner ehemaligen Partner bestätig'n. Ich hab den Grund für Maka'fons Stimmung falsch gedeutet.\n\nDie Klingenschwingen haben ihre letzte Brut aufgefress'n und deshalb wird sie nich' mehr trächtig, bis ihre Brut gerächt ist und sie sich sicher fühlt.", sourceObjectiveStatus = "unverified-source-field" }
quests[50151] = { id = 50151, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ballastbarer Schmied gesucht", description = "Das Arsenal bietet uns eine gute Gelegenheit, {class}. Wir sollten sie auch nutzen.\n\nWenn sich diese Schlacht hinzieht, haben wir kaum Möglichkeiten, unsere Waffen und Rüstungen zu reparieren. Ein Schmied ist in jedem Krieg unverzichtbar und Ballaster ist einer unsrer besten.\n\nDas Arsenal ist nicht weit von hier. Ich schlage vor, Ihr begebt Euch zu Ballaster, bevor es zu spät ist!", sourceObjective = "Findet Arnold Ballaster im Waffenlager von Korlach.", completion = "Das Glück ist auf unsrer Seite.\n\nMit dem Schmied beim Turm sind unsere Inquisitoren perfekt für die Schlacht gerüstet.", sourceObjectiveStatus = "unverified-source-field" }
quests[50152] = { id = 50152, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Metalldetektor", description = "Sehr erfreut, {class}.\n\nIch hoffe, es ist in Ordnung für Euch, dass ich mir die Freiheit erlaubt habe, die Situation im Waffenlager schon einmal auszuspähen.\n\nDie gute Nachricht ist, dass es noch einiges an brauchbarer Ausrüstung gibt. Die schlechte Nachricht ist, dass der Zirkel das weiß und ebenfalls danach Ausschau hält.\n\nZusätzliche Waffen und Rüstungen wären eine wichtige Aufwertung unseres Arsenals. Ich schlage vor, dass wir so viel mitnehmen, wie wir können.", sourceObjective = "Sammelt 10 hochwertige Ausrüstungen im Waffenlager von Korlach.", progress = "Was habt Ihr im Waffenlager gefunden?", completion = "Der Zirkel hat das Waffenlager also noch nicht komplett ausgeräumt? Das nenne ich mal gute Neuigkeiten.\n\nSelbst die gewöhnlichen Bürger von Drustvar sind schon sehr passable Kämpfer. Mit dieser zusätzlichen Ausrüstung können wir aus jedem geretteten Stadtbewohner einen weiteren fähigen Soldaten machen.", sourceObjectiveStatus = "unverified-source-field" }
quests[50154] = { id = 50154, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Angeblich eine Delikatesse", description = "Ein romantisches Essen sorgt für 'nen Abend voller Liebe. Das gilt für uns, also warum nich' auch für Maka'fon? Bringt ihr etwas Selt'nes, das ihr'n Geschmack trifft.\n\nDimetrodons am Wasser fress'n harte Samenkapseln un' verdau'n sie nur teilweise. Mit ein bisschen Voodoo könn' wir die Kapseln verzaubern. Das is' für Euch un' mich vielleicht eklig, aber für Brutosaurier 'n seltener Leckerbissen. So is' das im Leben.\n\nEs gibt genug Dimetrodons, also müss'n ein paar sterb'n, damit die Brutosaurier leb'n könn'. Das is' der Zweck des Todes.", sourceObjective = "Besorgt 25 halb verdaute Kapseln aus den Bäuchen von Dimetrodons in der Nähe.", progress = "Die Kapseln, die wir brauch'n, werden erst im Magen von Dimetrodons essbar. Passt da drin auf Eure Finger auf... die Schuppen hab'n scharfe Kanten.", completion = "Wir find'n die Kapseln vielleicht abstoßend, aber die Brutosaurier mög'n sie sehr gerne.", sourceObjectiveStatus = "unverified-source-field" }
quests[50157] = { id = 50157, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Gold in diesen Feldern", description = "Es werden noch immer Leute vermisst und ich könnte Eure Hilfe brauchen, um sie zu finden.\n\nAuch wenn Brennadam jetzt sicher ist, mache ich mir Sorgen um unsere näher am Kral der Borstenrücken gelegenen Farmen. Bis jetzt haben wir uns darauf verlassen, dass die Miliz die Stacheleber zurückhält, aber da sie jetzt nach Osten abgerückt ist, habe ich Angst um unsere weiter draußen gelegenen Farmen.\n\nGoldfelds Farm liegt fast direkt südlich von uns an den Wasserfällen den Hügel hinauf. Obwohl es nicht weiter verwunderlich ist, dass er noch nicht aufgebrochen ist, wäre es mir lieber, wenn Ihr nachschaut.", sourceObjective = "Findet Bauer Goldfeld auf seiner Farm.", completion = "Rosen macht sich ununterbrochen Sorgen um mich. Ich sage ihr immer wieder, dass es mir hier oben gutgeht, aber sie will es nicht hören...", sourceObjectiveStatus = "unverified-source-field" }
quests[50158] = { id = 50158, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Versenkt", description = "Wenn Ihr eine Minute habt, gibt es da draußen noch einen Bauern, der es noch nicht zurückgeschafft hat.\n\nSein Name ist Büttner und er ist auf einer Farm gleich am Kral der Borstenrücken. Wenn die Stacheleber wieder angreifen, ist seine Farm eine der ersten in ihrem Weg.\n\nIch habe lange nichts von Büttner gehört. Er verließ sich hauptsächlich auf die Unterstützung seiner mechanischen Landarbeiter, also haben wir keine Ahnung, wie es um ihn bestellt ist.\n\nBrecht nach Westen auf und schaut mal nach ihm, ja?", sourceObjective = "Sucht Bauer Büttner auf seiner Farm.", completion = "Ich bin hier zurückgeblieben, um zu sehen, ob ich helfen kann... Ich hoffe doch, alle anderen haben es sicher zurückgeschafft?", sourceObjectiveStatus = "unverified-source-field" }
quests[50161] = { id = 50161, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Raimund retten", description = "Auf der Karte, die wir vorhin gefunden haben, waren einige rote Markierungen in der Nähe des Blumenfelds eingezeichnet.\n\nKönntet Ihr wohl dort oben nach Papa suchen?\n\nIch bleibe hier und überprüfe das restliche Zeug.\n\nIch würde ja mit Euch gehen, aber ich bin allergisch gegen Bienen.\n\nUnd nehmt seine Stiefel mit. Nur für den Fall der Fälle.", sourceObjective = "Findet Raimund Mildenhall.", progress = "Wird auch Zeit, dass mich jemand suchen kommt!", completion = "Ahh, hah! Anselm schickt Euch wohl, um nach mir zu suchen, was?\n\nHe, meine Stiefel habt Ihr auch gefunden?! Wundervoll!", sourceObjectiveStatus = "unverified-source-field" }
quests[50162] = { id = 50162, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Klebrige Komplikationen", description = "Meine bahnbrechenden wissenschaftlichen Entdeckungen, wundervoll, wundervoll... Ich bin ganz nahe dran an der perfekten Formel!\n\nWie sich der Honig hier kristallisiert und wächst, das ist einfach bildschön. Wie Ihr sehen könnt, ist das aber auch gerade ein kleines Problem für mich.\n\nKönnt Ihr mir vielleicht helfen? Sammelt einfach ein bisschen Gelée Royale von den Bienenstöcken draußen.\n\nUnd keine Sorge wegen der Bienen. Das sind friedliche, sanfte Tierchen.\n\nSie stechen fast gar nicht.", sourceObjective = "Sammelt 60 Gelée Royale.", progress = "Habt Ihr schon das ganze Gelée Royale gesammelt?", completion = "Ich hoffe, die Bienen haben Euch keine Probleme gemacht. Aber nein, natürlich nicht... Warum auch?\n\nSie sind doch völlig harmlos.", sourceObjectiveStatus = "unverified-source-field" }
quests[50164] = { id = 50164, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Polly will einen Keks?" }
quests[50165] = { id = 50165, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die B-Mannschaft", description = "Wir müssen die Dinge hier in Ordnung bringen. Und als Nächstes sind diese verdammten Wendigos, die den Hof terrorisieren, dran. \n\nWenn wir genug von ihnen töten, sollte das die anderen vertreiben!\n\nIch habe eine vorzügliche Lösung erstellt, die genau das richtige Mittel für diese Angelegenheit sein könnte!\n\nSchmeißt diese Flaschen auf Eure Feinde, damit die süßen kleinen Apoideas uns zu Hilfe kommen.\n\nAber passt bloß auf, dass Ihr selbst nicht in Kontakt mit dem Zeug geratet...", sourceObjective = "Tötet 12 Hochlandzerfleischer.", completion = "Haha! Habt Ihr die Panik in ihren Augen gesehen, als sie die Bienenschwärme bemerkt haben? \n\nFantastisch!", sourceObjectiveStatus = "unverified-source-field" }
quests[50168] = { id = 50168, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Königliche Nachfolge", description = "Ich weiß, ich weiß, okay... Die Farm wird von lebendem Honig überschwemmt und die Bienen sind riesengroß geworden.\n\nIch gebe ja zu, dass nicht alles nach Plan gelaufen ist. Aber jede bahnbrechende wissenschaftliche Entdeckung hat nun mal ihren Preis!\n\nIch habe versucht, die Aggression innerhalb des Schwarms abzumildern. Sie kam als unschöner Nebeneffekt meiner Fehlkalkulation, aber Ihr müsst mir noch einen weiteren Gefallen tun...\n\nIhr müsst die Schwarmmutter töten und mir ihren Stachel bringen.", sourceObjective = "Holt Euch den Stachel der Schwarmmutter.", progress = "Oooh, ooh, habt Ihr ihn?!", completion = "Ich bin froh, dass Ihr kein Auge verloren habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[50172] = { id = 50172, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Blutrote Wald", description = "Meister Eschtal wurde in den Wald entführt, aber er ist nicht der Einzige. Bei Bürgermeister Reinwalds Zählung fehlten noch mehr.\n\nWas wir jetzt machen müssen, ist klar. Wir müssen Meister Eschtal in den Wald folgen und ihn retten.\n\nMartin und ich werden uns in den Wald schleichen. Wir treffen Euch dort, in der Nähe einiger alter Ruinen.", sourceObjective = "Trefft Euch mit Inquisitorin Morgenlicht im Blutroten Wald.", completion = "Der Wald ist voller Hexen. Wenn wir Meister Eschtal retten wollen, werden wir kämpfen müssen.", sourceObjectiveStatus = "unverified-source-field" }
quests[50173] = { id = 50173, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Silberner Hoffnungsschimmer", description = "{class}, es gibt noch etwas, das wir in Betracht ziehen sollten.\n\nDie Rauhügelmine befindet sich nicht weit von hier. Das ist zwar hauptsächlich eine Eisenmine, aber manchmal finden die Bergarbeiter dort auch Silber.\n\nWir wissen nichts über den derzeitigen Zustand der Mine oder ob der Zirkel sich dort schon ausgetobt hat. Aber wir sollten uns den dort möglicherweise lauernden Gefahren stellen, um etwas Silber zu beschaffen, das wir gegen den Zirkel einsetzen können.", sourceObjective = "Sammelt 10 Silberklumpen in der Rauhügelmine.", progress = "Hattet Ihr Glück bei der Mine?", completion = "Ihr habt wirklich Silber gefunden? Hervorragend!\n\nEs ist zwar nicht viel, aber jede noch so kleine Menge Silber hilft uns bei unserem Kampf gegen den Zirkel!", sourceObjectiveStatus = "unverified-source-field" }
quests[50174] = { id = 50174, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ordentlich eingewickelt", description = "Ich bin zwar aus der Mine entkommen, aber einige meiner Freunde haben es nicht geschafft. Ich habe gesehen, wie die Spinnen sie in Netze eingesponnen haben. Wahrscheinlich werden sie als Nachmittagshappen aufbewahrt.\n\nDas war so schrecklich. Ich konnte aber nichts tun, nur fliehen.\n\nKönnt Ihr ihnen helfen, bitte?", sourceObjective = "Zerstört zuckende Kokons, um 8 Minenarbeiter in der Rauhügelmine zu retten.", completion = "Ihr habt sie gerettet!\n\nFür mich seid Ihr der größte Held aller Zeiten!", sourceObjectiveStatus = "unverified-source-field" }
quests[50175] = { id = 50175, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Widerlinge mit acht Beinen", description = "Irgendeine alte Hexe hat diesen Schwarm ekliger Spinnen auf die Mine losgelassen! Ich bin nur knapp mit dem Leben entkommen. Die widerlichen Dinger sind aber auch überall.\n\nLasst mich hier nicht zurück! Bitte tötet diese schrecklichen Biester!", sourceObjective = "Tötet 20 Gallenzahnspinnen in der Rauhügelmine.", completion = "Ihr... habt sie getötet?!\n\nOh, tausend Dank! Es war der reinste Alptraum hier drinnen!", sourceObjectiveStatus = "unverified-source-field" }
quests[50177] = { id = 50177, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Haltet die Barrikade!", description = "{name}, sie sammeln sich für einen schweren Angriff!\n\nWir müssen die Barrikaden gegen den Überfall verteidigen. Seid Ihr dabei?", sourceObjective = "Verteidigt die Barrikaden gegen den Angriff!", progress = "Jetzt haben wir wieder etwas Luft zum Atmen.", completion = "Diese Hexe! Sie muss hinter diesen Angriffen stecken!", sourceObjectiveStatus = "unverified-source-field" }
quests[50178] = { id = 50178, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Probleme am Wurzelpfad" }
quests[50195] = { id = 50195, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bilgenspalters Brigade", description = "<Laut diesen Befehlen wurden diese Assassinen von einem Seebärenkapitän angeheuert, der in Drustvar einen Brückenkopf errichten will.\n\nIhn zu töten, würde für die Horde und ihre Kriegspläne eine heftige Niederlage bedeuten. Dann hören vielleicht auch diese ständigen Überfälle auf.>", sourceObjective = "Besiegt Käpt'n Bilgenspalter an der Brackwasserküste und plündert seine Kriegsbeute.", sourceObjectiveStatus = "unverified-source-field" }
quests[50206] = { id = 50206, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gegenschlag" }
quests[50226] = { id = 50226, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Machtquelle", description = "Nach der Zerstörung von Silithus sind die Silithiden eine Zeit lang verschwunden, aber seit kurzem strömen sie zurück an die Oberfläche.\n\nDiese neuen Silithiden scheinen stärker als zuvor!\n\nIch habe eine Hypothese, dass die Silithiden sich an einer Art Machtquelle unter Sargeras' Klinge nähren.\n\nMir wurde aufgetragen, den Effekt dieser mysteriösen Kraft auf die Silithidenbauten zu studieren.\n\nBringt mir so viele unversehrte Silithidengehirne, wie Ihr tragen könnt, damit ich mit der Forschung beginnen kann!", sourceObjective = "Sammelt 10 Silithidengehirne.", progress = "Habt Ihr die Gehirne?", completion = "Oh! Seht Euch diese riesigen, prächtigen Gehirne an! Ich will mich sofort reinwühlen... Danke für Eure Hilfe, {name}! Ihr könnt gern bleiben und zusehen, aber es könnte eine ganz schöne Sauerei werden!", sourceObjectiveStatus = "unverified-source-field" }
quests[50227] = { id = 50227, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Larven im Dutzend", description = "Ich bin fassungslos! Wie konnten die Silithiden den Einschlag von Sargeras' Klinge überleben?\n\nIch habe noch nie eine Spezies gesehen, die sich derart schnell an Umweltveränderungen anpassen kann, wie die Silithiden!\n\nDie Larven, oft auch Brutlinge genannt, können sich je nach Bedarf des Schwarms in eine Vielzahl von Silithidenkreaturen entwickeln.\n\nWird die Entwicklung der Larven vom Schwarmbewusstsein bestimmt oder spielen Umwelteinflüsse eine Rolle?\n\nDie Wissenschaft muss es ans Licht bringen!", sourceObjective = "Sammelt 12 Silithidenbrutlinge.", progress = "Habt Ihr die Silithidenlarven?", completion = "Ah, Ihr habt die Brutlinge! Das sieht vielversprechend aus. Wollt Ihr mir zusehen, wie ich sie behutsam, Stück für Stück seziere und jedes Detail ihrer Anatomie katalogisiere?", sourceObjectiveStatus = "unverified-source-field" }
quests[50228] = { id = 50228, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Zwielichtüberlebende", description = "In Silithus wimmelte es früher nur so vor Anhängern des Schattenhammers.\n\nDer Kult galt als zerschlagen, aber er wartete nur geduldig in den Schatten. Ihre Zahl ist dramatisch gesunken, aber sie sind so fanatisch wie eh und je.\n\nDie meisten ihrer Kultisten hier wurden bei Sargeras' Angriff getötet, aber nicht alle. Ihr Anführer Michiel Leerenwanderer ist seit der Zerstörung von Silithus mutiger geworden.\n\nWir können nicht zulassen, dass er die Überlebenden versammelt. Er muss gestoppt werden!", sourceObjective = "Holt Euch Michiel Leerenwanderers Kopf.", progress = "Wir dürfen nicht zulassen, dass der Schattenhammerkult wieder in Silithus Fuß fasst.", completion = "Das ist also der Kopf von Michiel Leerenwanderer. Eine grausame Aufgabe, aber es war notwendig. Die Allianz dankt Euch für Eure Dienste, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[50229] = { id = 50229, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein kleines Stückchen Stoff", description = "{name}, seid Ihr das, <den/die> ich da draußen rascheln höre? Ich bin's, Angus Sturmbräu!\n\nHier sind überall Kultisten, also sprecht leise. Rückt ein Stück näher und haltet Euch die Nase zu, während wir reden!\n\nDas ist das einzige Plumpsklo in ganz Silithus! Glaubt mir, ich hab letzte Nacht stundenlang gesucht. Ich hab mich für 'nen kleinen \"Bombenabwurf\" reingeschlichen, bevor die Kultisten aufgewacht sind, aber ich hab ein... ähm... kleines Problem.\n\nIch finde keinen Stoff, um... Ihr wisst schon...\n\nSeht doch bitte mal nach, ob Ihr ein kleines Stückchen Stoff auftreiben könnt, und reicht es durch die Türe rein!", sourceObjective = "Sammelt 8 Fetzen Zwielichtseide.", progress = "Habt Ihr \"die Ware\"?", completion = "Aye! Das wird's tun! Nur noch ein Minütchen...", sourceObjectiveStatus = "unverified-source-field" }
quests[50230] = { id = 50230, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Machtquelle", description = "Die Silithiden sind aufgebracht und stärker denn je!\n\nIch glaube, sie zehren von irgendeiner Art Macht tief im Boden – wahrscheinlich in der Nähe von Sargeras' Klinge.\n\nMir wurde aufgetragen, die Auswirkungen dieser mysteriösen Macht auf die Silithiden zu untersuchen.\n\nBringt mir so viele unversehrte Silithidengehirne, wie Ihr nur tragen könnt, und ich beginne mit der Forschung!", sourceObjective = "Sammelt 10 Silithidengehirne.", progress = "Hey Kleiner! Habt Ihr das Zeug?", completion = "Heiliger Strohsack! Seht Euch diese riesigen, prächtigen Gehirne an! Wo ist mein Skalpell? Wartet... nein... bringt mir die Elektrosäge. Zeit für die großen Geschütze, Baby!", sourceObjectiveStatus = "unverified-source-field" }
quests[50231] = { id = 50231, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Larven im Dutzend", description = "Wie konnten die Silithiden den Einschlag von Sargeras' Klinge überleben?\n\nIch habe noch nie eine Spezies gesehen, die sich derart schnell an Umweltveränderungen anpassen kann, wie die Silithiden!\n\nEs muss einen Weg geben, diese Viecher zu zähmen! Nutzt ihre evolutionäre Biologie für unsere Zwecke!\n\nWir müssen sie von klein auf trainieren! Vergesst die alten Krustigen, wir brauchen Babys!\n\nBeschafft mir so viele Silithidenlarven, wie Ihr tragen könnt, und ich finde heraus, wie wir sie trainieren können!", sourceObjective = "Sammelt 12 Silithidenbrutlinge.", progress = "Habt Ihr die Silithidenlarven?", completion = "Ihr habt die Larven! Oh, mit denen werden wir so richtig abkassieren! Ich kann das Gold schon in meinen Taschen klimpern hören!", sourceObjectiveStatus = "unverified-source-field" }
quests[50232] = { id = 50232, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Zwielichtüberlebende", description = "In diesen Landen wimmelte es früher nur so vor Anhängern des Schattenhammers.\n\nDer Kult galt als zerschlagen, aber Finsternis überdauert immer in den Schatten.\n\nDie meisten der Kultisten wurden bei Sargeras' Angriff getötet, aber nicht alle. Die Zerstörung von Silithus hat ihren Anführer Michiel Leerenwanderer angespornt.\n\nWir können nicht zulassen, dass er die Überlebenden vereint. Bringt mir seinen Kopf!", sourceObjective = "Holt Euch Michiel Leerenwanderers Kopf.", progress = "Wir dürfen nicht zulassen, dass der Schattenhammerkult wieder in Silithus Fuß fasst!", completion = "Das ist also der Kopf von Michiel Leerenwanderer. Der wird sich großartig auf einem Spieß machen. Für Eure Dienste habt Ihr den Respekt der Horde verdient, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[50234] = { id = 50234, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mannschaften von Freihafen" }
quests[50235] = { id = 50235, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Keine sichere Zuflucht", description = "Ich hab Rastakhan nach Zeb'ahari gebracht, um ihn dort zu versteck'n, {name}. Ich hätt nich' im Traum dran gedacht, dass Zuls Anhänger uns so schnell find'n würd'n.\n\nDie Bewohner von Zeb'ahari werd'n von jenen gejagt, die dem Propheten folg'n. Was ihnen jetz' zustößt, is' meine Schuld, weil ich den König in ihr Dorf gebracht hab.\n\nHelft, mir, sie zu rett'n, {name}. Findet alle, die noch geh'n könn', und schickt sie zu mir.\n\nFür die, die gestorben sin', kann ich nix mehr mach'n, aber wir könn' immer noch die Lebenden rett'n.", sourceObjective = "Rettet 12 Einwohner von Zeb'ahari.", completion = "Ich will denen helf'n, ihr Dorf zu sichern.\n\nBleibt wachsam, {name}. Zul wird nich' aufhör'n, solang das Schicksal vom alt'n Rastakhan ungewiss is'.", sourceObjectiveStatus = "unverified-source-field" }
quests[50238] = { id = 50238, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stacheldorn", description = "Ich habe mit Lord und Lady Scharfzahn gespielt, da hat mein Papi mich weggeholt. Ich habe den armen Lord Scharfzahn fallen lassen und eins von den großen, gemeinen Monstern hat ihn sich geschnappt!\n\nPapi hat gesagt, er wird mir helfen, ihn zurückzubekommen. Er ist aber schon lange weg und ich glaube, er ist zu sehr mit anderen Dingen beschäftigt. Mami und die anderen Erwachsenen erledigen ständig Dinge für Bürgermeister Reinwald.\n\nLady Scharfzahn und ich sind wirklich traurig. Könnt Ihr das böse Monster verhauen und meinen Dino retten?", sourceObjective = "Tötet Stacheldorn und holt Lord Scharfzahn zurück.", progress = "Habt Ihr Lord Scharfzahn gefunden? Ich glaube, eins von den riesigen Monstern hat ihn.", completion = "Yay! Oh. I-ihr habt jemanden gesehen? Meinen Papi?\n\n<Linda umarmt Ihr Spielzeug und schluchzt.>\n\nIch habe Mami schon lange nicht mehr gesehen. Hoffentlich geht es ihr gut.", sourceObjectiveStatus = "unverified-source-field" }
quests[50239] = { id = 50239, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Auswahl von Verbündeten", description = "Aufgrund meiner Erfahrung mit dem Eintritt der Pandaren in die Allianz wurde ich als Botschafter für unsere neuen Verbündeten auserkoren.\n\nIch habe eine Liste mit potenziellen Verbündeten gemacht, die der Allianz womöglich beitreten wollen.\n\nBringt mehr über sie in Erfahrung und kommt dann zu mir zurück.", sourceObjective = "Erfahrt mehr über potenzielle Verbündete.", progress = "Ihr müsst eine Entscheidung treffen, {class}.", completion = "Euer Rat ist stets willkommen, {name}. Die Wahl, die Ihr heute trefft, wird die Allianz stärken.", sourceObjectiveStatus = "unverified-source-field" }
quests[50240] = { id = 50240, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Es liegt mir auf der Zunge", description = "<Als Ihr Euch nähert, gestikuliert die blinde Zandalari ungeduldig.>\n\nHört sich an, als ob Ihr's eilig habt, kleiner Kümmerling!\n\nSetzt Euch und erzählt 'ner alten Trolldame 'ne Geschichte, bevor Ihr zum nächsten Abenteua loszieht.\n\nIch hab mit mei'm Pterrordax viele Abenteua erlebt, als ich jung war. Hab das ganze Tal erkundet!\n\nMein Pterrordax is' schon lange tot, aber...\n\n<Tra'wala die Blinde grinst schelmisch.>\n\nManchmal, nachts, klau ich den Wachen Leckerlis und überliste die ollen Pterrordaxe, damit sie mich reit'n lassen. Ha!", sourceObjective = "Stehlt eine Packung mit Pterrordaxleckerlis und benutzt sie, um auf einem Pterrordax tiefer in die Stadt vorzudringen.", sourceObjectiveStatus = "unverified-source-field" }
quests[50242] = { id = 50242, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Auswahl von Verbündeten", description = "Als Botschafter der Horde ist es meine Pflicht, die Ränge der Horde im Angesicht der Bedrohung zu stärken.\n\nAuf Euren Abenteuern habt Ihr viele getroffen, die die Horde unterstützen könnten, wenn wir sie davon überzeugen, sich unserer Sache anzuschließen.\n\nIch habe eine Liste mit den vielversprechendsten potenziellen Verbündeten. Wem ihr Euch zuerst widmet, überlasse ich Euch.", sourceObjective = "Erfahrt mehr über potenzielle Verbündete.", progress = "Ich erwarte eine eindeutige Entscheidung, {class}.", completion = "Ich lege großen Wert auf Eure Meinung, {name}. Die Wahl, die Ihr heute trefft, wird die Horde stärken.", sourceObjectiveStatus = "unverified-source-field" }
quests[50247] = { id = 50247, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Post muss fließen", description = "Bei all dem Trubel in letzter Zeit habe ich viel zu wenige Eilementare für das Sortieren der Briefe.\n\nEs ist wirklich einfach – werft einfach den Brief in das richtige Portal. Von dort werden sie in die entlegensten Winkel von Azeroth geschleudert.\n\nWarum machen wir nicht einfach ein Spiel daraus? Wie viele könnt Ihr in einer Minute sortieren?", sourceObjective = "Helft dem Postmeister dabei, mindestens 15 Briefe innerhalb des Zeitlimits zu sortieren.", completion = "Gute Arbeit!\n\nIst das nicht ein erfüllendes Gefühl? Zu wissen, dass man für die sichere Ankunft eines jeden Briefes sorgt?\n\nKommt jederzeit vorbei, um mir zur Hand zu gehen!", sourceObjectiveStatus = "unverified-source-field" }
quests[50248] = { id = 50248, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein zweiter Verbündeter", description = "Ihr habt einen wichtigen ersten Schritt zur Stärkung der Allianz gemacht, {name}. Gute Arbeit.\n\nDoch ich fürchte, ein einzelnes neues Bündnis wird die Horde nicht aufhalten. Der Kriegshäuptling wird nicht ruhen, bis Orgrimmars Kräfte den Verteidigern von Sturmwind zahlenmäßig klar überlegen sind.\n\nIch muss Euch bitten, weitere Verbündete für unsere Sache zu gewinnen. Wir müssen schnell handeln.", sourceObjective = "Wählt einen zweiten Verbündeten, dessen Unterstützung Ihr ersuchen wollt.", sourceObjectiveStatus = "unverified-source-field" }
quests[50249] = { id = 50249, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die dreifache Bedrohung von Boralus", description = "Wenn Tallis wirklich glaubt, dass wir die Südhafenwacht aufgeben, weil er willkürlich ein paar Soldaten ausschaltet, hat er sich geschnitten. Der einzige Grund dafür, dass wir die armseligen Truppen dieses Lagers noch nicht verjagt haben, ist, dass wir Dringenderes zu erledigen haben.\n\nFernns Leutnants richten die Kanonen der Wache gerade direkt auf Boralus. Sie sind der wahre Grund für den Angriff.\n\n<Der Marinesoldat blickt Euch besorgt an, als ihm klar wird, was er da sagt.>", sourceObjective = "Schaltet die drei Leutnants von Fernn aus.", completion = "Haben wir ihm endlich ein paar nützliche Informationen entlocken können?", sourceObjectiveStatus = "unverified-source-field" }
quests[50250] = { id = 50250, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eilsendung" }
quests[50251] = { id = 50251, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geschlossener Kreis", description = "<Der Dorfbewohner wird durch eine Bindungsrune gefangen gehalten. Die Zerstörung der Rune sollte ihn befreien.>", sourceObjective = "Zerstört 8 Bindungsrunen, um gefangene Dorfbewohner zu befreien.", completion = "Mich graust bei dem Gedanken, wofür sie die Leute benutzt haben könnten.", sourceObjectiveStatus = "unverified-source-field" }
quests[50252] = { id = 50252, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Paarungshalbzeit", description = "Kala und ich sind gescheitert. Voodoo und Wissenschaft ham nix gebracht. Ich bin ratlos.\n\nIch hoff, Ihr könnt uns helf'n, 'nen bessren Weg zu find'n. Die Brutosaurier ham 'ne Chance verdient!\n\nBitte schenkt uns was von Eurer Zeit. Vielleicht findet Ihr 'nen Weg, den wir nich' seh'n.", sourceObjective = "Entwerft eine Strategie mit Kala Kruxtopf und Hexendoktorin Jangalar, wie man mithilfe von Voodoo und Wissenschaft die vom Aussterben bedrohten Brutosaurier dazu bringen kann, sich fortzupflanzen.", completion = "Danke für Eure Hilfe, {name}. Das is' das Beste aus beiden Welt'n und nützt vielleicht den Brutosauriern.", sourceObjectiveStatus = "unverified-source-field" }
quests[50253] = { id = 50253, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein verbessertes Arsenal", description = "Ich verstehe nicht viel von der Schmiedekunst, aber ich bin ziemlich sicher, dass das nicht genug Silber ist, um alle Inquisitoren auszurüsten. Wir werden eine andere Verwendung dafür finden müssen.\n\nHoffen wir, dass Ballaster sich etwas... Kreatives einfallen lässt.", sourceObjective = "Sprecht mit Arnold Ballaster, um eine silberne Waffe bei der Wachmannshöhe anzufertigen.", progress = "Was kann der alte Arnold für Euch tun?", completion = "Was für eine Schönheit! Damals in der Marine haben wir unsere Musketen mit Metallsplittern vollgestopft, wenn uns die Kugeln ausgingen.\n\nDamit könnt Ihr mit Sicherheit genug Schaden verursachen!", sourceObjectiveStatus = "unverified-source-field" }
quests[50254] = { id = 50254, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein zweiter Verbündeter", description = "Ein neuer Verbündeter wird sich als nützlich erweisen. Ein zweiter stärkt uns noch viel mehr.\n\nDie Allianz schmiedet unermüdlich ihre Pläne. Wir müssen schnell handeln oder sie schlagen zu, bevor wir darauf vorbereitet sind.\n\nGebt mir Bescheid, wenn Ihr bereit seid, mit unserem nächsten Verbündeten in Verhandlungen zu treten. Wir dürfen jetzt nicht zögerlich sein.", sourceObjective = "Wählt einen zweiten Verbündeten, dessen Unterstützung Ihr ersuchen wollt.", sourceObjectiveStatus = "unverified-source-field" }
quests[50264] = { id = 50264, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rettung der Landarbeiter", description = "Wir sind herumgelaufen und haben versucht, den Hof unter Kontrolle zu bringen, aber die Bienen, oh meine Güte, die Bienen!\n\nDiese riesigen Ungeheuer kamen aus dem Nichts und haben alle mit Honig festgeklebt.\n\nIch habe hier oben nach Raimund gesucht, aber ehe ich mich versah, war auch ich festgeklebt.\n\nUnd dann ist das Komischste überhaupt passiert. Der Honig ist um mich herum gewachsen!\n\nDie anderen Landarbeiter stecken noch immer in Schwierigkeiten! Ihr müsst ihnen helfen!", sourceObjective = "Rettet die in Honig eingeschlossenen Landarbeiter.", completion = "In Honig gefangen nur noch darauf zu warten, gefressen zu werden, muss die Hölle gewesen sein!", sourceObjectiveStatus = "unverified-source-field" }
quests[50265] = { id = 50265, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Meister Eschtal retten", description = "Ich glaube, ich kann Meister Eschtal in einem Käfig sehen. Er muss befreit werden!\n\nDiese Hexen mit ihren langen Masken scheinen das Sagen zu haben. Ich wette, bei ihnen findet man auch das Nötige, um seinen Käfig zu öffnen.\n\nIch bleibe hier, passe auf Lehrling Nezz auf und sorge dafür, dass die Gegend sicher bleibt.", sourceObjective = "Nehmt einer Hexwaldbinderin einen Schlüssel ab und befreit Meister Eschtal.", completion = "Wir hatten in Eurer Abwesenheit einige Besucher, aber ich habe mich um sie gekümmert.\n\nEschtal ist wohlbehalten zurück, wirkt aber etwas mitgenommen. Er muss einige der Gräuel mitangesehen haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[50266] = { id = 50266, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bittersüß", description = "He!\n\nIch muss hier raus und zurück nach Falkenforst! Mein Gatte und ich haben nach dem Lieblingsspielzeug unserer Tochter gesucht, als ich entführt wurde. Bitte, ich muss hier raus! Ich muss sicher sein, dass meine Familie in Sicherheit ist.\n\nSie haben mir meine Ausrüstung abgenommen. Meine Sachen sind überall im Lager verstreut. Holt mich hier raus und besorgt mir meine Sachen, bitte!", sourceObjective = "Befreit Samantha Süß und holt ihre Sachen zurück.", completion = "Danke. Ich werde mir den Weg nach Falkenforst freikämpfen. Sie werden dafür bezahlen, was mit meiner Familie passiert ist!", sourceObjectiveStatus = "unverified-source-field" }
quests[50268] = { id = 50268, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mit ein wenig Geschmack", description = "Nun, ich muss zugeben, dass ich mich diesbezüglich jetzt etwas besser fühle. Wenn Hexendoktorin Jangalars Voodoo dafür sorgen kann, dass Ben'jin richtig reagiert, wie er es der Wissenschaft nach tun sollte, was haben wir dann zu verlieren?\n\nMeine Rezeptur sei gesegnet oder verhext oder wie immer man das bei Jangalars Voodookessel nennt.", sourceObjective = "Belegt Kalas Formel mit Voodoo und benutzt dazu Hexendoktorin Jangalars Kessel.", progress = "Wird es wegen dem Voodookram merkwürdig riechen? Schon gut, sinnlose Überlegungen.", completion = "Die Konsistenz ist immer noch dieselbe... Findet Ihr auch, dass es jetzt etwas kohlensäurehaltig wirkt?\n\nIch kann kaum erwarten, zu sehen, ob das hier besser wirkt als die ursprüngliche Formel... die EIGENTLICH einwandfrei hätte wirken müssen, wie ich hinzufügen möchte.", sourceObjectiveStatus = "unverified-source-field" }
quests[50270] = { id = 50270, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tief im Kern", description = "Hört zu, Ihr werdet zu einem Ort reisen müssen, der Tiefenheim genannt wird. Dort müsst Ihr dann einen Irdenen ausfindig machen.\n\nDer Typ, der mir das Rezept verkauft hat, sagte mir, dass er es von einem Irdenen bekommen hat, der sich... Ormhun nennt. Ormhun Haumichtot.\n\nLeider weiß ich nicht viel über diesen Ort, aber vielleicht könnt Ihr Euch ja bei den Einheimischen nach seinem Wohnort erkundigen.\n\nWenn es Euch nichts ausmacht, würde ich jetzt gerne weiter meine Rezepte an den Mann bringen.", sourceObjective = "Reist nach Sturmwind und nehmt das Portal nach Tiefenheim. Sucht nach Eurer Ankunft Ormhun Steinhammer auf.", completion = "Mich sucht Ihr also, was? Und womit kann der alte Ormhun einem Fleischling helfen?\n\n<Ihr erklärt Ormhun, dass Ihr versucht, einen khaz'gorischen Amboss zu finden.>\n\nHa! Viel Glück damit! Ich hab schon seit, oooh... Jahrhunderten keinen mehr gesehen.\n\nIhr habt allerdings Glück, dass ich weiß, wie man einen herstellen kann. Und Ihr gefallt mir.\n\nIch schätze, ich könnte eine Ruhestandspause einlegen und Euch bei einem letzten Herstellungsprozess helfen. Nach so langer Zeit, wird es schön sein, wieder an der Schmiede zu stehen. Muss nur meinen Hammer finden...", sourceObjectiveStatus = "unverified-source-field" }
quests[50271] = { id = 50271, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hammer und Tasche", description = "Die meisten Materialien, die wir brauchen, sind hier unten in Tiefenheim zu finden.\n\nWir müssen nur ein bisschen diskret zu Werke gehen. Wenn die alte Therazane Wind davon bekommt, was wir vorhaben, könnte sie versuchen, dem einen Riegel vorzuschieben.\n\nAber wir sollten uns darum keine Sorgen machen. Als Erstes braucht Ihr Diaminium. Im Alabasterschelf wachsen Säulen, in denen das reichlich vorkommt.\n\nBenutzt einfach Euren Schmiedehammer und zertrümmert diese Säulen. Macht Euch keinen Kopf, wenn das Diaminium auch zerbricht. Das schmelzen wir sowieso ein.", sourceObjective = "Geht zum Alabasterschelf und zertrümmert Diaminiumsäulen. Sammelt 60 Diaminium.", progress = "Das wird ein Spaß! Ich habe so einen Amboss schon seit Ewigkeiten nicht mehr hergestellt!", completion = "Oh, haben die Drachen gehört, wie Ihr alles zertrümmert habt? Ha ha! Ja, ich schätze, das hat ihre Aufmerksamkeit erregt.\n\nAber das hier dürfte trotzdem reichlich Diaminium sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[50272] = { id = 50272, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mit einem Ohr am Boden", description = "Das nächste benötigte Reagenz stammt aus den Mägen der Würmer, die sich hier durch den Boden wühlen.\n\nMan findet zwar überall viele Würmer, aber Ihr benötigt eine ganz bestimmte Art. Man sieht sie nur sehr selten an der Erdoberfläche, aber es gibt Mittel und Wege, um sie herauszulocken.\n\nIhr müsst nur genug Lärm machen, damit sie sauer werden! Ha ha! Wenn sie dann unter Euren Füßen herumwimmeln, benutzt diesen Stampfer, um sie herauszulocken.\n\nVersetzt ihnen den Todesstoß und holt das Metall aus ihren winzigen Mägen!", sourceObjective = "Geht in die Zackenwüste und sucht nach Anzeichen für Würmer. Für gewöhnlich wirbeln die ordentlich Staub auf, wenn sie sich unter der Erde bewegen. Benutzt einen Stampfer, damit sie an die Oberfläche kommen, tötet sie und sammelt 30 Endurit von ihnen ein.", progress = "Es ist schon eine Weile her, dass ich auf die Jagd nach Würmern gegangen bin.\n\nWir sind immer auf und ab gehopst, um sie zu ärgern, bevor wir die Stampfer hergestellt haben.", completion = "Ihr könnt nicht behaupten, dass Ihr keinen Spaß daran hattet, die Stampfer durch die Gegend zu werfen, stimmt's? Ha ha!\n\nAußerdem habt Ihr eine gute Ausbeute mitgebracht. Das dürfte reichen, um damit zu arbeiten.", sourceObjectiveStatus = "unverified-source-field" }
quests[50273] = { id = 50273, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Atal'Dazar: Die Hörner abstoßen", description = "Wir haben das Metall für die Basis und den Körper, aber da fehlt noch ein letztes Teil...\n\nDas Ambosshorn musste aus Ukrit bestehen. Aber das Metall gibt es seit Ewigkeiten nicht mehr.\n\nEs gibt noch ein anderes Metall, das ihm in Langlebigkeit kaum nachsteht. Es ist eine Art Gold, das die Trolle reichlich abgebaut haben. Und ich glaube, ich weiß, wo Ihr es findet.\n\nDie Trolle kontrollieren ein Gebiet, das Atal'Dazar heißt. Die ganze Stadt besteht aus dem Zeug. Wenn Ihr irgendetwas findet, das wie ein Horn aussieht, würde uns das die Mühe ersparen, ein ganz neues formen zu müssen.", sourceObjective = "Begebt Euch nach Atal'Dazar und holt das Goldene Horn von Rezan.", sourceObjectiveStatus = "unverified-source-field" }
quests[50274] = { id = 50274, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schmiedekunst der Titanen", description = "Seid Ihr bereit, <mein Junge/meine Liebe>?\n\nIhr werdet das Hämmern übernehmen, während ich mich um das letzte Reagenz kümmern werde, das wir brauchen.", sourceObjective = "Trefft Euch mit Ormhun in der Nähe der Berstenden Säulen und helft ihm, einen khaz'gorischen Amboss herzustellen.", completion = "Jetzt könnt Ihr ziemlich widerstandsfähige Ausrüstung herstellen. Aber Ihr solltet Euch lieber auf den Rückweg machen.", sourceObjectiveStatus = "unverified-source-field" }
quests[50275] = { id = 50275, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ambossangeberei", description = "Nehmt Euren Amboss und sprecht mit niemandem über die Herstellungsmethode.\n\nSollte ich herausfinden, dass Ihr Euch nicht daran haltet, könnte Euer nächster Besuch in meinem Reich ziemlich unangenehm werden.", sourceObjective = "Bringt den Amboss zu Grix Brennecke in Boralus.", completion = "Wie war das?! Ihr habt wirklich einen? Und Ihr habt ihn hierhergebracht?!\n\n<Grix reißt die Augen weit auf, als Ihr den Amboss neben ihm fallen lasst.>\n\nWisst Ihr, was das bedeutet? Es bedeutet, dass ich ab jetzt das DOPPELTE für die Anleitungen berechnen kann!\n\nIch danke Euch, {name}. Ihr seid ein erstaunlicher Schmied!", sourceObjectiveStatus = "unverified-source-field" }
quests[50276] = { id = 50276, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Anleitung für die Ewigkeit", description = "Sagt ma', Ihr seht so aus, als ob Ihr 'nen gut'n Hammer schwingen könnt, <Bruda/Schwesta>. Für sowas hab ich 'ne Nase.\n\n<Zak'aal grinst über beide Ohren.>\n\nHört zu. Ich hab 'ne Anleitung für den tollsten Schmiedehammer, den Ihr je geseh'n habt. Un' ich geb sie im Tausch für 'n bisschen Erz her.\n\nRebliserz, um genau zu sein. Is' ziemlich selten, aber in Atal'Gral gibt's reichlich davon. Die Naga dort mach'n da ihre Waffen draus.\n\nBringt mir 'ne Ladung davon un' die Anleitung gehört Euch!", sourceObjective = "Bringt Schmiedemeister Zak'aal 30 Stücke Rebliserz aus Atal'Gral in Zuldazar.", progress = "Die Anleitung is' locker taus'nd, wenn nich' ZEHNtaus'nd Gold wert! Schmiede überall werden auf Euch neidisch sein, Bruda.", completion = "Jo, jo! Das is' das Zeug!\n\nHier's die Anleitung, viel Spaß damit.", sourceObjectiveStatus = "unverified-source-field" }
quests[50277] = { id = 50277, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Informationen raushämmern", description = "Lasst mich rat'n. Ihr habt Euch die Anleitung angeseh'n un' gemerkt, dass Ihr 'nen khaz'gorischen Amboss für die Herstellung braucht. Un' Ihr wollt jetz' wissen, wo's 'nen khaz'gorischen Amboss gibt.\n\n<Bruda/Schwesta>, ich hab nie was davon gesagt, dass ich den Hammer mach'n kann. Wenn's recht is', muss ich jetz' noch mehr Anleitungen verkauf'n.", sourceObjective = "Bedrängt Schmiedemeister Zak'aal weiter, um mehr Informationen zu erhalten, wo ein khaz'gorischer Amboss zu finden ist.", completion = "Ruhig, Bruda. Ich sag Euch, was ich weiß.", sourceObjectiveStatus = "unverified-source-field" }
quests[50278] = { id = 50278, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tief im Kern", description = "Hört zu, Ihr müsst nach Tiefenheim geh'n und die dazu überred'n, Euch ihre Geheimnisse zu verrat'n. Da wurd der letzte Amboss gemacht, hab ich gehört.\n\nIch kenn auch nur einen Irdenen da unten, der Euch vielleicht hilft. Er heißt Ormhun Steinhammer.\n\nEr is'n Ausgestoßener, aber nich' so schwer zu find'n.", sourceObjective = "Reist nach Orgrimmar und nehmt das Portal nach Tiefenheim. Sucht nach Eurer Ankunft Ormhun Steinhammer auf.", completion = "Mich sucht Ihr also, was? Und womit kann der alte Ormhun einem Fleischling helfen?\n\n<Ihr erklärt Ormhun, dass Ihr versucht, einen khaz'gorischen Amboss zu finden.>\n\nHa! Viel Glück damit! Ich hab schon seit, oooh... Jahrhunderten keinen mehr gesehen.\n\nIhr habt allerdings Glück, dass ich weiß, wie man einen herstellen kann. Und Ihr gefallt mir.\n\nIch schätze, ich könnte eine Ruhestandspause einlegen und Euch bei einem letzten Herstellungsprozess helfen. Nach so langer Zeit, wird es schön sein, wieder an der Schmiede zu stehen. Muss nur meinen Hammer finden...", sourceObjectiveStatus = "unverified-source-field" }
quests[50279] = { id = 50279, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ambossangeberei", description = "Nehmt Euren Amboss und sprecht mit niemandem über die Herstellungsmethode.\n\nSollte ich herausfinden, dass Ihr Euch nicht daran haltet, könnte Euer nächster Besuch in meinem Reich ziemlich unangenehm werden.", sourceObjective = "Bringt den Amboss zu Schmiedemeister Zak'aal in Zuldazar.", completion = "Bitte was?! Ihr habt echt einen? Und habt ihn mitgebracht?!\n\n<Zak'aal reißt die Augen weit auf, als Ihr den Amboss neben ihm fallen lasst.>\n\nWisst Ihr, was das heißt, Bruda? Das heißt, ich kann jetz' das DOPPELTE für die Anleitungen nehmen!\n\nDanke, {name}. Ihr seid 'n Hammaschmied!", sourceObjectiveStatus = "unverified-source-field" }
quests[50287] = { id = 50287, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Endlose Gorillakriegsführung" }
quests[50288] = { id = 50288, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Therazanes Wahl", description = "<Ihr erklärt, dass Ihr keinesfalls respektlos gegenüber Therazane sein oder ihre Geheimnisse stehlen wollt.>\n\nInteressant...\n\nIch habe eine großartige Idee, wie man dieses Problem lösen kann. Würdet Ihr sie gerne hören?", sourceObjective = "Hört Euch Therazanes Vorschlag an.", progress = "Wer hätte geglaubt, dass man einer Kreatur wie Euch so bereitwillig unsere Geheimnisse überlässt.\n\nIch schätze, ich muss die Vorgänge in meinem Reich genauer im Blick behalten.", completion = "Ihr habt Eure Entscheidung getroffen. Und eine interessante noch dazu.", sourceObjectiveStatus = "unverified-source-field" }
quests[50295] = { id = 50295, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zum Zähne ausbeißen", sourceObjective = "Tötet 25 Wendigos.", sourceObjectiveStatus = "unverified-source-field" }
quests[50296] = { id = 50296, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ziegenbockbarbier", sourceObjective = "Verwendet die Ziegenschere bei 6 sanftmütigen Ziegen.", sourceObjectiveStatus = "unverified-source-field" }
quests[50297] = { id = 50297, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Kopf ihres Feindes", description = "Ihr habt was Wunderbares gemacht, {name}. Düsterschweif is' tot un' Maka'fon muss nich' mehr unter den Klingenschwingen leid'n. Sieht so aus, als ob Düsterschweif schon vor 'ner ganzen Weile ihre Eier kaputtgemacht hat.\n\nBringt Düsterschweifs Kopf zu Maka'fon als Beweis, dass er weg is'. Wenn sie dann Ben'jins Geruch drauf findet, wird sie wieder 'n würdig'n Paarungspartner such'n.\n\nWenn Ben'jin das merkt, wird er sich ihr nähern un' die Natur nimmt ihr'n Lauf.", sourceObjective = "Legt Düsterschweifs Kopf vor Maka'fon ab, damit sie weiß, dass ihr Revier dank Ben'jin wieder sicher ist.", progress = "Nehmt Düsterschweifs Kopf un' gebt ihn Maka'fon. Seh'n wir mal, was dann passiert.", completion = "Das is'n toller Moment un' ich hab Hoffnung, dass diese Brutosaurusart weiterleben un' hier im Dschungel gedeih'n wird.", sourceObjectiveStatus = "unverified-source-field" }
quests[50299] = { id = 50299, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Greifen greifen" }
quests[50300] = { id = 50300, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Ruf des Sprechers", sourceObjective = "Trefft Euch mit Magni Bronzebeard an der Wunde in Silithus.", sourceObjectiveStatus = "unverified-source-field" }
quests[50303] = { id = 50303, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fremder in einem fremden Land", description = "Hallo, ich bin Botschafter Schwarzwacht.\n\nEs ist mir eine Ehre, Euch in Orgrimmar willkommen zu heißen, {race}.\n\n<Er lächelt gekünstelt.>\n\nNun, da sich ein Leben voller Abenteuer vor Euch auftut, seid versichert, dass... ähm...\n\nWisst Ihr was? Ich habe diese Begrüßung heute den ganzen Tag immer wieder abgespult. Mir reicht's.\n\nSprecht mit Chromie auf dem Stundenglas. Und dann sprecht mit Eurem Abgesandten. Kusch!", sourceObjective = "Sprecht mit Chromie in Orgrimmar.", completion = "Hier sind wir also: Orgrimmar. Die Orcs haben einen... interessanten Sinn für Ästhetik. Gebt Acht auf die Stacheln, {name}.\n\nUnd die Gerüche... So viele Gerüche.", sourceObjectiveStatus = "unverified-source-field" }
quests[50305] = { id = 50305, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fremder in einem fremden Land", description = "Willkommen in Sturmwind, {race}. Ich lade Euch ein, unsere prächtige Stadt zu erkunden. Hm, Ihr seht aus wie jemand, dem das Nachtleben zusagt. Wir haben viele beliebte Tavernen und eine pulsierende Musikszene!\n\nAber das kann warten. Ein Bronzedrache wollte Euch sprechen. Sie sitzt unter dem Baum in der Nähe, ausgerechnet auf einem Stundenglas!\n\nUnd danach erwartet Euch ein Abgesandter der Ren'dorei, der Euch in der Stadt willkommen heißen will. Klingt, als hättet Ihr einen langen Tag vor Euch!\n\nIch wünsche einen angenehmen Aufenthalt, {name}!", sourceObjective = "Sprecht mit Chromie in Sturmwind.", progress = "Und? Entspricht Sturmwind Euren Erwartungen?", completion = "Willkommen in Sturmwind. Es ist nicht gerade Silbermond, aber die Stadt hat ihre Reize.\n\nFalls Ihr eine herzliche Begrüßung erwartet habt, nun, ich kann nicht sagen, ich selbst hätte eine bekommen, aber die meisten hier sind recht höflich.\n\nEinerlei. Ich suche mir jetzt ein Abenteuer! Vielleicht auch nur einen Durstlöscher.", sourceObjectiveStatus = "unverified-source-field" }
quests[50306] = { id = 50306, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dies und Das", description = "Meister Eschtal wird wohl etwas Belebendes brauchen, sobald wir ihn befreit haben. Ich kenne einen Trank, der sich schnell zubereiten lässt und jeden wach kriegt, aber dazu brauche ich erst einige Dinge.\n\nDiese Weidenhunde da unten verfügen über organisches Material, das ich nutzen kann, und die Hexen tragen Taschen mit Reagenzien bei sich. Da ist mit ziemlicher Sicherheit drin, was ich brauche.\n\nBringt mir diese Sachen, dann kümmere ich mich um den Rest, sobald wir Meister Eschtal wiederhaben.", sourceObjective = "Sammelt 4 Proben organischen Materials und 3 Taschen mit Reagenzien.", progress = "Habt Ihr etwas erreicht?", completion = "Hmm... Sehr interessant. Und penetrant. Vielleicht sollte ich als Erstes den Geruch irgendwie beseitigen.", sourceObjectiveStatus = "unverified-source-field" }
quests[50313] = { id = 50313, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fremder in einem fremden Land", description = "Willkommen in Sturmwind, {race}. Ich lade Euch ein, unsere prächtige Stadt zu erkunden. Hm, Ihr wirkt mir recht fromm. Wir haben hier eine traumhafte Kathedrale, die Euch bestimmt interessieren wird!\n\nAber das kann warten. Ein Bronzedrache wollte Euch sprechen. Sie sitzt unter dem Baum in der Nähe, ausgerechnet auf einem Stundenglas!\n\nUnd danach erwartet Euch ein Abgesandter der Lichtgeschmiedeten, der Euch in der Stadt willkommen heißen will. Klingt, als hättet Ihr einen langen Tag vor Euch!\n\nIch wünsche einen angenehmen Aufenthalt, {name}!", sourceObjective = "Findet Chromie in Sturmwind.", progress = "Ich kann das Licht hier spüren.", completion = "Willkommen in dieser wunderschönen Stadt, {name}. Ich bin sicher, die anderen Mitglieder der Allianz empfangen Euch mit genauso offenen Armen wie mich.\n\nIch habe bereits einige der Stadtwachen getroffen. Aufrechte Männer und Frauen allesamt, aber wir könnten ihnen noch das ein oder andere beibringen.", sourceObjectiveStatus = "unverified-source-field" }
quests[50315] = { id = 50315, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nicht eingeplant" }
quests[50316] = { id = 50316, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Störung entdeckt: Ulduar", description = "Ihr seid spät dran. Erinnert Ihr Euch noch an das letzte Mal, als wir uns den Machenschaften stellen mussten, die zu Yogg-Sarons Ausbruch aus seinem Gefängnis unter Ulduar führten? Damals wart Ihr auch spät dran. Ihr solltet wirklich versuchen, pünktlicher zu sein.\n\nNa dann, auf, auf! Alte Götter! Hüter! Titanenzeug! Hakt das auf Eurer Liste ab, damit wir weitermachen können. Wir haben Zeiten und Orte zu besuchen.\n\n<Vormu bedeutet Euch hektisch, zu verschwinden.>", sourceObjective = "Durchlebt die Expedition nach Ulduar erneut.", progress = "Es muss genau dieselbe Anzahl gebratener Zwerge sein, wie letztes Mal. Medium natürlich – gut durch währe völliger Wahnsinn.", completion = "Also das ist beunruhigend. Die Titanenschlösser, die Yogg-Saron festhalten, scheinen gealtert, aber nicht auf natürliche Weise. Die hier sollten mindestens für weitere 40.000 Jahre halten. Aber die Einzigen mit der nötigen Macht für so eine Manipulation sind tot... oder nicht? Vielleicht... nein, das ergibt absolut keinen Sinn.", sourceObjectiveStatus = "unverified-source-field" }
quests[50318] = { id = 50318, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein rechtzeitiger Ruf aus Nordend", description = "Das Gleißen ertrinkt im Schatten einer stellaren Masse, die die Seher mit Entsetzen erfüllt. Findet die Seherin Vormu in Dalaran und bietet Ihr Eure Hilfe an.\n\nNein, nicht dieses Dalaran, das andere. Ja, ich weiß, es ist schrecklich verwirrend.", sourceObjective = "Trefft Euch mit Vormu in Dalaran über dem Kristallsangwald.", completion = "Wir sind nicht im Zeitplan. Marsch, marsch.", sourceObjectiveStatus = "unverified-source-field" }
quests[50319] = { id = 50319, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fremder in einem fremden Land", description = "Hallo, ich bin Botschafter Schwarzwacht.\n\nEs ist mir eine Ehre, Euch in Orgrimmar willkommen zu heißen, {race}.\n\n<Er lächelt gekünstelt.>\n\nNun, da sich ein Leben voller Abenteuer vor Euch auftut, seid versichert, dass... ähm...\n\nWisst Ihr was? Ich habe diese Begrüßung heute den ganzen Tag immer wieder abgespult. Mir reicht's.\n\nSprecht mit Chromie auf dem Stundenglas. Und dann sprecht mit Eurem Abgesandten. Kusch!", sourceObjective = "Sprecht mit Chromie.", completion = "So viele Tauren! Ich glaube, seit ich hier bin, habe ich mehr Tauren gesehen als in meinem Leben am Hochberg.\n\nSie wollen alle mein Geweih anfassen. Das war am Anfang etwas schräg, aber jetzt mag ich es irgendwie.", sourceObjectiveStatus = "unverified-source-field" }
quests[50321] = { id = 50321, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mojounfug", description = "Die von Euch geretteten Soldaten sprach'n von Überfällen auf Zandalar. Bluttrollräuber mit Schaum vorm Mund und übernatürlichen Kräften überwältigt'n die Verteidiger.\n\nSie sagten, diese Kräfte kämen von Mojofläschchen, aus denen die Räuber vor dem Kampf trank'n. Wir können nicht zulass'n, dass die Bluttrolle sie weiterhin besitz'n.\n\nGeht runter ins Lager und zerstört alle Fläschchen, die Ihr finden könnt.", sourceObjective = "Zerstört 6 Fläschchen zähflüssiges Mojo.", sourceObjectiveStatus = "unverified-source-field" }
quests[50322] = { id = 50322, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein gefiederter Trend" }
quests[50324] = { id = 50324, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zischfeders idyllisches Resort" }
quests[50325] = { id = 50325, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schluss mit dem Großritual", description = "Die Blutholzhexen planen einen Großritus, ein sehr mächtiges Ritual. Sie beabsichtigen, einen Riss in der Realität zu öffnen, um ihren dunklen Meister hindurchzuholen!\n\nIch vermute, dass sie mit Gorak Tul unter einer Decke stecken. Wir können nicht zulassen, dass sie das Ritual erfolgreich abschließen.\n\nIhr müsst meine Speerspitze sein, während ich Meister Eschtal und Martin beschütze. Sorgt für Chaos und unterbrecht ihre Rituale!", sourceObjective = "Zerstört die Ritualfokusse.", completion = "Verdammt! Wir haben sie zwar verlangsamt, aber sie arbeiten noch immer an diesem Ritual. Um sie endgültig aufzuhalten, müssen wir noch mehr tun.", sourceObjectiveStatus = "unverified-source-field" }
quests[50327] = { id = 50327, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hallo Wach", description = "Jetzt muss das vermischt werden.\n\n<Martin beginnt, die Zutaten in einem Becher zu vermengen.>\n\nIch benutze ziemlich starken Grog als Grundlage, einen Tropfen Chiliextrakt und eine Handvoll Herdblumen... Da!\n\n<Martin gibt Euch einen Becher.>\n\nEs schmeckt schlimmer, als es riecht, aber es wird Meister Eschtal wieder zu Verstand bringen. Bitte gebt ihm diesen Becher.", sourceObjective = "Gebt Meister Eschtal den Becher.", completion = "Oh! Meine Güte!\n\n<Eschtal schüttelt sich und hustet.>\n\nEin bisschen weniger Herdblume nächstes Mal, Martin, aber sonst hat es seinen Zweck erfüllt. Das habt Ihr beide gut gemacht.", sourceObjectiveStatus = "unverified-source-field" }
quests[50328] = { id = 50328, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ungewöhnliche Aromen", description = "Abgemacht ist abgemacht. Ihr habt mir die Stacheln besorgt, also bekommt Ihr von mir auch den großen Batzen Honig, den ich Euch versprochen hatte.\n\nIch hoffe, Ihr und Rhan'ka werdet ihn genießen... aber schön langsam. Das ist mein Ernst. Esst bloß nicht alles auf einen Schlag!\n\nAch ja, und ich bin eigentlich immer an Geschäften interessiert... Wenn Ihr also mal was verkaufen oder noch mehr Honig haben wollt, schaut einfach vorbei!", sourceObjective = "Liefert den Eiterschwingen-\"Honig\" bei Rhan'ka im Goldhauer ab.\n\nBereitgestellter Gegenstand:", completion = "Den Loa sei Dank, dass die Sandwüter Euch nich' getötet und Euch die feinen Sachen abgenomm'n ham.\n\nDie Getränke sind fast fertig, aber perfekt werd'n die bloß mit den Zutaten, die Ihr mir geliefert habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[50329] = { id = 50329, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Matronen vom Blutholz", description = "Die Hexen, die hier das Sagen haben, diese Matronen...\n\n<Eschtal schaudert und nimmt sich dann zusammen.>\n\nDie Matronen sind die treibende Kraft hinter dem Großritus. Sie sind furchterregend, aber nicht unverwundbar. Wenn Ihr ein paar von ihnen ausschalten könntet, hätten wir eine größere Chance, diesem Treiben ein Ende zu bereiten.\n\nNehmt diesen Trank. Er wird die Matronen schwächen. Dann habt Ihr vielleicht eine bessere Chance, sie zu töten.", sourceObjective = "Tötet die Matronen Elsbeth Gerrik, Stefania Wehrheim und Wilona Pechwald.", progress = "Habt Ihr sie getötet?", completion = "Der Trank hat sogar noch besser als erwartet gewirkt! Es ist doch sehr ermutigend, dass die Zeit, die ich in der... Obhut der Hexen verbracht habe, Früchte getragen hat.\n\nDer Verlust ihrer Anführerinnen ist auf jeden Fall ein Rückschlag für sie.", sourceObjectiveStatus = "unverified-source-field" }
quests[50331] = { id = 50331, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein anderes Resultat", description = "Es lässt sich unmöglich sagen, wann diese Befehle losgeschickt oder erhalten wurden.\n\nRokor ist vor einiger Zeit mit ein paar Suchern nach Norden aufgebrochen. Sie müssten mittlerweile dort sein.\n\nWarnt Gral und seine Anhänger, falls der Tempel noch steht.\n\nSollte schon alles verloren sein, müssen wir tun, was in unserer Macht steht.", sourceObjective = "Findet Rokor in der Nähe von Atal'Gral im Norden.", completion = "Ich fürchte, der Fund dieser Befehle kommt zu spät, um denen zu helfen, die hier gedient haben... etwa fünf Jahre zu spät.", sourceObjectiveStatus = "unverified-source-field" }
quests[50332] = { id = 50332, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Großa Jägamacka", description = "In dies'n Tälern hält der Macka die Tiere am Leb'n, nur damit sie sei'm Vergnüg'n dien'. Für seine Unterhaltung.\n\nDie Leben von andern sind nich' so billig. Auch die kleinste Kreatur kann 'nen Haufen Ärger mach'n. Der Macka muss lern', das zu respektier'n.\n\nIch glaub', jetz' is' die rechte Zeit, um dem groß'n Jägamacka 'ne Lektion zu erteil'n, meint Ihr nich'? Wollt Ihr treu meine Botschaft überbring'n?", sourceObjective = "Überlebt Janis Streich für Nesingwary.\n\nWenn Ihr Eure Sauridenverkleidung verliert, kehrt zu Jani zurück und besorgt Euch eine neue.", progress = "Habt Ihr dem groß'n Jägamacka schon mein Geschenk gebracht, Zastamann?", completion = "Haha! Gut gemacht, Zastamann. Der große Jägamacka wird Woch'n brauch'n, um den Gestank aus seinem Munitionsvorrat zu krieg'n. Ganz zu schweig'n von den Füß'n. Ihr seid in meiner Gunst gestieg'n.", sourceObjectiveStatus = "unverified-source-field" }
quests[50335] = { id = 50335, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vollstreckt meine Rache", description = "Es kümmert mich nicht, wem Ihr die Treue schwört, {race}. Hogger muss sterben!\n\nEr und diese anderen Kretins in diesem vom Licht verlassenen Loch haben meine Männer abgeschlachtet. Die Allianz und die Horde mögen ihre Streitigkeiten haben, aber ihr solltet wissen, dass ein kaltblütiger Mord an meinen Leuten nicht ungesühnt bleiben wird.", sourceObjective = "Bezwingt Randolph Moloch, Fürst Gluthitze und Hogger.", progress = "Ist es getan? Ist Hogger tot?", completion = "Der Aufstand ist niedergeschlagen, die Elemente sind beruhigt und Hogger ist niedergestreckt... Ich kann Euch nicht genug danken, {name}. Meine Leute wurden gerächt.\n\nVielen Dank.", sourceObjectiveStatus = "unverified-source-field" }
quests[50336] = { id = 50336, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das G-Team", description = "Ich würde mich von Bi'ay Bäräkuss und Mör'dok geflissentlich fernhalten – die sind beide nicht ganz dicht. \n\nDann an die Arbeit! Geht diesen Tunnel entlang, bis Ihr zum Tüftlerhof kommt. Hoffentlich wisst Ihr, was zu tun ist, wenn Ihr Robogenieur Thermadraht begegnet.\n\nUnser Anführer, Kommandosoldat Hann Ibal, möchte Euch irgendwo da drin treffen. Er wird Euch reich für Eure Bemühungen belohnen.\n\nWahrscheinlich...", sourceObjective = "Tötet Robogenieur Thermadraht.", completion = "Ich hätte Euch liebend gern als vollwertigen G-Team-Kommandosoldaten, aber unsere Statuten verbieten die Aufnahme von Hordenmitgliedern ausdrücklich. Dafür könnt Ihr Mitglied im G-Team-Fanclub werden!\n\nHier ist etwas für Eure Unannehmlichkeiten.", sourceObjectiveStatus = "unverified-source-field" }
quests[50337] = { id = 50337, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das G-Team", description = "Dieser Mör'dok ist verrückt, {class}. Passt bloß auf, dass Ihr niemals mit diesem Gnom in einem Flugzeug sitzt.\n\nVerstohlenheit ist normalerweise nicht mein Ding, und sie wird ganz bestimmt auch nicht Eures sein. Geht diesen Flur entlang bis zur Abschussrampe und kümmert Euch um den Elektrokutor 6000.\n\nDer Elektrokutor ist verantwortlich für die Luftfahrzeuge...\n\n... und ich hasse Luftfahrzeuge. Mich bekommt man in kein Luftfahrzeug!\n\nBenutzt diesen Fallschirm, um anschließend abzuspringen und sprecht mit Kommandosoldat Fähs über Eure nächste Aufgabe.", sourceObjective = "Vernichtet den Elektrokutor 6000.", completion = "Hat ja lange genug gedauert. Los, hinter die Säule, bevor Ihr unsere Tarnung auffliegen lasst!", sourceObjectiveStatus = "unverified-source-field" }
quests[50338] = { id = 50338, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das G-Team", description = "Wie seid Ihr hier reingekommen, {name}?\n\nIch bin Mör'dok vom G-Team. <Ein/Eine:r> {race} kommt uns gerade richtig!\n\nHelft uns, die verstrahlten Wesen zu besiegen, die sich in Gnomeregan eingenistet haben, dann mache ich Euch zu <einem G-Team-Kommandosoldaten/einer G-Team-Kommandosoldatin> ehrenhalber!\n\nNehmt diesen Fallschirm, springt hinunter in die Halle der Zahnräder und besiegt die verflüssigte Ablagerung. Wenn Ihr fertig seid, meldet Euch bei Kommandosoldat Bi'ay Bäräkuss im westlichen Korridor. Ihr beide werdet Euch mit Sicherheit gut verstehen.", sourceObjective = "Tötet die verflüssigte Ablagerung.", completion = "Diese Mission ist noch lange nicht zu Ende!", sourceObjectiveStatus = "unverified-source-field" }
quests[50340] = { id = 50340, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zurückgeklaut", description = "<Die leere Vorratskiste ist deutlich mit dem Emblem von Kul Tiras gekennzeichnet. Das muss die Beute ihrer Überfälle auf die Höfe im Tal sein.\n\nDie Bewohner wollen sicher ihre Vorräte zurück, sofern noch welche übrig sind.>", sourceObjective = "Beschafft 5 gestohlene Kisten.", progress = "Haltet Ausschau nach allem, was irgendwie nützlich sein könnte. Dieser Ort ist sehr gefährlich.", completion = "Wir klauen sie ja nicht wirklich. Wir holen sie uns nur zurück. Hey! Sind das meine Glücksanker?", sourceObjectiveStatus = "unverified-source-field" }
quests[50341] = { id = 50341, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine neue Entdeckung", description = "Heute haben sich die Anführer der Horde für ein Festmahl zur Feier unseres Sieges über die Brennende Legion versammelt.\n\nWährend die anderen gegessen haben, hat Gallywix um eine Audienz mit der Dunklen Fürstin gebeten.\n\nOffenbar hat er eine mysteriöse Substanz in Silithus gefunden... ein magisches Erz. Anders als alles, was wir kennen.\n\nDer Kriegshäuptling hat mich angewiesen, Euch mit den Details vertraut zu machen und auf einen Spezialauftrag vorzubereiten.", sourceObjective = "Sprecht mit Nathanos Pestrufer.", completion = "Die Dunkle Fürstin hat befohlen, dass Ihr persönlich die Operation in Silithus überwacht.", sourceObjectiveStatus = "unverified-source-field" }
quests[50343] = { id = 50343, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mutig in die Metbrauerei Mildenhall", description = "Ahhhh! <Mein Herr/Meine Dame>, bitte helft mir!\n\nMein Papa ist nicht aus der Brauerei zurückgekehrt... Und als ich dort nachsehen wollte, waren überall riesige Honigklumpen.\n\nAber... aber... irgendwie haben die sich von selbst bewegt. Ein Honigklumpen hat sogar einen Hasen gefressen, ich schwöre!\n\nIch habe Angst, alleine zurückzugehen, aber mein Papa ist sicher in Schwierigkeiten.\n\nKönnt Ihr mich begleiten?", sourceObjective = "Untersucht die Metbrauerei Mildenhall.", completion = "Wo kommen all diese Dinger nur her?", sourceObjectiveStatus = "unverified-source-field" }
quests[50349] = { id = 50349, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Überrannte Mine", description = "Es war furchtbar! Ich war in der nahegelegenen Mine und habe nur auf einen Felsen eingehackt, da sprang er plötzlich hoch und biss mich in den Hals! Seit wann können Felsen herumlaufen und Leute beißen?\n\nNichts wie weg, dachte ich, und gab Fersengeld, aber ein paar Verrückte sind immer noch da und versuchen, die Mine zurückzuerobern. Wenn Ihr gerne auf Felsen einschlagen wollt, dann nehmt die Straße nach Süden, bis Ihr sie findet.", sourceObjective = "Findet den leitenden Minenarbeiter Theock im Winterschlundförderlager.", completion = "Wieso tragt Ihr keine Bergbaukappe?! Es ist gefährlich hier draußen! Hier, setzt die auf.\n\nUnd jetzt habe ich eine Aufgabe für Euch. Wirklich einfach.", sourceObjectiveStatus = "unverified-source-field" }
quests[50350] = { id = 50350, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Chemiker gesucht", description = "Das ganze Chaos begann, als wir ein großes Azeritvorkommen tief in der Mine abbauen wollten. Die Mine fing an zu grollen, und diese ganzen verfluchten Kreaturen brachen aus dem Boden hervor. Ich bin sicher, dass wir die Mine zurückerobern können, wenn wir nur diese Ader schließen.\n\nAls Erstes brauchen wir einen Chemiker. Der beste, den wir haben, ist in seinem Labor auf der anderen Flussseite. Sucht ihn auf, er wird Euch dann weitere Anweisungen geben.", sourceObjective = "Findet den obersten Chemiker Walters.", sourceObjectiveStatus = "unverified-source-field" }
quests[50351] = { id = 50351, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gute Mine im bösen Spiel", description = "Die Mine steckt wirklich in Schwierigkeiten. Wir graben dort schon seit einer Weile, aber so etwas habe ich noch nie gesehen. Azerit steht nicht einfach auf und läuft herum.\n\nWenn wir die Mine zurückerobern wollen, brauchen wir mehr Hilfe. Wir brauchen einen Ingenieur und einen Sprengstoffexperten. Mir schweben zwei vor, zwei Schwestern, um genau zu sein, aber sie sind jenseits des Flusses in das ganze Chaos hineingeraten.\n\nFindet die Schwestern. Sie werden Euch bei der nächsten Phase des Plans helfen.", sourceObjective = "Findet Bautechnikerin Alena und Sprengstoffexpertin Prim.", completion = "Gut. Alle sind da.", sourceObjectiveStatus = "unverified-source-field" }
quests[50352] = { id = 50352, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Prise Azerit", description = "Ich habe keine Zeit für albernes Geplauder! Falls Ihr es noch nicht bemerkt habt, die Steine sind zum Leben erwacht und führen nichts Gutes im Schilde!\n\nIhr könnt mir helfen und meine Chemikerausrüstung zurückholen. Und wenn Ihr sowieso da draußen seid, dann erledigt doch ein paar dieser Kreaturen und bringt mir deren Staub. Prim wird beides für den nächsten Schritt ihres Plans brauchen.\n\nVielleicht finden wir heraus, was dieses Azerit zum Leben erweckt hat.", sourceObjective = "Besorgt 45 Azeritstaub und Walters' Chemikerausrüstung.", progress = "Habt Ihr den Staub mitgebracht?", completion = "Gute Arbeit! Jetzt werden wir damit etwas Sinnvolles machen.", sourceObjectiveStatus = "unverified-source-field" }
quests[50353] = { id = 50353, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Yippie-Ya-Yeah, Schweinebacke", description = "Ich sehe hier nirgendwo ihren Leichnam. Das heißt, dass sie vielleicht noch am Leben ist.\n\nDie Borstenrücken haben Gefangene gemacht und alle, die sie jemals verschleppt haben, wurden nie wieder gesehen.\n\nUns bietet sich eine einzigartige Gelegenheit und wir müssen sie nutzen!\n\nDringt mit mir in den Kral ein und befreit so viele Überlebende wie möglich. Und falls Ihr Bäuerin Deike findet, seht nach, ob sie noch lebt.", sourceObjective = "Findet und rettet 7 gefangene Bauern und Bäuerin Deike.", completion = "Ich war sicher, dass sie erledigt sind. Vielen Dank.", sourceObjectiveStatus = "unverified-source-field" }
quests[50354] = { id = 50354, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Augen auf!", description = "Einige dieser Stacheleber sind offensichtlich Späher. Das erkennt man ganz leicht an diesen Hörnern. Fast so, als ob ihre Aufgabe direkt über ihren Köpfen angezeigt würde.\n\nIch konnte einen töten, war aber nicht schnell genug. Er konnte noch in sein Horn stoßen und Verstärkung rufen. Ich schlage vor, Ihr tötet sie leise, sonst passiert Euch dasselbe.\n\nWenn wir hier drin nicht mucksmäuschenstill sind, kommen wir nicht weit. Hier, Hobbs hat mir einige seiner Schlafpfeile gegeben. Damit stellen wir sie ruhig.", sourceObjective = "Tötet 6 Ausgucke der Borstenrücken.", completion = "Kaum zu glauben, dass ich es hierher geschafft habe. Dieser Ort ist so schwer bewacht...", sourceObjectiveStatus = "unverified-source-field" }
quests[50356] = { id = 50356, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stein trifft Dynamit", description = "Danke für Eure Hilfe da draußen, aber wir müssen Euch um einen weiteren Gefallen bitten.\n\nDiese Elementare kommen irgendwo aus der Mine und wir brauchen Euch, um die Quelle zu finden.\n\nIhr kommt zwar da drin offensichtlich selbst gut zurecht, aber zur Sicherheit gebe ich Euch noch etwas von Prims Spezialdynamit mit. Durch den Azeritstaub, den Ihr gesammelt habt, ist es noch stärker als sonst.\n\nGeht rein, findet die Quelle und stoppt diese Elementare.", sourceObjective = "Versiegelt die Quelle der Azeritkreaturen.", completion = "Ein Trogg? Hmmm... Er hat bestimmt schon einiges an Azerit verputzt, um zu so etwas in der Lage zu sein.\n\nJetzt, wo er erledigt ist, können wir uns der übrigen Kreaturen entledigen und weitergraben! Danke für Eure Hilfe!", sourceObjectiveStatus = "unverified-source-field" }
quests[50358] = { id = 50358, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wüstenforschung", description = "Sargeras' dunkle Klinge hat einen Schatten der Zerstörung über das Land geworfen.\n\nBei dem Angriff scheinen die Silithidenschwarmstöcke zerstört worden zu sein, jedoch erreichen mich Berichte, dass die Silithiden zurückkehren.\n\nWenn es nach mir ginge, würde ich diese verfluchten Schwarmstöcke allesamt einfach abfackeln. Aber es geht nicht nach mir.\n\nDie Dunkle Fürstin wünscht, dass die überlebenden Silithiden seziert und untersucht werden.\n\nPixni Rostbombe leitet die Untersuchung und braucht dringend jemanden, der \"Proben einsammelt\".", sourceObjective = "Sprecht mit Pixni Rostbombe.", completion = "Seid Ihr gekommen, um die Proben einzusammeln? Wird auch Zeit, dass sie endlich Hilfe schicken.", sourceObjectiveStatus = "unverified-source-field" }
quests[50359] = { id = 50359, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Putztrupp gesucht", description = "Wa... Warum lebt dieser Honig und warum ist niemand mehr hier?\n\nIhr denkt doch nicht etwa... Oh nein! Bitte, {name}, sagt mir, dass sie nicht gefressen wurden!\n\nAhhhh! Das wäre ja schrecklich! Bitte, ich will nicht gefressen werden!", sourceObjective = "Tötet 4 fließenden Honig und 4 blubbernden Met.", completion = "Danke, dass Ihr diese Dinger beseitigt habt, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[50360] = { id = 50360, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Khadgars Bitte", description = "Während Eurer Abwesenheit ist Erzmagier Khadgar eingetroffen. Er ist scheinbar gekommen, um mit Euch zu reden, {name}.\n\nFindet schnell heraus, was er möchte. Ich will, dass er schleunigst wieder von hier verschwindet.\n\nEin Mensch, der seine Nase in die Angelegenheiten der Horde steckt, ist wirklich das Letzte, was wir brauchen.", sourceObjective = "Sprecht mit Erzmagier Khadgar.", completion = "Schön, Euch zu sehen, {name}. Mir schwant, dass ich die Gastfreundschaft der Horde mir gegenüber langsam ausgeschöpft habe.", sourceObjectiveStatus = "unverified-source-field" }
quests[50363] = { id = 50363, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kriegsschweine", description = "Sie mögen putzig aussehen, aber da wird eine neue Herde Kampfschweine ausgebildet.\n\nBauern mögen keine Verschwendung und es wäre sehr schade, solch nützliche Kreaturen zu beseitigen.\n\nWie auch immer, wir könnten diese Schweine brauchen und ich hätte sie lieber bei uns, als mich in ein paar Jahren mit einem blutdürstigen Eber herumschlagen zu müssen. Ihr findet sie oben an den Klippen, die das Zentrum des Krals überragen. Treibt so viele Ferkel wie möglich zusammen und wir finden eine gute Verwendung für sie.", sourceObjective = "Fangt 8 grasende Kampfferkel ein.", completion = "Ich werde sie mitnehmen und dafür sorgen, dass sie auf den Höfen eine vernünftige Ausbildung bekommen.", sourceObjectiveStatus = "unverified-source-field" }
quests[50364] = { id = 50364, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Blut von Azeroth", description = "Wissen die Anführer der Allianz und der Horde überhaupt, worum sie da kämpfen?\n\nDie Substanz, die aus der Wunde austritt, ist das Lebensblut von Azeroth!\n\nWir müssen die Wunde heilen, statt sie für unsere Machtspiele auszubeuten! Azeroth ist die einzige Heimat, die wir haben. Wir dürfen nicht zulassen, dass sie stirbt!\n\nIch vertraue Euch, {name}, und ich weiß, dass Eure Meinung hohes Gewicht in der Horde hat. Ihr müsst sie zur Vernunft aufrufen.\n\nStoppt diesen Wahnsinn, oder es gibt keine Hoffnung für unsere Welt...", sourceObjective = "Überbringt Magni Bronzebarts Nachricht.", completion = "Das Blut von Azeroth? Hmpf.\n\nIch werde dafür sorgen, dass der Kriegshäuptling davon unterrichtet wird, aber diese Operation muss weiterlaufen, bis ich einen Befehl zum Abbruch erhalte!", sourceObjectiveStatus = "unverified-source-field" }
quests[50365] = { id = 50365, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Über alle Berge", description = "Die Stacheleber sind unruhig. Sie haben was Großes vor. Ihr müsst sie aufhalten!\n\nSie sammeln die ganze Zeit Vorräte und bringen sie in die Höhlen über ihrem Heiligtum. Konservierte Dornen, Kessel voller Gift, riesige Totems...\n\nSie bereiten sich auf einen Krieg vor.\n\nGeht da hoch und zerstört ihre Vorräte, bevor sie gegen die Einwohner des Tals eingesetzt werden können!", sourceObjective = "Vernichtet die Vorräte.", completion = "Der Verlust der Vorräte, die Ihr zerstört habt, sollte ein ziemlicher Rückschlag für sie sein. Sie müssen sie über längere Zeit angespart haben...", sourceObjectiveStatus = "unverified-source-field" }
quests[50367] = { id = 50367, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zorn in der Flasche", description = "<Die Flasche, die der Stacheleber bei sich hatte, enthält eine widerlich riechende, orangefarbene Flüssigkeit. Ihr seid nicht sicher, ob man sie gefahrlos trinken kann, aber es kann nicht schaden, ein paar Proben zu den Bürgern von Brennadam mitzunehmen.\n\nVielleicht kann ihr Alchemist ein Gegenmittel finden, um die Wirkung aufzuheben.>", sourceObjective = "Sammelt 10 stinkende Proben.", progress = "Habt Ihr etwas für mich?", completion = "Dieses Zeug riecht furchtbar. Vielleicht weiß Hobbs etwas damit anzufangen. Sobald wir hier raus sind, werde ich dafür sorgen, dass er die Proben erhält.", sourceObjectiveStatus = "unverified-source-field" }
quests[50368] = { id = 50368, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schrecken des Krals", description = "Bei allen Göttern der See, was für ein Ungeheuer!\n\nIch kann kaum glauben, was ich da sehe, {name}. Dieser Ettin wurde demselben Ritual unterzogen wie die anderen und er scheint noch zorniger zu sein! Wenn er es hier raus schafft, haben wir keine Chance.\n\nIch weiß, dass ich das Unmögliche verlange, aber ich muss darum bitten: Tötet dieses Monster und rettet das ganze Tal vor seinem Zorn! Hier, nehmt eine der Trankproben, die Ihr mir gebracht habt. Es ist vielleicht gefährlich, aber möglicherweise braucht Ihr sie, um diese Bestie zu bezwingen.", sourceObjective = "Besiegt Knirschfaust den Wahnsinnigen.", progress = "Wir müssen das Ding töten!", completion = "Es ist vollbracht! Ich hatte Angst, Ihr wärt erledigt, aber Ihr habt uns alle gerettet!", sourceObjectiveStatus = "unverified-source-field" }
quests[50369] = { id = 50369, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Braunbärgebräu" }
quests[50370] = { id = 50370, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tiefer in den Wald", description = "Wir müssen tiefer in den Wald. Die Hexen führen offensichtlich etwas noch Schlimmeres im Schilde, als ich mir ausgemalt hatte.\n\nEs ist zwar meine Pflicht, mit Meister Eschtal zu Lady Luzilla zurückzukehren, aber es ist ebenso meine Pflicht, mehr über diese Bedrohung für unser Volk zu erfahren und sie wenn möglich aufzuhalten.\n\nEs ist zwar ein Risiko, wenn wir uns weiter in den Wald hineinwagen, aber ich glaube, das ist es wert.", sourceObjective = "Reist mit Morgenlicht, Eschtal und Nezz tiefer in den Wald.", completion = "Beim Anker meiner Ahnen, was für eine enorme Armee! Wenigstens scheint sie noch nicht marschbereit zu sein. Und der Baum... auf den konzentrieren sie sich offenbar.", sourceObjectiveStatus = "unverified-source-field" }
quests[50371] = { id = 50371, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rückruf nach Sturmwind", description = "König Wrynn hat um Eure schnellstmögliche Rückkehr nach Sturmwind gebeten. Eine dringende Angelegenheit erfordert Eure Aufmerksamkeit.\n\nEinzelheiten erläutere ich bei Eurer Ankunft.\n\nTrefft mich bei der Löwenruh. Eile ist geboten, unser Zeitfenster könnte sich bereits schließen!", sourceObjective = "Trefft Euch mit Mathias Shaw in Sturmwind.", completion = "Endlich seid Ihr eingetroffen, {name}. Die Zukunft der Allianz könnte von dem abhängen, was ich Euch jetzt sage...", sourceObjectiveStatus = "unverified-source-field" }
quests[50372] = { id = 50372, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wüstenforschung", description = "Sargeras' dunkle Klinge hat einen Schatten der Zerstörung über das Land geworfen.\n\nBei dem Angriff scheinen die Silithidenschwarmstöcke zerstört worden zu sein, aber mich erreichen Berichte, dass die Silithiden zurückkehren.\n\nWir müssen in Erfahrung bringen, wie die Silithiden der Vernichtung entgangen sind und was die Klinge für eine Wirkung auf ihre Schwärme hat.\n\nDie Krone wünscht, dass die überlebenden Silithiden seziert und untersucht werden.\n\nTammy Tüfteldrall leitet die Untersuchung und braucht dringend jemanden, der \"Proben sammelt\".", sourceObjective = "Sprecht mit Tammy Tüfteldrall.", completion = "Seid Ihr hier, um die Proben zu sammeln? Dann lasst uns loslegen!", sourceObjectiveStatus = "unverified-source-field" }
quests[50373] = { id = 50373, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Wiedersehen", description = "Die Lage in Silithus scheint mehr Aufmerksamkeit auf sich zu ziehen.\n\nErzmagier Khadgar ist gerade angekommen, während Ihr weg wart. Er scheint wegen Euch hier zu sein, {name}.\n\nDie Angelegenheit ist wohl dringend. Ich würde Euch raten, schnellstmöglich mit ihm zu sprechen.", sourceObjective = "Sprecht mit Erzmagier Khadgar.", completion = "Es tut gut, Euch zu sehen, {name}. Ich wünschte, ich wäre unter besseren Umständen hier...", sourceObjectiveStatus = "unverified-source-field" }
quests[50374] = { id = 50374, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Blut von Azeroth", description = "Wissen die Anführer der Allianz und der Horde überhaupt, worum sie da kämpfen?\n\nDie Substanz, die aus der Wunde austritt, ist das Lebensblut von Azeroth!\n\nWir müssen die Wunde heilen, statt sie für unsere Machtspiele auszubeuten! Azeroth ist die einzige Heimat, die wir haben. Wir dürfen nicht zulassen, dass sie stirbt!\n\nIch vertraue Euch, {name}, und ich weiß, dass Eure Meinung hohes Gewicht in der Allianz hat. Ihr müsst sie zur Vernunft aufrufen.\n\nStoppt diesen Wahnsinn, oder es gibt keine Hoffnung für unsere Welt...", sourceObjective = "Überbringt Magni Bronzebarts Nachricht.", completion = "Das Blut von Azeroth? Ich werde dafür sorgen, dass Sturmwind davon unterrichtet wird, aber ich muss alle Operationen durchführen wie gehabt, bis ich neue Befehle erhalte!", sourceObjectiveStatus = "unverified-source-field" }
quests[50375] = { id = 50375, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reitet mit mir", sourceObjective = "Reitet auf Gonk, während er die Quelle der Verderbnis in der Nähe untersucht.", sourceObjectiveStatus = "unverified-source-field" }
quests[50376] = { id = 50376, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Seemannsgarn: Dicker Fisch", description = "Könnt Ihr die Dreistigkeit dieser Tunichtgute glauben? Nehmen die Steuerfrau von diesem Kai hier nicht ernst?\n\nPah!\n\nLeiht für einen Moment oder drei Euer Ohr. Ich hab eine Geschichte, die Bier in Euren Krug füllt und Euch in Euren Stiefeln erzittern lässt!\n\nEs war der größte, tödlichste Fang, den ich je auf den Wellen geplündert hatte...", sourceObjective = "Hört Euch die Geschichte von Steuerfrau Haken an.", completion = "Hört nicht auf sie. Jedes Wort ist wahr, wenn ich es doch sage!", sourceObjectiveStatus = "unverified-source-field" }
quests[50381] = { id = 50381, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der große Hutraub", description = "Händler reiten diese Straße lang. Sie transportier'n ihre Waren von ei'm Ort zum ander'n und füll'n sich die eig'nen Taschen.\n\n'n Anführer namens Tik'su war der Schlimmste von all'n. Er hat gepfefferte Preise verlangt und sogar Trolle mussten dabei nies'n!\n\nSein größter Stolz? Sein Hut.\n\nGeht und bringt ihm meine Botschaft, Zastamann. Jagt sei'm Reittier Angst ein, damit es Tik'su abwirft. Dann bringt mir sein'n Hut.", sourceObjective = "Stehlt erfolgreich Tik'sus Hut.\n\nWenn Ihr Eure Sauridenverkleidung verliert, kehrt zu Jani zurück und besorgt Euch eine neue.", progress = "Habt Ihr Euch schon mit Tik'su über sein'n Hut unterhalt'n, Zastamann?", completion = "Haha! Gut gemacht, Zastamann. Ihr habt Tik'sus Stolz verletzt... und sein'n Hintern. Der wird 'ne Weile wehtun. Ihr seid in meiner Gunst gestieg'n.", sourceObjectiveStatus = "unverified-source-field" }
quests[50385] = { id = 50385, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unermüdliche Bestimmung", description = "Ihr Griff lockert sich, aber nur kurz. Wir müssen diesen Ort zurückerobern!\n\nDie Höhlen in der Bucht sind von zappelnden, alptraumhaften Schrecken befallen. Nehmt die heiligen Segen. Wagt Euch in die Finsternis vor und findet ihre Altäre.\n\nSäubert unser Land von ihren lästerlichen Konstruktionen!", sourceObjective = "Läutert 3 versunkene Altäre.", completion = "Ein Sieg... vielleicht ein Wendepunkt.", sourceObjectiveStatus = "unverified-source-field" }
quests[50386] = { id = 50386, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Treibt sie davon", description = "Sie lauern in den Schatten der salzdurchtränkten Höhlen. Die dunkle Lake unter dem reinen Glanz der Oberfläche.\n\nIch habe sie gesehen. Sie quälen mich in meinen Träumen und ihr Flüstern ruft Wahnsinn hervor. Sie sprechen von ihrem Meister, der mit Klauen an der Barriere kratzt...\n\nSucht bei den Klippen nach ihren Höhlen. Findet das, was darin lauert, und löscht alles aus.", sourceObjective = "Untersucht und besiegt das, was in den 4 Bauten in der Vergessenen Bucht lauert.", completion = "Diese Dinger wurden vorerst zurückgedrängt.", sourceObjectiveStatus = "unverified-source-field" }
quests[50387] = { id = 50387, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schmuck und Tand", description = "Unterhalb der Gezeiten halten diese Schrecken es nicht für nötig, in ihren Labyrinthen zu bleiben.\n\nSie sind in die Nacht hinausgetreten, schleichen sich in die Dörfer und geben sich ihrer Gier hin. Sie werden die Vorräte gegen uns einsetzen und in ihren Ritualen nutzen. In Ritualen der Beschwörung und der Zwiesprache mit Mächten, deren Grauen unseren Verstand übersteigt.\n\nDie Bevölkerung ist nicht länger meine Sorge, aber ich will nicht miterleben müssen, dass diese salzigen Diebe damit durchkommen. Nehmt ihnen ihr Raubgut ab und erteilt ihnen eine bittere Lektion.", sourceObjective = "Bergt 3 Kisten mit gestohlenen Versorgungsgütern.", progress = "Ohne Gefahren gibt es keinen Ruhm.", completion = "Mit Blut bezahlt.", sourceObjectiveStatus = "unverified-source-field" }
quests[50388] = { id = 50388, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Last meines Ehrgeizes", description = "Genau wie die anderen Siedlungen war auch ich abhängig von den Diensten der Seeleute und Wasserfahrzeuge, um mit Vorräten beliefert zu werden. Sie waren durch ihren Pflichteifer und ihr Schweigen äußerst nützlich.\n\nWie nicht anders zu erwarten, erregten sie die Aufmerksamkeit von Feinden, einschließlich derer unterhalb der Wellen. Ihr Anker wurde verhext und sie wurden auf den Meeresgrund gezogen, bevor sie auch nur aufschreien konnten.\n\nIch sah, wie sie ihre ätherischen Segel hissten und die Seemannslieder der Verdammten sangen. Wenn diese Gewässer wieder sicher sein sollen, dann müssen sie erneut zum Schweigen gebracht werden. Für immer.", sourceObjective = "Besiegt den ertrunkenen Kapitän.", completion = "Und am Ende der Tod eines Seemanns.", sourceObjectiveStatus = "unverified-source-field" }
quests[50389] = { id = 50389, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bösartige Inspiration", description = "Vor langer Zeit gab es einmal eine Maid.\n\nEin altkluges Kind, das Lieder mochte. Sie machte es sich zum Steckenpferd, mir auf Schritt und Tritt zu folgen. Zunächst war das entzückend.\n\nSie lief am Rand des Kais entlang und verstrickte sich dabei in Seilen, die um einen höhnisch grinsenden Götzen lagen. In dem Moment erbebten die Wellen, gaben den beiden einen kleinen Stoß und sie versanken unter der Wasseroberfläche.\n\nIch höre immer noch ihr Lied. Zunächst dachte ich, es wäre eine vorübergehende Einbildung, Musik auf den Wellen. Jetzt habe ich erkannt, dass die Stimme einen finsteren Zweck verfolgt.\n\nSie muss sterben.", sourceObjective = "Tötet die verzaubernde Sirene.", completion = "Sie wurde zu ihrer Königin und ihrer Sklavin zugleich gemacht.", sourceObjectiveStatus = "unverified-source-field" }
quests[50391] = { id = 50391, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Seemannsgarn: Angeln mit Blei", description = "Haken hat sie nicht alle, das sage ich Euch. Haifische, die gemeinsam an etwas arbeiten... Pfui Teufel!\n\nDas erinnert mich an eine meiner Lieblingsgeschichten. Habe ich Euch jemals davon erzählt, wie ich DAS größte, tödlichste, mit den meisten Tentakeln bewehrte Biest in ganz Azeroth erwischt habe?!\n\nNein? Das dachte ich mir. Das ist keine Geschichte, die ich im nüchternen Zustand erzählen würde. Es war ein Tag wie kein anderer...", sourceObjective = "Hört Euch Meisterkanonier Schnurs Geschichte an.", progress = "Aye, mein Junge?", completion = "Ozumat ist nicht da, weil ich dem verfluchten Vieh in sein schleimiges Gesicht geschossen habe! Ich schwöre bei meinem Bart, dass jedes Wort wahr ist!", sourceObjectiveStatus = "unverified-source-field" }
quests[50393] = { id = 50393, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Spross von Pa'ku", description = "<Das Pterrordaxei ist warm und zittert. Es wird bald schlüpfen.>\n\nVielleicht kann Euch ein gewisser Pterrordaxloa helfen.", sourceObjective = "Bringt das Pterrordaxei zu Pa'ku auf der Pterrorhöhe.\n\nBereitgestellter Gegenstand:", completion = "Ein Ei? Es scheint nicht zu meiner Brut zu gehören.\n\nWo habt Ihr das gefunden?", sourceObjectiveStatus = "unverified-source-field" }
quests[50394] = { id = 50394, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jetzt Euer Problem", description = "Hm. Dieses Ei gehört nicht zu meiner Brut und meine Brutlinge brauchen keine weiteren Geschwister.\n\n<Pa'ku lächelt oder bleckt die Zähne. Zumindest sieht man verdammt viele ihrer Zähne.>\n\nIhr müsst Euch um den Kleinen kümmern und Euch damit beeilen.\n\nEr wird sehr bald schlüpfen.\n\nOh, noch ein kleiner Hinweis: Wenn Ihr wollt, dass der Kleine Euch mag, dann seid Ihr besser das Erste, was er sieht, nachdem er geschlüpft ist.", sourceObjective = "Bringt das Pterrordaxei in das leere Nest und wartet bis es schlüpft.", completion = "<Der winzige Pterrordax himmelt Euch an.>\n\nSkriiiii.", sourceObjectiveStatus = "unverified-source-field" }
quests[50395] = { id = 50395, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Ruf des Himmels", description = "<Kua'fon dreht seinen Kopf in Richtung der Klippen und zwitschert aufgeregt. Er breitet seine winzigen Schwingen aus und flattert heftig.>\n\nEs ist Zeit, das Nest zu verlassen.", sourceObjective = "Seht zu, wie Euer Jungtier seinen ersten Sprung in die große unbekannte Welt wagt.", completion = "Es tut mir leid, aber so spielt das Leben nun mal in den Himmeln. Nicht alle Jungtiere überleben, bis sie ausgewachsen sind.", sourceObjectiveStatus = "unverified-source-field" }
quests[50396] = { id = 50396, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pterrordaxschicksal", description = "<Kua'fon sieht sehnsüchtig zum Horizont und stößt einen scharfen Schrei aus.\n\nMan kann einen Pterrordax vom Himmel holen, aber man kann den Himmel nie aus seinem Herzen verbannen. Es ist Zeit, etwas zu tun.\n\nVielleicht kann Pa'ku Euch weiterhelfen.>", sourceObjective = "Bittet Pa'ku um Hilfe.", completion = "Gut, dass Ihr zu mir gekommen seid. Ich hatte schon überlegt, das Ding wieder aus dem Nest zu werfen.\n\nVielleicht gibt es noch eine andere Möglichkeit.", sourceObjectiveStatus = "unverified-source-field" }
quests[50397] = { id = 50397, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hochfliegende Ambitionen", description = "<Kua'fon mustert Euch eingehend. Ein einzelnes goldenes Auge bleibt unverwandt auf Euch fixiert.>\n\nSkrii.\n\n<Er richtet sein Maul dem Horizont entgegen und breitet seine Flügel weit aus.>\n\nSkrii!\n\n<Ist es endlich so weit?>", sourceObjective = "Fliegen?", completion = "<Kua'fon keucht.>", sourceObjectiveStatus = "unverified-source-field" }
quests[50401] = { id = 50401, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Angst vorm Fallen", description = "Einige Junge entdecken ihre Schwingen schneller als andere. Eures hatte zumindest so viel Gespür, sie offen zu halten.\n\nIch würde mir über seine Sicherheit keine allzu großen Sorgen machen. Diese Kleinen sind robuster, als man denkt.\n\nNach diesem Rückschlag muss das Junge es weiter versuchen und lernen, keine Angst vorm Fallen zu haben. Es ist Eure Aufgabe, ihm das beizubringen.\n\n<Der Loa lächelt Euch an und zeigt dabei all seine Zähne.>\n\nWenn es bockig wird, müsst Ihr es eben anders überzeugen.", sourceObjective = "Findet Euer Jungtier und überzeugt es, zum Nest zurückzukehren.", progress = "<Kua'fon zittert vor Angst zwitschert aufgeregt um Hilfe.\n\nEin kleines Leckerli kann Euer Jungtier vielleicht beruhigen.>", completion = "<Das Jungtier untersucht Eure Hände vorsichtig.>", sourceObjectiveStatus = "unverified-source-field" }
quests[50402] = { id = 50402, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "SKRIIIII!", description = "<Kua'fon starrt Euch einen Moment lang an, öffnet dann das Mäulchen und stößt ein langanhaltendes Kreischen aus.\n\nIhr braucht Hilfe.>", sourceObjective = "Findet heraus, was Euer Jungtier verstört, und kümmert Euch darum.", progress = "<Das Junge sucht Euch mit Blicken nach etwas Essbarem ab. Behaltet Eure Finger besser außer Reichweite.>\n\nSkrii!? Skrii!", completion = "<Kua'fon verschlingt das Dinofutter mit einem Bissen.>\n\nSkrii.", sourceObjectiveStatus = "unverified-source-field" }
quests[50412] = { id = 50412, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zurück ins Nest", description = "<Kua'fon schaut voller Vertrauen zu Euch auf.>\n\nJetzt wäre ein guter Zeitpunkt, ihn zum Nest zurückzutragen.", sourceObjective = "Bringt Kua'fon in sein Nest auf der Pterrorhöhe zurück.", completion = "<Das Junge lässt sich im Nest nieder.>\n\nSkrii.", sourceObjectiveStatus = "unverified-source-field" }
quests[50417] = { id = 50417, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Ruin ist über uns gekommen", description = "Unter den Wellen lauert ein Schrecken. Er will meine Familie, mein Haus und mein Vermächtnis auslöschen.\n\nIhr müsst kommen, Eurer Bestimmung folgen und uns von den Schrecken der Tiefe erlösen!\n\nFindet unser Anwesen im Osten auf den Inseln. Wir haben im Schatten der großen Festung ein luxuriöses Leben geführt. Wir glaubten, dass die Priester uns von der Dunkelheit unter uns erlösen würden. Jetzt ist diese Dunkelheit an die Oberfläche gestiegen und flüstert uns in unseren Träumen Wahnsinn ein.\n\nBeeilt Euch. Die Luft ist finsterer, als ich sie je in meinem verfluchten Leben gesehen habe.", sourceObjective = "Findet den Verfasser des geheimnisvollen Briefs.", completion = "Ihr habt den Brief beantwortet. Jetzt seid Ihr an diesen Ort gebunden.", sourceObjectiveStatus = "unverified-source-field" }
quests[50418] = { id = 50418, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Seemannsgarn: Sinken und Schwimmen", description = "Mpf mpf!\n\nMpf mpf mpf mpf mpf. Mpf mpf mpf.\n\nMpf.\n\nMpf mpf? Mpf!", sourceObjective = "\"Hört\" \"Senkblei\" bei seiner \"Geschichte\" zu.", completion = "Mpf mpf mpf. Mpf.", sourceObjectiveStatus = "unverified-source-field" }
quests[50420] = { id = 50420, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein leicht geschütteltes Geschenk" }
